\label{lem:HS}
		For each  $g\in \mathcal H_{K}$,
		$\Gamma_g$ is a Hilbert-Schmidt operator from 
		$Q^{1/2}\tilde{\mathcal H}_{K}$
		to $\mathbb R$ satisfying that, for any orthonormal basis  $(\eta_i)_{i\in I}$ of 
		$Q^{1/2}\tilde{\mathcal H}_{K}$,

		\[
			\|\Gamma_g\|^2_{\mathcal L^{\mathrm{HS}}_{Q^{1/2}\tilde{\mathcal H}_{K}}}
			:=\sum_{i\in I} |\Gamma_g \eta_i|^2 
			= \Norm*{Q^{1/2}[g]_K}^2_{\tilde{\mathcal H}_{K}} 
			\leq \|Q^{1/2}\|^2 \|g\|^2_{\mathcal H_{K}}
		\]

\label{thm:main2}
		Let $({\mathbb X}, d,m)$ be a metric measure space such that \eqref{ineq:entropy bound} is satisfied. 
		Let the stochastic basis $(\Omega, \mathscr{F}, (\mathscr{F}_t)_{t\geq 0}, \mathbb P, W)$, drift coefficient $b$, noise coefficient
		$\sigma$, and the initial value $f$ be given as in \eqref{eq:SB}--\eqref{eq:IV}.
        Suppose
		$\mathcal L$ admits a heat kernel $\{G_t(x, y)\}_{t>0,x,y\in{\mathbb X}}$ (with respect to the Radon measure $m$) that satisfies \eqref{cond:ctem continuous},
		\eqref{cond:exp_hk_lamda} and
		\eqref{cond:time_holder}.
		Suppose
		the existence of
		a $\mathbb P$-null subset $\mathrm N_{\refstepcounter{c}{\thec}\label{c:Lip}}$ of $\Omega$ s.t.
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:LiG}]
			(linear growth condition)
			for any $T>0$, uniformly for
			$\omega \in \Omega \setminus \mathrm N_{\ref{c:Lip}}$,
			$(t,x) \in [0,T] \times {\mathbb X}$ and $u \in \mathbb{R}$,
			\begin{equation}
				|b(\omega, t,x,u) |+|\sigma(\omega, t,x,u)| \lesssim 1+|u|;
				\quad \text{and}
			\end{equation}
		\end{itemize}
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{ineq:g_lip}]
			(Lipschitz condition)
			for any $T>0$, uniformly for
			$\omega \in \Omega \setminus \mathrm N_{\ref{c:Lip}}$,
			$(t,x) \in [0,T] \times {\mathbb X}$ and $u,v \in \mathbb{R}$,
			\begin{equation}
				|b(\omega, t,x,u) - b(\omega, t,x,v)|+|\sigma(\omega, t,x,u)- \sigma(\omega, t,x,v)| \lesssim |u - v|.
			\end{equation}
		\end{itemize}
		Then, there exists a 
		mild-solution $(u_t)_{t\geq 0}$ to the SPDE \eqref{eq:spde}, and the solution is unique up to indistinguishability.

\label{thm:comparison}
		Suppose the same assumptions as in Theorem \ref{thm:main2} hold. Let $(u_t)_{t\ge 0}$ and $(u'_t)_{t \ge 0}$ be the mild-solutions with initial conditions $u_0=f\in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ and  
        $u_0' = f' \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ respectively.
		\begin{enumerate}
			\item \label{part:main2 weak comparison} (Comparison principle)
			Suppose  \eqref{cond:hk_uni_bound} and \eqref{eq:con}  hold. If
			$f(x) \ge f'(x)$ for  $x \in {\mathbb X}$, then ${\mathbb P}\bigl(u_t(x)\ge u'_t(x)\ \text{for all }t\ge 0 \text{ and } x\in{\mathbb X}\bigr)=1$.
			\item \label{part:main2 strong comparison}
			(Strong comparison principle) Suppose   \eqref{cond:hk_uni_bound}, \eqref{ineq:instant_propagation} and \eqref{eq:con}    hold. If $f(x) \ge f'(x)$ for  $x \in {\mathbb X}$ and $f(x_0) >f'(x_0)$ for some $x_0 \in {\mathbb X}$,
			then ${\mathbb P}\bigl(u_t(x)> u'_t(x)\ \text{for all }t> 0 \text{ and } x\in{\mathbb X}\bigr)=1$.
			\item  \label{part:main2 strictly positivity}
			(Strict positivity)
			Suppose   \eqref{cond:hk_uni_bound}, \eqref{ineq:instant_propagation} and \eqref{eq:con}    hold, and that almost surely,
			\begin{align}\label{cond:pos_zero}
				b(t,x,0) \ge 0\quad \text{ and }\quad \sigma(t,x,0) = 0 \quad\text{for all }(t,x) \in \mathbb{R}_+ \times {\mathbb X}.
			\end{align}
            If $f$ is non-negative and $f(x)>0$ for some $x\in {\mathbb X}$, then 
                        ${\mathbb P}\bigl(u_t(x)> 0\ \text{for all }t> 0 \text{ and } x\in{\mathbb X}\bigr)=1$.
		\end{enumerate}

\label{Eg:PolySubGaussianHK}
		In many standard examples we have $\Psi(r)\asymp r^{d_w}$ for some $d_w \ge 2$ and $V(r) \asymp r^{d_h}$ for some $d_h \ge 1$; in that case this setting corresponds to the usual sub-Gaussian heat kernel estimate. Examples include
		\begin{itemize}
			\item  $\mathbb{R}^n$ with the usual Gaussian heat kernel, in which case $d_h = n$ and $d_w = 2$. 
			\item  metric graphs with volume doubling property, with $d_h = 1$ and $d_w = 2$;  see \cite{MR4278798}. 
			\item (Unbounded) Sierpi\'{n}ski gasket in $\mathbb{R}^n$ with $d_h = \log_2(n+1)$ and $d_w = \log_2(n+3)$; see \cites{barlow1988brownian,barlow1998diffusions}.
		\end{itemize}

		Under these choices of $\Psi$ and $V$, the standing assumptions in Section~\ref{sec:backgroup_setups} are satisfied when the parameters meet appropriate conditions (see Appendix~\ref{sec:appendix}). In particular, for white noise ($\gamma=0$) one needs $d_h<d_w$; for colored noise $K_\gamma$, the condition reads
		\[
		\frac{d_h}{d_w} > \gamma > \max\Braces*{0,\frac{d_h}{d_w}-1}{,}
		\]
		which is consistent with the conditions for the resolvability of Parabolic Anderson models in \cite[Theorem 1.1]{Zbl08159034}  and the discussion thereafter.

\label{prop:fractionalPAM}
		Let $({\mathbb X},d,m,\mathcal E,\mathcal F)$, $\mathcal L$ and $1 \le d_h \le d_w$ be as above and let $\beta \in (d_h/d_w, 1)$.
		Fix an $x_0 \in {\mathbb X}$ and let $h(x):= 1+d(x_0,x)$ and let $\dot{W}$ be the space-time white noise on $\mathbb{R}_+\times {\mathbb X}$.
		For any $u_0 \in \mathcal C^{\mathrm{tem},+}_{{\mathbb X},h}$ that is not identically zero, there exists a unique solution to
		\begin{equation}\label{eq:fractionalPAM}
			\partial_t u = -(-\mathcal L)^\beta u + u \dot{W},\qquad u(0,\cdot) = u_0.
		\end{equation}
		Furthermore, $\mathbb P \left(u(t,x)>0 \,\text{ for }\, t>0,\, x \in {\mathbb X} \right) =1$.

\label{prop:local_manifolds}
Suppose $({\mathbb X},d,m)=(M,d_g,m)$ and $\mathcal L=\tfrac12\Delta_M$ are the Riemannian manifold and operator  described above  such that \eqref{eq:manifold_gaussian} holds.
Suppose the function $h$, the constant $\gamma$ and the measure $K$ are as in the paragraph containing \eqref{eq:manifold_gamma}-\eqref{eq:manifold_covariance}.
Then, $(M,d,m)$ satisfies \eqref{ineq:entropy bound}, $h$ satisfies \eqref{ineq:faster_than_ms} and \eqref{ineq:ref_regular}, the heat semigroup $(P_t)_{t\geq0}$ is Feller, $K$ is a symmetric, non-negative definite Radon measure, and \eqref{cond:ctem continuous}, \eqref{cond:time_holder}{,}
\eqref{cond:exp_hk_lamda}{, \eqref{cond:hk_uni_bound} and \eqref{ineq:instant_propagation}} are all satisfied.

\label{cor:mtg+mink_cs}
		Suppose that $(\Omega, \mathscr{F}, (\mathscr{F}_t)_{t\geq 0}, \mathbb P, W)$ is a stochastic basis given as in \eqref{eq:SB}. 
		Then for every $p\geq 2$, uniformly for every $t\geq 0$ and real-valued predictable random field $(\Phi(s,y))_{s\geq 0, y\in {\mathbb X}}$ 
		such that 
		\[
		\|\Phi\|_{L_{[0,t]}^2 \mathcal H_{K} L^p_\Omega} :=\left(\int_0^t \left\|\left\|\Phi(s,\cdot)\right\|_{L^p_{\Omega}}\right\|_{\mathcal H_{K}}^2 \mathrm ds \right)^\frac{1}{2} < \infty, 
		\]
		we have
		\begin{align}\label{ineq:mtg+mink+cs}
			\left\|\iint_0^t \Phi(s,y)W(\mathrm ds,\mathrm dy)\right\|_{L^p_\Omega} 
			\lesssim \|\Phi\|_{L_{[0,t]}^2 \mathcal H_{K} L^p_\Omega}.
		\end{align}

\label{lem:hk longtime}
		Suppose that $\lambda \in \mathbb{R}$ and 
		$\tilde \alpha \in (0,1)$ satisfy \eqref{cond:exp_hk_lamda} with $\alpha$ being replaced by $\tilde \alpha$,
		then there exist $\kappa, \tilde \kappa >0$ so that 
		uniformly for every $t>0$ and $x\in {\mathbb X}$,
		\begin{align}\label{ineq:hk_m long time}
			\| G_t(\cdot,x)h(\cdot)^\lambda\|_{L^1_{\mathbb X}} \lesssim e^{\kappa t}h(x)^\lambda,
		\end{align}
		and
		\begin{align}\label{ineq:hk_k long time}
			\| G_t(\cdot,x)h(\cdot)^\lambda\|_{\mathcal H_{K}}^2 
			\lesssim t^{-\tilde \alpha}
			e^{\tilde \kappa t}h(x)^{2\lambda}.
		\end{align}
		Let $\beta\in [0,1)$ and $\xi_1,\xi_2>0$ be given as in \eqref{cond:time_holder}. For each $T>0$, it holds uniformly in $t,t' \in (0,T]$ and $x \in {\mathbb X}$ that
		\begin{align}\label{ineq:time_holder_long_time}
			\Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x)}_{L^1_{\mathbb X}} \lesssim  \frac{\Absolute*{t-t'}^{\xi_1 \wedge 1}}{\Parentheses*{t\wedge t'}^\beta}.
		\end{align}
		Moreover, it holds uniformly in $t\in(0,T]$ and $x,x'\in{\mathbb X}$ with $d(x,x')\le1$ that
		\begin{align}\label{ineq:spatial_holder_long_time}
			\Norm*{G_t(\cdot,x)-G_t(\cdot,x')}_{L^1_{\mathbb X}}
			\lesssim \frac{d(x,x')^{\xi_2}}{t^\beta}.
		\end{align}

\label{lem:hk_abs}
		Let $\xi_1,\, \xi_2 \in (0,1]$ be as in \eqref{cond:time_holder}, then
		for any $T>0$ and $\lambda \in [0,1/2]$, it holds uniformly for 
		$t,t'$ in $[0,T]$
		and  $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$,
		that 
		\begin{align}
			h(x)^{-\lambda}\| h(\cdot)^{\lambda}\Parentheses*{G(\cdot,\cdot;t,x) - G(\cdot, \cdot; t', x')} \|_{L^1_{[0,T)} L^1_{\mathbb X}}
			\lesssim  |t-t'|^{{{\xi_1 \wedge 1}\over 2}} + d(x,x')^{{\xi_2 \over 2}\wedge 1}. \label{ineq:hk abs holder m}
		\end{align}
		Let $\alpha\in (0,1)$ and $\beta \in [0,1)$ be as in \eqref{cond:exp_hk_lamda} and \eqref{cond:time_holder} respectively.  
		There exist $\widetilde \xi_1,\widetilde \xi_2 \in (0,1)$, so that for every $\lambda_1\in[0,1/2]$ and $T>0$,
		it holds uniformly for $t,t'$ in $[0,T]$ and  $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ that
		\begin{align}
			h(x)^{-2\lambda_1}\| h(\cdot)^{\lambda_1}\Absolute*{G(\cdot,\cdot;t,x) - G(\cdot, \cdot; t', x') }\|^2_{L^2_{[0,T)}\mathcal H_{K}}
			\lesssim |t-t'|^{2\widetilde \xi_1} + d(x,x')^{2\widetilde \xi_2}. \label{ineq:hk abs holder k}
		\end{align}
		Moreover, there exist $\xi\in(0,1]$ and $\alpha_0\in(0,1)$ such that, for every $\lambda\in[0,1/2]$ and $T>0$, uniformly for $x,x'\in{\mathbb X}$ with $d(x,x')\le1$ and $0\le t\le t'\le T$,
		\begin{align}
			\int_0^{t'}\left\|\left|G_{t-s}(\cdot,x)-G_{t'-s}(\cdot,x')\right|h(\cdot)^\lambda\right\|_{\mathcal H_K}^2\,\mathrm ds
			\lesssim t'^{1-\alpha_0}\left(|t-t'|^\xi+d(x,x')^\xi\right)h(x)^{2\lambda}.
			\label{ineq:hk abs holder k weighted}
		\end{align}

\label{lem:PsiM}
		Suppose that both $(B, \Sigma)$ and $(B', \Sigma')$ are Duhamel-integrable pairs. Then 
		\begin{itemize}
			\item $\Psi_1(B')$ is a modification of $\Psi_1(B)$ provided $B'$ is a predictable modification of $B$; 
			\item $\Psi_2(\Sigma')$ is a modification of $\Psi_2(\Sigma)$ provided $\Sigma'$ is a predictable modification of $\Sigma$.
		\end{itemize}

\label{lem:b_contract_combined}
		Let $\lambda \ge0$ and $\tilde \alpha \in (0,1)$ satisfy \eqref{cond:exp_hk_lamda} with $\alpha$ being replaced by $\tilde \alpha$.
		Let $p \ge 2$ and $g \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$. When $\lambda=0$, assume in addition that $g\in\mathcal C_{\mathbb X}^{\mathrm b}$. For each $U \in \mathbb M_{\lambda,p}$ and $(t,x) \in [0,T]\times {\mathbb X}$, define
		\begin{equation}\label{eq:BuSu}
			B_U(t,x):= b(t,x,U(t,x)),\qquad \Sigma_U(t,x):= \sigma(t,x,U(t,x)).
		\end{equation}
		Then  for each $U\in \mathbb M_{\lambda,p}$, $(B_U,\Sigma_U)$ is a Duhamel-integrable pair, and  $\Psi(g,B_U,\Sigma_U) \in \mathbb M_{\lambda,p}$.
		Moreover,
		uniformly in $ U,\, V \in \mathbb M_{\lambda, p }$, $A\ge 1$ and $g \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$, we have 
		\begin{align}
			\Norm*{\Psi(g,B_U,\Sigma_U) - \Psi(g,B_V, \Sigma_V)}_{\mathbb M_{\lambda, p, A}} 
			\lesssim  A^\frac{\tilde \alpha - 1}{2} 
			\Norm*{U - V}_{\mathbb M_{\lambda, p, A}}.
		\end{align}

\label{prop:wellposted}
		Suppose that  $\lambda \in (0,1]$ (or $\lambda=0$ if $f\in\mathcal C^{\mathrm b}_{\mathbb X}$) and $p \ge 2$. Then there exists a $U \in \mathbb M_{\lambda,p}^f$, unique up to predictable modification,
		such that $\Phi(U)$ is a  predictable modification of $U$.

From \eqref{eq:pp}, we know that $\Phi(U) \in \mathbb M_{\lambda,p}$.
		Note that for any $U \in \mathbb M_{\lambda,p}^{ f}$,
		\begin{equation}
			\Phi(U)(0,x)
			= \Psi(f, B_U, \Sigma_U)(0,x) 
			= f(x), \quad x\in {\mathbb X}.
		\end{equation}
		Therefore, 
		$\Phi: U \mapsto \Phi(U)$ is a map from $\mathbb M_{\lambda,p}^{f}$ to $\mathbb M_{\lambda,p}^{f}$.
		From Lemma \ref{lem:PsiM} and \eqref{eq:Modification} we can verify that, for any $U \in \mathbb M_{\lambda,p}^{f}$
		and any 
		predictable
		modification $U'$ of $U$, $\Phi(U')$ is a 
		predictable
		modification of 
		$\Phi(U)$.
		Therefore, we can define a map $\Phi^\sharp$ from $\mathbb M_{\lambda,p}^{\sharp,f}$ to $\mathbb M_{\lambda,p}^{\sharp,f}$ such that 
		\begin{equation}\label{eq:Phisharp}
			\Phi^\sharp([U]_{\mathrm{p}}) = [\Phi(U)]_{\mathrm{p}}, \quad \forall U\in \mathbb M^f_{\lambda, p}.
		\end{equation}
		Recall that $\alpha\in (0,1)$ is given by \eqref{cond:exp_hk_lamda}.
		Note that uniformly for $A\ge 1$ and $U,V \in \mathbb M_{\lambda,p}^f$,
		\begin{align}\label{eq:PhiD}
			&\|\Phi(U) - \Phi(V)\|_{\mathbb{M}_{\lambda,p,A}} 
			=\Norm*{\Psi(f,B_U,\Sigma_U) - \Psi(f, B_V, \Sigma_V)}_{\mathbb M_{\lambda, p, A}} 
			\\&\overset{\text{Lemma \ref{lem:b_contract_combined}}}\lesssim A^{\frac{\alpha - 1}{2}} \|U - V\|_{\mathbb{M}_{\lambda,p,A}}. 
		\end{align}
		From the fact that $\alpha \in (0,1)$, there exists a large $A_0>0$ such that for any $A\geq A_0$ and $U,V \in \mathbb M_{\lambda,p}^{f}$,
		\begin{equation} \label{eq:PC}
			\|\Phi(U) - \Phi(V)\|_{\mathbb{M}_{\lambda,p,A}} \leq \frac{1}{2}\|U-V\|_{\mathbb{M}_{\lambda,p,A}}.
		\end{equation}

		Now, for any $A\geq A_0$ and $\mathbf U, \mathbf V$ in $\mathbb M_{\lambda,p}^{\sharp,f}$, taking representatives $U\in \mathbf U\cap\mathbb M_{\lambda,p}^f$ and $V\in \mathbf V\cap\mathbb M_{\lambda,p}^f$ respectively, it holds that 
		\begin{align}
			&d_{\lambda,p, A}\Parentheses*{\Phi^\sharp(\mathbf U), \Phi^\sharp(\mathbf V)} 
			= \Norm*{\Phi^\sharp([U]_{\mathrm{p}}) - \Phi^\sharp([V]_{\mathrm{p}})}_{\mathbb{M}_{\lambda,p,A}^{\sharp}} 
			\\&\overset{\eqref{eq:Phisharp}}{=} \Norm*{ [\Phi(U)]_{\mathrm{p}} - [\Phi(V)]_{\mathrm{p}} }_{\mathbb{M}_{\lambda,p,A}^{\sharp}} 
			=\Norm*{ [\Phi(U) - \Phi(V)]_{\mathrm{p}} }_{\mathbb{M}_{\lambda,p,A}^{\sharp}} 
			\\&\overset{\eqref{eq:NormSharp}}{=} \left\| \Phi(U) - \Phi(V)\right\|_{\mathbb{M}_{\lambda,p,A}}  
			\overset{\eqref{eq:PC}}\leq \frac{1}{2}\left\|U-V\right\|_{\mathbb{M}_{\lambda,p,A}}
			\overset{\eqref{eq:NormSharp}}{=} \frac{1}{2}\left\|[U-V]_{\mathrm{p}}\right\|_{\mathbb{M}_{\lambda,p,A}^\sharp}
			\\&= \frac{1}{2}\left\|[U]_{\mathrm{p}}-[V]_{\mathrm{p}}\right\|_{\mathbb{M}_{\lambda,p,A}^\sharp}
			=  \frac{1}{2}d_{\lambda,p, A}\Parentheses*{\mathbf U, \mathbf V} .
		\end{align}

		Now noticing Lemma \ref{lem:CMS}, $\Phi^\sharp$ is a contraction map from the complete metric space $(\mathbb{M}_{\lambda,p}^{\sharp,f}, d_{\lambda,p,A})$ to $( \mathbb{M}_{\lambda,p}^{\sharp,f}, d_{\lambda,p,A})$ for every $A\geq A_0$. 
		By the Banach fixed-point theorem, 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:UMf}] there exists a unique element $\mathbf U$ in $\mathbb{M}_{\lambda,p}^{\sharp,f}$ such that $\Phi^\sharp(\mathbf U) = \mathbf U$.
		\end{itemize}
		Let $U\in \mathbf U\cap \mathbb M_{\lambda,p}^f$ be a representative of the $\mathbf U$ in \eqref{eq:UMf}, then by \eqref{eq:Phisharp}, $[\Phi(U)]_{\mathrm{p}} = [U]_{\mathrm{p}}$. This proves the existence part of the desired result.
		Suppose that there is any other $U'\in \mathbb M_{\lambda,p}^f$ such that $[\Phi(U')]_{\mathrm{p}} = [U']_{\mathrm{p}}$, then by \eqref{eq:Phisharp}, $\Phi^\sharp([U']_{\mathrm{p}}) = [U']_{\mathrm{p}}$, and by \eqref{eq:UMf}, $[U']_{\mathrm{p}} = [U]_{\mathrm{p}}$.
		This proves the uniqueness part of the desired result. We are done.

\label{prop:existence of C_tem modification}
		Suppose that $U \in \mathbb M^{f}$ is  the random field given as in Corollary  \ref{cor:MfT},
		then $U$ admits a  predictable modification $\tilde U$ taking values in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.  In addition, $\Phi(U)$ admits a modification in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ and  there exists $\xi \in (0,1)$ so that for any $T>0$, $p \ge 2$ and $\lambda \in (0,1]$, it holds uniformly in $t,t'\in [0,T]$, $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$, 
		\begin{align}
			&\Norm*{\Psi_1(B_U)(t,x) - \Psi_1(B_U)(t',x')}_{L^p_\Omega}+\Norm*{\Psi_2(\Sigma_U)(t,x) - \Psi_2(\Sigma_U)(t',x')}_{L^p_\Omega} \\
			&\lesssim \Parentheses*{|t-t'|^\xi +d(x,x')^\xi }h(x)^\lambda.
		\end{align}

\setcounter{step}{0}\refstepcounter{step}\emph{Step \thestep. }
		Notice that $U$ is the predictable modification of 
		\begin{equation}\label{eq:PhiU}
			\Phi(U) := \Psi_0(f) + \Psi_1(B_U) + \Psi_2(\Sigma_U).
		\end{equation}
		To prove the desired result for this proposition, we only need to show that each term on the right hand side of \eqref{eq:PhiU} admits a modification taking values in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.
		In fact, if this has been shown, then $\Phi(U)$ admits a modification $\tilde \Phi(U)$ taking values in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$. 
		And since the continuous random field $\tilde \Phi(U)$ is predictable, by \eqref{eq:Modification}, it is also a predictable modification of both $\Phi(U)$ and $U$. 


		\refstepcounter{step}\emph{Step \thestep. }
		From \eqref{cond:ctem continuous}, we know that $\Psi_0(f)$ takes values in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ already.

		\refstepcounter{step}\emph{Step \thestep. }
		We will show that $\Psi_1(B_U)$ admits a 
		modification taking values in $\mathcal C_{[0,T]} \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.
		Let $\xi_1, \xi_2$
		be the constants given as in 
		\eqref{cond:time_holder}.
		Let $\lambda_0 \in [0,1]$ (where $\lambda_0=0$ is allowed only if $f\in\mathcal C^{\mathrm b}_{\mathbb X}$, in which case $U\in\mathbb M_{0,p}$ by Corollary~\ref{cor:MfT}) and $p \geq 2$ be arbitrary. 
		Define $\lambda := \lambda_0 / p \in [0,1/2]$. 
		Note that uniformly  for $(s,y)\in [0,T]\times {\mathbb X}$ and $\omega \in \Omega\setminus \mathrm N_{\ref{c:Lip}}$, 
		\begin{align}
			\Absolute*{B_U(s,y)} + \Absolute*{\Sigma_U(s,y)}&= \Absolute*{b(s,y, U(s,y))} 
			+ \Absolute*{\sigma(s,y,U(s,y))}
			\\&{\overset{\eqref{eq:LiG}}\lesssim} 1 + |U(s,y)|. \label{eq:BUles}
		\end{align}
		Therefore, we have the existence of a $\Lambda\otimes m$-null subset $\mathrm N_{\refstepcounter{c}{\thec}\label{c:BUh}}$ of $[0,T]\times {\mathbb X}$ such that uniformly for every $(s,y)\in [0,T]\times {\mathbb X}\setminus \mathrm N_{\ref{c:BUh}}$, 
		\begin{align}
			&\Norm*{B_U(s,y)}_{L^p_\Omega} 
			\overset{\eqref{eq:BUles}}{\lesssim} \Norm*{1 + |U(s,y)|}_{L^p_\Omega} 
			\overset{\text{Minkowski}}\leq 1 + \Norm*{U(s,y)}_{L^p_\Omega}
			\\& \leq h(y)^{\lambda} + \Norm*{U}_{\mathbb M_{\lambda, p}} h(y)^{\lambda}
			\lesssim h(y)^{\lambda}. \label{eq:BUp}
		\end{align}

		Uniformly for every $t,t'\in [0,T]$ and $x,x'\in {\mathbb X}$ with $d(x,x') \le 1$,
		\begin{align}
			& \mathbb E\left[\left|\Psi_1(B_U)(t,x) - \Psi_1 (B_U)(t',x')\right|^p\right]^{\frac{1}{p}} = \left\|\Psi_1(B_U)(t,x) - \Psi_1 (B_U)(t',x')\right\|_{L^p_\Omega} 
			\\&= \left\| \int_0^T \mathrm ds \int_{\mathbb X} \left(G(s,y;t,x) - G(s,y;t',x')\right) B_U(s,y) m(\mathrm dy)\right\|_{L^p_\Omega} 
			\\&\overset{\text{Minkowski}}\le  \left\| \left| G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')\right| \left\|B_U(\cdot,\cdot)\right\|_{L^p_\Omega} \right\|_{L^1_{[0,T]\times{\mathbb X}}}
			\\&\overset{\eqref{eq:BUp}} \lesssim \Norm*{\Absolute*{G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')}h(\cdot )^\lambda }_{L^1_{[0,T]\times {\mathbb X}}} 
			\\&\overset{\text{Lemma \ref{lem:hk_abs} }}\lesssim  \Parentheses*{\Absolute*{t-t'}^{\Parentheses*{\xi_1 \wedge 1}\over 2} +  d(x,x')^{\frac{\xi_2}{2}\wedge 1} }h(x)^\lambda 
			\\&= \Parentheses*{\Absolute*{t-t'}^{\Parentheses*{\xi_1 \wedge 1}\over 2} +  d(x,x')^{\frac{\xi_2}{2}\wedge 1} }h(x)^{\lambda_0/p}     
		\end{align}
		Since $\Psi_1(B_U)(0,\cdot) \equiv 0$ is deterministic, and since $p\geq 2$ and $\lambda_0 \in (0,1]$ are chosen arbitrarily, from Lemma \ref{lem:tight_tem_moment}, $\Psi_1(B_U)$ admits a modification taking values in  $\mathcal C_{[0,T]} \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ as desired for this step.

		\refstepcounter{step}\emph{Step \thestep. } We will show that $\Psi_2(\Sigma_U)$ admits a predictable modification taking values in $\mathcal C_{[0,T]} \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.
										Let $\lambda_0 \in [0,1]$ (where $\lambda_0=0$ is allowed only if $f\in\mathcal C^{\mathrm b}_{\mathbb X}$, in which case $U\in\mathbb M_{0,p}$ by Corollary~\ref{cor:MfT}) and $p\geq 2$ be arbitrary.
		Take $\lambda_1:=\lambda_0/p\in[0,1/2]$ with $p\lambda_1 \leq \lambda_0$.
		Pay attention that \eqref{cond:exp_hk_lamda} holds with $\lambda$ being replaced by $\lambda_1$.

		Uniformly for every $(t,x)$ and $(t',x')$ in $[0, T]\times {\mathbb X}$, we have
		\begin{align}
			&\mathbb E\left[\left|\Psi_2(\Sigma_U)(t,x) - \Psi_2(\Sigma_U)(t',x')\right|^p \right]^{1/p}
			\\&= \Norm*{\iint_0^T \Parentheses*{G(s,y;t,x)-G(s,y;t',x')} \Sigma_U(s,y)W(\mathrm ds, \mathrm dy)}_{L^p_\Omega}
			\\&\overset{\text{Lemma \ref{cor:mtg+mink_cs}}} \lesssim \left\|\left(G(\cdot, \cdot;t,x) - G(\cdot,\cdot;t',x')\right)  \Sigma_U \right\|_{L^2_{[0,T]} \mathcal H_K L_\Omega^p}
			\\&=\Parentheses*{\int_0^T \Norm*{
					\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} 
					\Norm*{\Sigma_U(s,\cdot)}_{L^p_\Omega}
				}_{\mathcal H_K}^2\mathrm ds}^{1/2}. \label{ineq:continuity stochastic part }
		\end{align}
		Note that we have the existence of a $\Lambda \otimes K$-null subset $\mathrm N_{\refstepcounter{c}{\thec}\label{c:SigmaNull}}$ of $[0,T]\times {\mathbb X}^2$ such that uniformly for every $(s,x,y)\in [0,T]\times {\mathbb X}^2 \setminus {\mathrm N_{\ref{c:SigmaNull}}}$, 
		\begin{align}
			\Norm*{\Sigma_U(s,x)}_{L^p_\Omega} \cdot \Norm*{\Sigma_U(s,y)}_{L^p_\Omega} 
			&{\overset{\eqref{eq:BUles}}{\lesssim}} \Norm*{1 + |U(s,x)|}_{L^p_\Omega} \cdot \Norm*{1 + |U(s,y)|}_{L^p_\Omega}
			\\& {\overset{\text{Minkowski}}\leq} \Parentheses*{ 1 + \Norm*{U(s,x)}_{L^p_\Omega}} \cdot \Parentheses*{ 1 + \Norm*{U(s,y)}_{L^p_\Omega}}
			\\& \leq \Parentheses*{h(x)^{\lambda_1} + \Norm*{U}_{\mathbb M_{\lambda_1, p}} h(x)^{\lambda_1}}\cdot \Parentheses*{h(y)^{\lambda_1} + \Norm*{U}_{\mathbb M_{\lambda_1, p}} h(y)^{\lambda_1}}\\
			&\lesssim h(x)^{\lambda_1} h(y)^{\lambda_1}. \label{eq:SUp}
		\end{align}
		Therefore, uniformly for every $(t,x)$ and $(t',x')$ in $[0, T]\times {\mathbb X}$ with $d(x,x') \le 1$, we have
		\begin{align}
			&\mathbb E\left[\left|\Psi_2(\Sigma_U)(t,x) - \Psi_2(\Sigma_U)(t',x')\right|^p \right]^{1/p}
			\\&\overset{\eqref{ineq:continuity stochastic part }}\lesssim \Parentheses*{\int_0^T \Norm*{
					\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} 
					\Norm*{\Sigma_U(s,\cdot)}_{L^p_\Omega}
				}_{\mathcal H_K}^2\mathrm ds}^{1/2}
			\\&\overset{\eqref{eq:SUp}}\lesssim \Parentheses*{\int_0^T \Norm*{
					\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} 
					h(\cdot)^{\lambda_1}
				}_{\mathcal H_K}^2\mathrm ds}^{1/2}
			\\& \overset{\text{Lemma \ref{lem:hk_abs} }}\lesssim  h(x)^{\lambda_1} \Parentheses*{\Absolute*{t-t'}^{\widetilde \xi_1} + d(x,x')^{\widetilde \xi_2}} 
			\lesssim 
			h(x)^{\lambda_0/p}
			\Parentheses*{\Absolute*{t-t'}^{\widetilde \xi_1} + d(x,x')^{\widetilde \xi_2}}
		\end{align}
		for some $\widetilde\xi_1,\, \widetilde\xi_2 \in(0,1]$, where we used the fact that 
		$h(x) \ge 1$ for all 
		$x \in {\mathbb X}$ and $p\lambda_1 \leq \lambda_0$ in the last line.
		Since $\Psi_2(\Sigma_U)(0,\cdot) \equiv 0$ is deterministic, and since $p \ge 2$ and $\lambda_0\in (0,1]$ 
		were
		chosen arbitrarily  independent of $\tilde \xi_1$ and $\tilde \xi_2$, from Lemma \ref{lem:tight_tem_moment}, $\Psi_2(\Sigma_U)$ admits a modification 
		taking values in 
		$\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ as desired for this step.

		\refstepcounter{step}\emph{Step \thestep. }
		Combining results from
		Steps 1, 2, 3 and 4
		with the argument at the beginning of this proof, we know that the desired result for this proposition holds.

The condition $[U]_{\mathrm p} = [V]_{\mathrm p}$ says that
		\begin{equation}
			U(\omega,t,x) = V(\omega, t, x), \quad \text{$\mathbb P\otimes \Lambda$-a.e. $(\omega, t)\in \Omega \times [0,T]$,}\quad x\in {\mathbb X}.
		\end{equation}
		By Fubini's theorem, this implies that 
		\begin{equation}
			U(\omega,t,x) = V(\omega, t, x), \quad \text{$\mathbb P$-a.s. $\omega\in \Omega$,}\quad \text{$\Lambda$-a.e.~$t\in [0,T]$}, \quad x\in {\mathbb X}.
		\end{equation}
		Since ${\mathbb X}$ is separable, we know the existence of a countable dense subset ${\mathbb X}_0$ of ${\mathbb X}$. 
		Now the above display implies that for $\Lambda$-almost every $t\in [0,T]$,
		\begin{equation} \label{eq:CD}
			U(\omega,t,x) = V(\omega, t, x), \quad x\in {\mathbb X}_0, \quad \text{$\mathbb P$-a.s. $\omega\in \Omega$}.
		\end{equation}
		Denote by $A$ the collection of $t\in [0,T]$ such that \eqref{eq:CD} holds. Then $\Lambda(A^{\mathrm c}) = 0$, where $A^{\mathrm c} := [0,T]\setminus A$.
		Denote by $(\mathcal O_k)_{k=1}^\infty$ a countable topological base of $[0,T]$.
		For every $k\in \mathbb N$, since $\Lambda(\mathcal O_k)>0$, we must have $\mathcal O_k \not\subset A^{\mathrm c}$, and therefore, $\mathcal O_k\cap A \neq \emptyset$. 
		Taking $t_k \in \mathcal O_k\cap A \neq \emptyset$ for each $k\in \mathbb N$, we obtain a countable dense subset $A_0:=\{t_k:k\in \mathbb N\}$ of $[0,T]$ such that 
		\begin{equation}
			U(\omega,t,x) = V(\omega, t, x), \quad x\in {\mathbb X}_0, \quad \text{$\mathbb P$-a.s. $\omega\in \Omega$,}\quad t\in A_0.
		\end{equation}
		This implies that 
		\begin{equation}
			U(\omega,t,x) = V(\omega, t, x), \quad x\in {\mathbb X}_0, \quad t\in A_0, \quad \text{$\mathbb P$-a.s. $\omega\in \Omega$}.
		\end{equation}
		Finally, since $U$ and $V$ are continuous random fields on $[0,T]\times {\mathbb X}$, we obtain the desired result for this lemma.

\setcounter{step}{0}\refstepcounter{step}\emph{Step \thestep. }\label{step:LT}
		Since $T>0$ was chosen arbitrarily, we only need to show the well-posedness of SPDE \eqref{eq:spde} up to time $T$.
		That is, we only need to show that there exists an up-to-indistinguishability unique $(\mathscr F_t)_{t\geq 0}$-adapted $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued random field $(u_t(x))_{t\in [0,T], x\in {\mathbb X}}$ such that, for every $t\in [0,T]$ and $x\in {\mathbb X}$, \eqref{eq:mild2} holds almost surely.
		It is then standard to extend this unique solution to infinite time. 

		\refstepcounter{step}\emph{Step \thestep. }
		We show in this step the existence of $(u_t(x))_{t\in [0,T], x\in {\mathbb X}}$ as desired in Step \ref{step:LT}. 
		Let the predictable random fields $U$ and $\widetilde U$ be given as in Proposition \ref{prop:existence of C_tem modification}.
		Note that 
		\begin{equation}
			[\tilde U]_{\mathrm p} = [U]_{\mathrm p} = [\Phi(U)]_{\mathrm p} 
			\overset{\eqref{eq:Phisharp}}{=} \Phi^\sharp([U]_{\mathrm p}) =  
			\Phi^\sharp([\tilde U]_{\mathrm p}) = [\Phi(\tilde U)]_{\mathrm p}.
			\label{eq:Upm}
		\end{equation}
		Therefore, $\tilde U$ is also a random field as desired in Corollary \ref{cor:MfT}.
		As a consequence of this and Proposition \ref{prop:existence of C_tem modification}, 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:PU}] $\Phi(\tilde U)$ admits a modification in $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$, denoted by $\tilde \Phi(\tilde U)$.
		\end{itemize}
		Now, since both $\tilde U$ and $\tilde \Phi(\tilde U)$ are $\mathcal C_{[0,T]}\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued predictable random fields and 
		\begin{equation}
			[\tilde U]_{\mathrm p} 
			\overset{\eqref{eq:Upm}}{=} [\Phi(\tilde U)]_{\mathrm p} 
			\overset{\eqref{eq:PU}}{=} [\tilde \Phi(\tilde U)]_{\mathrm p},
		\end{equation}
		by Lemma \ref{eq:TX}, $\tilde U$ and $\tilde \Phi(\tilde U)$ are indistinguishable.
		From this and \eqref{eq:PU}, $\tilde U$ is a modification of $\Phi(\tilde U)$.
		The desired existence result for this step now follows by taking $(u_t(x))_{t\in [0,T], x\in {\mathbb X}} = \tilde U$.

		\refstepcounter{step}\emph{Step \thestep. } 
		We prove the uniqueness of the random field $(u_t(x))_{t\in [0,T], x\in {\mathbb X}}$ as desired in Step \ref{step:LT} following the argument outlined in \cite[Theorem 2.2]{MR1271224}. 
		To do this, let $U$ and $V$ be two such random fields, and let $\lambda \in (0,1]$ be arbitrary. We only need to show that $U$ and $V$ are indistinguishable.
		For the rest of this proof, $n$ always denotes an integer satisfying $n>\|f\|_{(\lambda)}$. We set
		\begin{align*}
			\tau_n:= { T\wedge }\inf\left\{
			t\in [0,T]:\,
			\Norm*{U(t,\cdot)}_{ (\lambda)
			} \ge n \text{ or } \Norm*{V(t,\cdot)}_{(\lambda)} \ge n \right\}.
		\end{align*}
		Noticing that $t\mapsto \|U(t,\cdot)\|_{(\lambda)}$ and $t\mapsto \|V(t,\cdot)\|_{(\lambda)}$ are almost surely continuous on $[0,T]$, it is easy to see that
		\begin{equation}\label{eq:tnT}
			\lim_{n\to \infty}\tau_n = T, \quad \text{a.s.}
		\end{equation}
		For every $t\in[0,T]$, $x\in{\mathbb X}$ and $n\in\mathbb N$, define
		\[
			U_n(t,x):=\mathbf 1_{\{t\leq\tau_n\}}U(t,x),
			\qquad
			V_n(t,x):=\mathbf 1_{\{t\leq\tau_n\}}V(t,x).
		\]
		Since $\tau_n$ is a stopping time, $t\mapsto\mathbf 1_{\{t\leq\tau_n\}}$ is adapted and left-continuous, and hence predictable; thus $U_n$ and $V_n$ are predictable.
		Clearly, for every $n\in \mathbb N$, \[\sup_{t \in [0,T]}\Parentheses*{\Norm*{U_n(t,\cdot)}_{(\lambda)}+ \Norm*{V_n(t,\cdot)}_{(\lambda)}} \le 2n, \quad \text{a.s.} \] and in particular $U_n, V_n \in \mathbb M_{\lambda, 2}$.
		For every $n\in \mathbb N$, define predictable functions $b^{(n)}$ and $\sigma^{(n)}$ on $\Omega \times [0,T] \times {\mathbb X} \times \mathbb R$ such that for every $t\in [0,T], x\in {\mathbb X}$ and $u\in \mathbb R$, 
		\begin{align}
			&(b^{(n)}(\omega, t, x, u))_{\omega \in \Omega} := b^{(n)}(t,x,u):= b(t, x, u)\mathbf 1_{\{t\leq \tau_n\}},
			\\&(\sigma^{(n)}(\omega, t, x, u))_{\omega \in \Omega} :=\sigma^{(n)}(t, x, u) := \sigma(t, x, u) \mathbf 1_{\{t\leq \tau_n\}}.
		\end{align}
		Pay attention that, almost surely for every $n\in \mathbb N$, $t\in [0,T]$, $x\in {\mathbb X}$ and $u,v\in \mathbb R$, we have
		\begin{equation}
			|b^{(n)}(t,x,u)| + |\sigma^{(n)}(t,x,u)|  \leq |b(t,x,u)| + |\sigma(t,x,u)|
		\end{equation}
		and
		\begin{align}
			&|b^{(n)}(t,x,u) - b^{(n)}(t,x,v)| + |\sigma^{(n)}(t,x,u)- \sigma^{(n)}(t,x,v)|  
			\\&= |b(t,x,u) - b(t,x,v)|\mathbf 1_{\{t\leq \tau_n\}} + |\sigma(t,x,u)- \sigma(t,x,v)|  \mathbf 1_{\{t\leq \tau_n\}} 
			\\&\leq  |b(t,x,u) - b(t,x,v)| + |\sigma(t,x,u)- \sigma(t,x,v)|.
		\end{align}
		Therefore, for every $n\in \mathbb N$, 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)] the linear growth condition \eqref{eq:LiG} and the Lipschitz condition \eqref{ineq:g_lip} still hold with $b$, and $\sigma$, being replaced by $b^{(n)}$, and $\sigma^{(n)}$, respectively.
		\end{itemize} 
		For any $n\in \mathbb N$, $\tilde U \in \mathbb M_{\lambda, 2}$, $t\in [0,T]$ and $x\in {\mathbb X}$, define
		\begin{equation}
			B^{(n)}_{\tilde U}(t,x):= b^{(n)}(t,x, \tilde U(t,x)) \quad \text{and} \quad \Sigma^{(n)}_{\tilde U}(t,x):= \sigma^{(n)}(t,x, \tilde U(t,x)).
		\end{equation}
		Now, for every $n\in \mathbb N$, since all the conditions of Lemma \ref{lem:b_contract_combined} are met with $(\tilde \alpha, p ,g, b, \sigma)$ being replaced by $(\alpha, 2, f, b^{(n)}, \sigma^{(n)})$, we conclude that 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)] for each $\tilde U\in \mathbb M_{\lambda,2}$, $(B^{(n)}_{\tilde U},\Sigma^{(n)}_{\tilde U})$ is a Duhamel-integrable pair, and  $\Psi(f,B^{(n)}_{\tilde U},\Sigma^{(n)}_{\tilde U}) \in \mathbb M_{\lambda,2}$; moreover, 
			\item[\refstepcounter{equation}(\theequation)\label{eq:uA}] uniformly in $ \tilde U, \tilde V \in \mathbb M_{\lambda, 2}$ and $A\ge 1$, we have 
			\begin{align}
				\Norm*{\Psi(f,B^{(n)}_{\tilde U},\Sigma^{(n)}_{\tilde U}) - \Psi(f,B^{(n)}_{\tilde V},\Sigma^{(n)}_{\tilde V})}_{\mathbb M_{\lambda, 2, A}} 
				\lesssim  A^\frac{\alpha - 1}{2} 
				\Norm*{\tilde U - \tilde V}_{\mathbb M_{\lambda, 2, A}}.
			\end{align}
		\end{itemize}
		In fact, we first note that for every $t\in [0,T]$ and $x\in {\mathbb X}$, almost surely,
		\begin{align} 
			&U(t,x) - V(t,x) 
			\\&= \iint_0^t G(s,y;t,x) b(s,y, U(s,y)) \mathrm ds m(\mathrm dy) 
			\\&\quad + \iint_0^t G(s,y;t,x) \sigma(s,y, U(s,y))W(\mathrm ds, \mathrm dy) 
			\\& \quad - \iint_0^t G(s,y;t,x) b(s,y, V(s,y)) \mathrm ds m(\mathrm dy) 
			\\& \quad - \iint_0^t G(s,y;t,x) \sigma(s,y, V(s,y))W(\mathrm ds, \mathrm dy). \label{eq:CF}
		\end{align}
		Since for every $x\in {\mathbb X}$, almost surely, both sides of \eqref{eq:CF} are continuous in $t\in [0,T]$,
		we have actually
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:Cv}] for every $x\in {\mathbb X}$, almost surely, \eqref{eq:CF} holds for every $t\in [0,T]$.
		\end{itemize}
		Define $Z_n:=U_n-V_n\in\mathbb M_{\lambda,2}$ for every $n\in\mathbb N$.
		Therefore, for every sufficiently large $n\in\mathbb N$, $t\in[0,T]$ and $x\in{\mathbb X}$, almost surely,
		\begin{align}
			&Z_n(t,x)=U_n(t,x)-V_n(t,x)
			\\&=\mathbf 1_{\{t\leq\tau_n\}}\big(U(t,x)-V(t,x)\big)
			\\&\overset{\eqref{eq:Cv}}{=} \mathbf 1_{\{t\leq\tau_n\}}
			\iint_0^{t} G(s,y;t,x) b^{(n)}(s,y, U_n(s,y)) \mathrm ds m(\mathrm dy)
			\\&\qquad + \mathbf 1_{\{t\leq\tau_n\}}
			\iint_0^{t} G(s,y;t,x) \sigma^{(n)}(s,y, U_n(s,y))W(\mathrm ds, \mathrm dy)
			\\& \qquad - \mathbf 1_{\{t\leq\tau_n\}}
			\iint_0^{t} G(s,y;t,x) b^{(n)}(s,y, V_n(s,y)) \mathrm ds m(\mathrm dy)
			\\& \qquad - \mathbf 1_{\{t\leq\tau_n\}}
			\iint_0^{t} G(s,y;t,x) \sigma^{(n)}(s,y, V_n(s,y))W(\mathrm ds, \mathrm dy)
			\\&=\mathbf 1_{\{t\leq\tau_n\}}
			\left[\Psi(f, B^{(n)}_{U_n}, \Sigma^{(n)}_{U_n})
			-\Psi(f, B^{(n)}_{V_n}, \Sigma^{(n)}_{V_n})\right](t,x).
			\label{eq:UnVn}
		\end{align}
		We obtain that, uniformly for every sufficiently large $n\in \mathbb N$ and $A\geq 1$,
		\begin{align}
			\Norm*{Z_n}_{\mathbb M_{\lambda,2,A}}
			&\overset{\eqref{eq:UnVn}}{\leq}
			\Norm*{\Psi(f,B^{(n)}_{U_n},\Sigma^{(n)}_{U_n})
			-\Psi(f,B^{(n)}_{V_n},\Sigma^{(n)}_{V_n})}_{\mathbb M_{\lambda,2,A}}\\
			&\overset{\eqref{eq:uA}}\lesssim
			A^\frac{\alpha - 1}{2}
			\Norm*{U_n-V_n}_{\mathbb M_{\lambda,2,A}}
			=A^\frac{\alpha - 1}{2}\Norm*{Z_n}_{\mathbb M_{\lambda,2,A}}.
		\end{align}
		Therefore, there exists an $A\geq 1$ sufficiently large such that
		$\Norm*{Z_n}_{\mathbb M_{\lambda,2,A}}
		\leq \frac{1}{2}\Norm*{Z_n}_{\mathbb M_{\lambda,2,A}}$
		for every sufficiently large $n\in\mathbb N$, which implies that
		\begin{align}
			\sup_{x \in {\mathbb X}}\operatorname*{ess\,sup}_{\Lambda\text{-a.e. }t\in[0,T]}
			e^{-At}h(x)^{-\lambda}\Norm*{Z_n(t,x)}_{L^2_\Omega}
			=\Norm*{Z_n}_{\mathbb M_{\lambda,2,A}}=0.
		\end{align}
		Thus, for every $x\in{\mathbb X}$,
		\[
			\mathbf 1_{\{t\leq\tau_n\}}\big(U(t,x)-V(t,x)\big)=0
			\quad\text{for $\mathbb P\otimes\Lambda$-almost every $(\omega,t)$.}
		\]
		Let ${\mathbb X}_0$ be a countable dense subset of ${\mathbb X}$.
		By Fubini's theorem, on a common event of probability one, for every sufficiently large $n\in\mathbb N$ and $x\in{\mathbb X}_0$,
		\[
			U(t,x)=V(t,x)
			\quad\text{for $\Lambda$-almost every $t\in[0,T]$ satisfying $t\leq\tau_n(\omega)$.}
		\]
		Since $n>\|f\|_{(\lambda)}$, the continuity used in the definition of $\tau_n$ gives $\tau_n>0$ almost surely.
		The joint continuity of $U-V$ therefore first gives equality for every $t\in[0,\tau_n]$ and $x\in{\mathbb X}_0$, and then, by density, for every $t\in[0,\tau_n]$ and $x\in{\mathbb X}$.

		Let $\Omega_0$ be a probability-one event on which $\tau_n\uparrow T$, as in \eqref{eq:tnT}, and $U-V$ is jointly continuous. Since $(\tau_n)_{n\in\mathbb N}$ is nondecreasing, for some sufficiently large $n_0\geq1$,
		\begin{align}
			&\Omega_0\cap\left\{U(t,x)=V(t,x),\ \forall\,(t,x)\in[0,T]\times{\mathbb X}\right\}\nonumber\\
			&\qquad=\Omega_0\cap\bigcap_{n\geq n_0}\left\{U(t,x)=V(t,x),\ \forall\,(t,x)\in[0,\tau_n]\times{\mathbb X}\right\}.
			\label{eq:continuity of sets_temp}
		\end{align}
		Since $\mathbb P(\Omega_0)=1$ and the events in the intersection above decrease with $n$, continuity from above of $\mathbb P$ gives
		\begin{equation}\label{eq:Zn1}
			\begin{aligned}
			1&=\lim_{n \to \infty}\mathbb P\left(
			U(t,x)=V(t,x),\
			\forall\,(t,x) \in [0,\tau_n]\times{\mathbb X}
			\right)\\
			&=\mathbb P\left( U(t,x)=V(t,x),\ \forall\,(t,x) \in [0,T]\times{\mathbb X} \right).
			\end{aligned}
		\end{equation}
		Therefore, $U$ and $V$ are indistinguishable random fields as desired.

\label{cor:moment}
		Let $u$ be the  mild-solution given by Theorem~\ref{thm:main2}, and let $p\ge2$. Then, for every $T>0$ and every $\lambda\in(0,1]$, and also for $\lambda=0$ if $f\in\mathcal C^{\mathrm b}_{\mathbb X}$,
		\begin{equation}\label{ineq:moment_every_t}
			\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}h(x)^{-\lambda}\Norm*{u(t,x)}_{L^p_\Omega}<\infty.
		\end{equation}

Fix $T>0$, and let $U$ and $\tilde U$ be as in the proof of Theorem~\ref{thm:main2}, constructed on $[0,T]$. By the uniqueness part of Theorem~\ref{thm:main2}, $u=\tilde U$ on $[0,T]\times{\mathbb X}$ up to indistinguishability, and by \eqref{eq:Upm}, $\tilde U$ is a predictable modification of $U$. Hence, by Corollary~\ref{cor:MfT}, $\Norm*{u}_{\mathbb M_{\lambda,p}}=\Norm*{U}_{\mathbb M_{\lambda,p}}<\infty$ for every $\lambda\in(0,1]$, and also for $\lambda=0$ if $f\in\mathcal C^{\mathrm b}_{\mathbb X}$.

		Now fix $x\in{\mathbb X}$ and $t\in[0,T]$. We see that the bound $h(x)^{-\lambda}\Norm*{u(s,x)}_{L^p_\Omega}\le\Norm*{u}_{\mathbb M_{\lambda,p}}$ holds for $\Lambda$-a.e.\ $s\in[0,T]$. Hence, we may choose such $s=t_j$ with $t_j\to t$. Since $u$ has continuous paths in $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ and $m$ has full support, $u(t_j,x)\to u(t,x)$ almost surely, and Fatou's lemma gives
		\begin{align*}
			h(x)^{-\lambda}\Norm*{u(t,x)}_{L^p_\Omega}\le\liminf_{j\to\infty}h(x)^{-\lambda}\Norm*{u(t_j,x)}_{L^p_\Omega}\le\Norm*{u}_{\mathbb M_{\lambda,p}}.
		\end{align*}
		Taking the supremum over $(t,x)\in[0,T]\times{\mathbb X}$ proves \eqref{ineq:moment_every_t}.

Fix $p \ge 2$, $\lambda \in (0,1]$ and $T>0$. 
		Define $v^{(n)}_t(x):= u^{(n)}_t(x) - u_t(x)$ for every $(t,x) \in [0,T] \times {\mathbb X}$ and $n\in \mathbb N$.
		Uniformly for every $(t,x)\in [0,T]\times {\mathbb X}$ and $n\in \mathbb N$, 
		\begin{align}
			&\Norm*{v^{(n)}_t(x)}_{L^p_\Omega} 
			\\&= \Bigg\| P_t^*(f_n-f)(x) +   \int_0^t \mathrm ds \int_{\mathbb X} G_{t-s}(y,x) \Parentheses*{b(s,y, u^{(n)}_s(y)) - b(s,y, u_s(y)) } m(\mathrm dy) 
			\\& \qquad + \iint_0^t G_{t-s}(y,x)\Parentheses*{\sigma(s,y, u^{(n)}_s(y)) - \sigma(s,y, u_s(y)) }W(\mathrm ds\mathrm dy)\Bigg\|_{L^p_\Omega}
			\\&\overset{\text{Minkowski}}{\leq}  P_t^*(|f_n-f|)(x) +  \int_0^t \mathrm ds \int_{\mathbb X} G_{t-s}(y,x) \Norm*{b(s,y, u^{(n)}_s(y)) - b(s,y, u_s(y)) }_{L^p_\Omega} m(\mathrm dy)
			\\& \qquad + \Norm*{\iint_0^t G_{t-s}(y,x)\Parentheses*{\sigma(s,y, u^{(n)}_s(y)) - \sigma(s,y, u_s(y)) }W(\mathrm ds\mathrm dy)}_{L^p_\Omega}
			\\&\overset{\text{Lemma \ref{cor:mtg+mink_cs}}}{\lesssim} P_t^*(|f_n-f|)(x) +  \int_0^t \mathrm ds \int_{\mathbb X} G_{t-s}(y,x) \Norm*{b(s,y, u^{(n)}_s(y)) - b(s,y, u_s(y)) }_{L^p_\Omega} m(\mathrm dy)
			\\& \qquad + \Parentheses*{\int_0^t \Norm*{ G_{t-s}(\cdot,x)\Norm*{\sigma(s,\cdot, u^{(n)}_s(\cdot)) - \sigma(s,\cdot, u_s(\cdot)) }_{L^p_\Omega} }_{\mathcal H_K}^2 \mathrm ds}^{1/2}
			\\&\overset{\eqref{ineq:g_lip}}{\lesssim}P_t^*(|f_n-f|)(x) +  \int_0^t \mathrm ds \int_{\mathbb X} G_{t-s}(y,x) \Norm*{v^{(n)}_s(y)}_{L^p_\Omega} m(\mathrm dy)
			\\& \qquad + \Parentheses*{\int_0^t \Norm*{ G_{t-s}(\cdot,x)\Norm*{v^{(n)}_s(\cdot)}_{L^p_\Omega} }_{\mathcal H_K}^2 \mathrm ds}^{1/2}. \label{eq:vntx}
		\end{align}
		We denote the three terms on the right-hand side of \eqref{eq:vntx} by $I_0^{(n)}(t,x)$, $I_1^{(n)}(t,x)$ and $I_2^{(n)}(t,x)$, respectively.

		It holds uniformly in $(t,x) \in [0,T] \times {\mathbb X}$ and $n \in \mathbb N$  that 
		\begin{align}
			&
			I_0^{(n)}(t,x) 
			= \int_{\mathbb X} G_t(y,x)|f_n(y)-f(y)| m(\mathrm dy)
			\le \int_{\mathbb X} G_t(y,x) h(y)^{\lambda} 
			\|f_n - f\|_{(\lambda)}m(\mathrm dy)
			\\&=  \Norm*{G_t(\cdot, x)h(\cdot)^\lambda}_{L^1_{\mathbb X}} \|f_n - f\|_{(\lambda)} 
			\overset{
				\text{Lemma \ref{lem:hk longtime}}
			}{\lesssim} h(x)^\lambda \Norm*{f_n - f}_{(\lambda)}. \label{eq:vntx0}
		\end{align}
		Similarly, it holds uniformly in $(t,x) \in [0,T]\times {\mathbb X}$  and $n\in \mathbb N$ that 
		\begin{align}
			&
			I_1^{(n)}(t,x) 
			\le \iint_0^t  G_{t-s}(y,x) h(y)^\lambda 
			\Norm*{\Norm*{
					v^{(n)}_s(\cdot)
				}_{L^p_\Omega}}_{(\lambda)} \mathrm ds m(\mathrm d y)
			\\& \overset{\text{Fubini}}{=} \int_0^t \Parentheses*{\int G_{t-s}(y,x) h(y)^\lambda m(\mathrm dy)} \Norm*{\Norm*{v^{(n)}_s(\cdot)}_{L^p_\Omega}}_{(\lambda)} \mathrm ds 
			\overset{
				\text{Lemma \ref{lem:hk longtime}}
			}{\lesssim}  h(x)^\lambda\int_0^t  
			\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds. \label{eq:vntx1}
		\end{align}
		Finally, it holds uniformly in $(t,x) \in [0,T]\times {\mathbb X}$  and $n\in \mathbb N$ that
		\begin{align}
			&
			I_2^{(n)}(t,x) 
			\leq \Parentheses*{\int_0^t \Norm*{ G_{t-s}(\cdot,x)h(\cdot)^\lambda \Norm*{\Norm*{v^{(n)}_s(\cdot)}_{L^p_\Omega}}_{(\lambda)} }_{\mathcal H_K}^2 \mathrm ds}^{1/2}
			\\
			&\leq \Parentheses*{\int_0^t \|G_{t-s}(\cdot,x) h(\cdot)^\lambda\|_{\mathcal H_K}^2 \left\|\|v^{(n)}_s(\cdot)\|_{L^p_\Omega}\right\|_{(\lambda)}^2 \mathrm ds }^\frac{1}{2}
			\\&\overset{
				\text{Lemma \ref{lem:hk longtime}}
			}{\lesssim} h(x)^\lambda \left(\int_0^t (t-s)^{-\alpha} 
			\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}^2
			\mathrm ds \right)^\frac{1}{2}. \label{eq:vntx2}
		\end{align}

		Combining \eqref{eq:vntx}, \eqref{eq:vntx0}, \eqref{eq:vntx1} and \eqref{eq:vntx2}, we see that uniformly in $\tau \leq t$ in $[0,T]$, $x\in {\mathbb X}$ and $n\in \mathbb N$, 
		\begin{align}
			&h(x)^{-\lambda} \Norm*{v^{(n)}_{\tau}(x)}_{L^p_\Omega} 
			\overset{\eqref{eq:vntx}}{\lesssim} h(x)^{-\lambda} I_0^{(n)}(\tau,x) + h(x)^{-\lambda} I_1^{(n)}(\tau,x) + h(x)^{-\lambda} I_2^{(n)}(\tau,x)
			\\&\overset{ \eqref{eq:vntx0}, \eqref{eq:vntx1}, \eqref{eq:vntx2}}{\lesssim} \Norm*{f_n - f}_{(\lambda)} + \int_0^\tau \Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds + \Parentheses*{\int_0^\tau (\tau-s)^{-\alpha} 
				\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}^2
				\mathrm ds }^\frac{1}{2}
			\\&= \Norm*{f_n - f}_{(\lambda)} + \int_0^\tau \Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds + \Parentheses*{\int_0^\tau s^{-\alpha} 
				\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(\tau-s)}^2
				\mathrm ds }^\frac{1}{2}
			\\&\leq  \Norm*{f_n - f}_{(\lambda)} + \int_0^t \Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds + \Parentheses*{\int_0^t s^{-\alpha} 
				\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(t-s)}^2
				\mathrm ds }^\frac{1}{2}
			\\&=  \Norm*{f_n - f}_{(\lambda)} + \int_0^t \Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds + \Parentheses*{\int_0^t {(t-s)}^{-\alpha} 
				\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}^2
				\mathrm ds }^\frac{1}{2}. \label{eq:hxl}
		\end{align}
		Then uniformly in $t\in [0,T]$ and $n\in \mathbb N$,
		\begin{align}
			&\|v^{(n)}\|_{\mathbb M_{\lambda,p}(t)}^2 = \sup_{x\in {\mathbb X}} \operatorname*{ess\,sup}_{\text{$\Lambda$-a.e. $\tau \in [0,t]$}} h(x)^{-2\lambda} \Norm*{v^{(n)}_\tau(x)}^2_{L^p_\Omega} 
			\\&\overset{\eqref{eq:hxl}}{\lesssim} \Parentheses*{\Norm*{f_n - f}_{(\lambda)} + \int_0^t \Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}
				\mathrm ds + \Parentheses*{\int_0^t {(t-s)}^{-\alpha} 
					\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}^2
					\mathrm ds }^\frac{1}{2}}^2
			\\&\overset{\text{Jensen}}\lesssim  \Norm*{f_n - f}^2_{(\lambda)} + \int_0^t \Norm*{v^{(n)}}^2_{\mathbb M_{\lambda,p}(s)}
			\mathrm ds + \int_0^t {(t-s)}^{-\alpha} 
			\Norm*{v^{(n)}}_{\mathbb M_{\lambda,p}(s)}^2
			\mathrm ds.
		\end{align}
		For $t \in [0,T]$, set $U_n(t):=\|v^{(n)}\|_{\mathbb M_{\lambda,p}(t)}$, which is finite by Corollary~\ref{cor:moment}. By Gr\"{o}nwall's inequality (see for example, \cite{chu1967gronwall}), we obtain uniformly in $t \in [0,T]$ that 
		\begin{align}
			U_n(t)^2 \lesssim \|f_n - f\|_{(\lambda)}^2\left(1+ \int_0^t \left( 1+ (t-s)^{-\alpha} \right) \exp\left( \int_0^s(1+(s-\tau)^{-\alpha})\mathrm d\tau  \right)\mathrm ds\right)
		\end{align}
		which converges to zero uniformly in $t \in [0,T]$ as $n \to \infty$ since $\alpha \in (0,1)$.

\label{lem:approx_estimates}
		\begin{enumerate}
			\item \label{lem:approx_estimates1} 
			Let $\alpha \in (0,1)$ be given as in \eqref{cond:exp_hk_lamda}. Then there exists $\kappa \in \mathbb{R}$, independent of $\varepsilon$, such that
			uniformly in $t>0$, $x\in{\mathbb X}$ and $\varepsilon\in(0,1]$,
			\begin{align}\label{ineq:R_bound}
				\left\|r_t^\varepsilon(\cdot,x)\right\|_{\mathcal H_K}^2
				\lesssim t^{-\alpha}e^{\kappa t},\qquad
				\left\|r_t^\varepsilon(\cdot,x)\right\|_{L^1_{\mathbb X}}
				\lesssim e^{\kappa t}.
			\end{align}
			\item  For each $t >0$,
			\begin{align}\label{lim:p_approx}
				\lim_{\varepsilon \downarrow 0}\sup_{x\in {\mathbb X}} \int_0^t \left\| \left|\int_{\mathbb X}  r_s^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy) -  G_s(\cdot, x)
				\right|\right\|^2_{\mathcal H_K}\,\mathrm ds = 0.
			\end{align}
			\item For each $T>0$, there exists a $c_T \in (0,1]$, and a function $\varepsilon \to \gamma_\varepsilon$ with $\lim_{\varepsilon \downarrow 0} \gamma_\varepsilon = 0$, so that,  uniformly in $(t,x) \in (0,T]\times {\mathbb X}$ and sufficiently small $\varepsilon >0$, it holds that
			\begin{align}\label{ineq:p_approx_m}
				\int_{\mathbb X} \left|r_t^\varepsilon(y,x)  - G_t(y,x)\right| m(\mathrm dy)\lesssim e^{-c_T\frac{t}{\varepsilon}} +  \frac{\gamma_\varepsilon}{t^\beta},
			\end{align}
			where $\beta$ is as in \eqref{cond:time_holder}.
		\end{enumerate}

\label{thm:non_negtive}
		Suppose that
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{ineq:non_negativity_coef_bound_at_zero}] for any $T>0$, uniformly for $\omega \in \Omega \setminus \mathrm N_{\ref{c:Lip}}$
			and $(t,x) \in [0,T]\times {\mathbb X}$,
			\begin{align}
				b(\omega,t,x,0) \geq 0, \qquad \sigma(\omega,t,x,0) = 0.
			\end{align}
		\end{itemize}
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{ineq:non_negative_approx_coef_ineq}]
			there exists an $\eta >0$ 
			so that for any $T>0$, 
			uniformly in $\omega \in \Omega \setminus \mathrm N_{\ref{c:Lip}}$, $u\in \mathbb R$,
			and $(t,x,y) \in [0,T]\times {\mathbb X}^2$,
			\begin{align}
				\Absolute*{b(\omega,t,x,u) - b(\omega,t,y,u)} \lesssim d(x,y)^\eta (1+|u|),\\
				\Absolute*{\sigma(\omega,t,x,u) - \sigma(\omega,t,y,u)} \lesssim d(x,y)^\eta |u|;
			\end{align}
		\end{itemize}
		and that $f$ is non-negative.
		Then  $u$ is non-negative.

In light of Proposition \ref{prop:continuity_initial} and Lemma \ref{lem:C_temp_density_0}, it is enough to assume that $f$ is bounded, continuous, and non-negative.

		For $\varepsilon>0$ and $(t,x)\in\mathbb{R}_+\times{\mathbb X}$, define $W^\varepsilon(t,x)=:W^\varepsilon_x(t)$ via
		\begin{align}\label{def:white_noise_cov}
			W^\varepsilon(t,x) := \iint_0^t  G_\varepsilon(y,x)W(\mathrm ds,\mathrm dy).
		\end{align}
		Observe that for each $(t,x),\, (t',x') \in \mathbb{R}_+\times {\mathbb X}$, 
		\begin{align}
			{\mathbb E}\left[W^\varepsilon(t,x)W^\varepsilon(t',x')\right] &= \Parentheses*{t\wedge t'}\left \langle Q\left[G_\varepsilon(\cdot, x)\right]_K, \left[G_\varepsilon(\cdot,x') \right]_K \right \rangle_{\tilde{\mathcal H}_K}\\
			&:=\Parentheses*{t'\wedge t} k_\varepsilon(x,x').
		\end{align}
		By \eqref{cond:exp_hk_lamda}, we see there is some $\alpha \in (0,1)$ so that $\sup_{x}k_\varepsilon(x,x)\lesssim\varepsilon^{-\alpha}$ uniformly in $\varepsilon \in (0,1]$.

		For each fixed $x\in{\mathbb X}$, the process $(W^\varepsilon(t,x),\,t\geq0)$ is a Brownian motion with 
		\begin{align}\label{eq:q_var_ep}
			\left[\int_0^\cdot W^\varepsilon(\mathrm ds,x)\right]_t =\left[ \iint_0^\cdot  G_\varepsilon(y , x)W(\mathrm dy,\mathrm ds)\right]_t = t k_\varepsilon(x,x)
		\end{align}
		where $([M]_t)_{t \ge 0}$ is the quadratic variation process of a martingale $(M_t)_{t\ge0}$. 

		Let $\varepsilon\in(0,1]$ and recall $\mathcal L^{\varepsilon,*}$, $P^{\varepsilon,*}$, and the density $r_t^\varepsilon$ defined after \eqref{approx_kernel}. Formally, we consider the following equation with initial condition $u_\varepsilon(0,x) = f(x)$, 
		\begin{align*}
			\mathrm d u_\varepsilon(t,x)
			={}&\left(\mathcal L^{\varepsilon,*}u_\varepsilon(t,x)+b(t,x,u_\varepsilon(t,x))\right)\mathrm dt+\sigma(t,x,u_\varepsilon(t,x))W^\varepsilon(\mathrm dt,x)
		\end{align*}
		whose mild form is given by
		\begin{align}\label{eq:cont_1d_mild}
			u_\varepsilon(t,x) = P^{\varepsilon,*}_t f(x) +&  \int_0^t e^{-(t-s)/\varepsilon}b\Parentheses*{s,x,u_\varepsilon(s,x)}\mathrm ds\nonumber\\
			&+\int_0^t\mathrm ds \int_{\mathbb X} r_{t-s}^\varepsilon(y,x)b(s,y,u_\varepsilon(s,y))m(\mathrm dy)\nonumber\\
			&+\int_0^t e^{- (t-s)/\varepsilon}\sigma(s,x,u_\varepsilon(s,x)) W^\varepsilon(\mathrm ds,x)\nonumber\\
			&+\int_{\mathbb X}\int_0^t r_{t-s}^\varepsilon(y,x)\sigma(s,y,u_\varepsilon(s,y))W^\varepsilon(\mathrm ds,y)m(\mathrm dy).
		\end{align}
		One can show that \eqref{eq:cont_1d_mild} has a $\mathcal C_{[0,T]} \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued solution satisfying
		\begin{align}\label{boud: lp_loc_both}
			\sup_{0 < \varepsilon\le 1}\sup_{0 \le t \le T} \sup_{x \in {\mathbb X}} {\mathbb E} \left[|u_\varepsilon(t,x)|^2\right] < \infty,\qquad \forall T>0.
		\end{align}
		 Since $\mathcal L^{\varepsilon,*}$ is bounded and
		\[
			P_t^{\varepsilon,*}-I=\int_0^t\mathcal L^{\varepsilon,*}P_s^{\varepsilon,*}\mathrm ds,
		\]
		ordinary and stochastic Fubini (Lemma \ref{thm:stochastic_fubini}), conditions \eqref{eq:LiG}, \eqref{cond:exp_hk_lamda}, \eqref{ineq:hk_m long time}, \eqref{ineq:R_bound}, and the bound \eqref{boud: lp_loc_both} ensure that  \eqref{eq:cont_1d_mild} satisfies
		\begin{align}\label{eq:cont_1d_sde}
			u_\varepsilon(t,x)=f(x)&+\int_0^t\left(\mathcal L^{\varepsilon,*}u_\varepsilon(s,x)+b(s,x,u_\varepsilon(s,x))\right)\mathrm ds\nonumber\\
			&+\int_0^t\sigma(s,x,u_\varepsilon(s,x))W^\varepsilon(\mathrm ds,x).
		\end{align}
		The last term is a one-dimensional It\^{o} integral. Hence, by \eqref{def:white_noise_cov} and \eqref{eq:cont_1d_sde}, $\left(u_\varepsilon(t,x)\right)_{t\geq0}$ is a continuous semimartingale for each fixed $\varepsilon\in(0,1]$ and $x\in{\mathbb X}$.

		Let $\varphi(u) := - \left(u \wedge 0\right) = u^-,\, u \in \mathbb{R} $, which is convex. By It\^o--Meyer--Tanaka's formula (\cite[Proposition 9.2]{le2016brownian}), we see for each $t \ge0$ and $x \in {\mathbb X}$,
		\begin{equation}\label{eq:u_epsilon negative part}
			\begin{aligned}
				{\mathbb E}[\varphi(u_\varepsilon(t,x))]= \varphi(f(x)) &- {\mathbb E}\left[\int_0^t \mathbf 1_{u_\varepsilon(s,x) \le 0} \left(\mathcal L^{\varepsilon,*} u_\varepsilon(s,x) +b(s,x,u_\varepsilon(s,x)) \right)\mathrm ds\right]\\
				&- {\mathbb E}\left[\int_0^t \mathbf 1_{u_\varepsilon(s,x) \le 0} \,\sigma(s,x,u_\varepsilon(s,x))\mathrm dW_x^\varepsilon(s) -\frac12L^0_x(t)\right]
			\end{aligned}
		\end{equation}
		where for each $x \in {\mathbb X}$, $\left(L_x^0(t)\right)_{t \ge 0 }$ is the local time of $(u_\varepsilon(t,x))_{t \ge 0}$ at zero, which is non-negative and non-decreasing. Now,  
		conditions \eqref{ineq:g_lip} and \eqref{ineq:non_negativity_coef_bound_at_zero} imply that there is some $L\ge0$ which is the common Lipschitz constant for $b$ and $\sigma$ on $[0,T]$. Hence, for $r\le0$ and $(t,x) \in [0,T]\times {\mathbb X}$, $b(t,x,r)\ge -L|r|$. 
		By the definition of  $\mathcal L^{\varepsilon,*}$, we get the second term on the right hand side  of \eqref{eq:u_epsilon negative part} (including the minus sign) is smaller than
		\begin{equation}\label{eq:u_epsilon second}
			\begin{aligned}
				&{\mathbb E}\left[\int_0^t \frac{1}{\varepsilon}\boldsymbol{1}_{u_\varepsilon(s,x) \le 0} u_\varepsilon(s,x)-\frac{1}{\varepsilon}\boldsymbol{1}_{u_\varepsilon(s,x) \le 0}P_\varepsilon^* u_{\varepsilon}(s)(x) +L\,\boldsymbol{1}_{u_\varepsilon(s,x) \le 0} |u_\varepsilon(s,x)| \mathrm ds\right]\\
				\le& \left(L +1/\varepsilon\right) \int_0^t {\mathbb E}[\varphi(u_\varepsilon(s,x))]\,\mathrm ds-\frac{1}{\varepsilon}\int_0^t \int_{\mathbb X} G(\varepsilon,y,x){\mathbb E}\left[ \boldsymbol{1}_{u_\varepsilon(s,x) \le 0}u_\varepsilon(s,y)\right]\,m(\mathrm dy)\,\mathrm ds
			\end{aligned}
		\end{equation}
		where $\boldsymbol{1}_A(\cdot)$ denotes the indicator function on the set $A$.  By \cite[Proposition 9.9]{le2016brownian}, we see for each $x \in {\mathbb X}$, it holds almost surely that
		\begin{align}\label{ineq:localtime epsilon}
			L^0_x(t) &\,\,= \lim_{\delta\downarrow 0}
			\frac{1}{\delta}\int_0^t 1_{\left\{0\le u_\varepsilon(s,x)\le \delta \right\}}\mathrm d\left[ u_\varepsilon(\cdot,x)\right]_s \nonumber\\
				&\,\,=\lim_{\delta\downarrow 0}
				\frac{1}{\delta} \int_0^t 1_{\left\{0\le u_\varepsilon(s,x)\le \delta \right\}}\sigma\big(s,x,u_\varepsilon(s,x)\big)^2 \mathrm d\left[ W_x^\varepsilon(\cdot)\right]_s\nonumber\\
				&\overset{
				\eqref{ineq:g_lip}, \eqref{ineq:non_negativity_coef_bound_at_zero}}{\le} L^2\lim_{\delta\downarrow 0}
				\frac{1}{\delta}\int_0^t 1_{\left\{0\le u_\varepsilon(s,x)\le \delta \right\}} \delta^2\mathrm d\left[ W_x^\varepsilon(\cdot)\right]_s\nonumber\\
				&\overset{\eqref{eq:q_var_ep}}{\le} L^2 k_\varepsilon(x,x) \lim_{\delta \downarrow 0}
				\frac{1}{\delta} \int_0^t  1_{\left\{0\le u_\varepsilon(s,x)\le \delta \right\}} \delta^2 \mathrm ds\nonumber\\
			&\,\,=0.
		\end{align}
		In addition, we see by \eqref{boud: lp_loc_both}, \eqref{eq:q_var_ep} and the Lipschitz bound on $\sigma$ that the stochastic integral in \eqref{eq:u_epsilon negative part} is square-integrable and hence has mean zero.
		Inserting \eqref{eq:u_epsilon second} and \eqref{ineq:localtime epsilon} into equation \eqref{eq:u_epsilon negative part} and recalling $\varphi(f) \equiv 0$ on ${\mathbb X}$ since $f \ge 0$, we see that 
		\begin{align}
			{\mathbb E}[\varphi(u_\varepsilon(t,x))] &\le ( 
			L +1/\varepsilon) \int_0^t {\mathbb E}\left[ \varphi(u_\varepsilon(s,x))\right] \mathrm ds \\
			&\quad \quad\quad+  (1/\varepsilon) \int_0^t\mathrm ds \int_{\mathbb X} G(\varepsilon,y,x){\mathbb E}\left[\varphi(u_\varepsilon(s,y)
			)\right]m(\mathrm dy).
		\end{align}
		By condition \eqref{cond:exp_hk_lamda} when $\lambda = 0$, we may take the supremum over $x \in {\mathbb X}$ on both sides and apply Gronwall's lemma to see that $\sup_{x \in {\mathbb X}} {\mathbb E}\left[\varphi(u_\varepsilon(t,x))\right] = 0$ for $t\in[0,T]$. Since $T>0$ is arbitrary, we see for each $(t,x)\in\mathbb{R}_+\times{\mathbb X}$, $u_\varepsilon(t,x)\ge0$ almost surely.

		Let $(u_t)_{t\geq0}$ be the unique solution to \eqref{eq:spde}. We will show that $\lim_{\varepsilon \downarrow 0}u_\varepsilon = u$ in an appropriate sense. By Lemma \ref{lem:hk longtime}, Lemma \ref{lem:approx_estimates} together with the bound \eqref{boud: lp_loc_both}, we may apply stochastic Fubini (Lemma \ref{thm:stochastic_fubini}) to see
		\begin{align}
			&\int_{\mathbb X}\int_0^t  r_{t - s}^\varepsilon(y,x)\sigma\big(s,y,u_\varepsilon(s,y)\big) W^{\varepsilon}(\mathrm ds,y) \,m(\mathrm dy)\\
			&\quad \quad \quad \quad \quad \quad \quad\quad \quad \quad \quad \quad \quad-\iint_0^t G(t-s,z,x)\sigma\big(s,z,u(s,z)\big) W( \mathrm dz, \mathrm ds)\\
			=&  \iint_0^t \left(\int_{\mathbb X}  r_{t-s}^\varepsilon(y,x)\sigma\big(s,y,u_\varepsilon(s,y) \big) G_\varepsilon(z,y)\,m(\mathrm dy)\right)\,W(\mathrm dz,\mathrm ds)\\
			&\quad \quad \quad \quad \quad \quad \quad\quad \quad \quad \quad \quad \quad -\iint_0^t  G(t - s,z,x)\sigma\big(s,z,u(s,z)\big) W(\mathrm dz, \mathrm ds)\\
			=&\iint_0^t \left(\int_{\mathbb X}  r_{t-s}^\varepsilon(y,x) \big(\sigma\big(s,y,u_\varepsilon(s,y) \big)-\sigma\big(s,y,u(s,y) \big) \big) G_\varepsilon(z,y)\,m(\mathrm dy)\right)\,W(\mathrm dz,\mathrm ds)\\
			&\quad+\iint_0^t\left(\int_{\mathbb X}  r_{t-s}^\varepsilon(y,x) \big(\sigma\big(s,y,u(s,y) \big)-\sigma\big(s,z,u(s,z) \big)\big) G_\varepsilon(z,y)\,m(\mathrm dy)\right)\,W(\mathrm dz,\mathrm ds)\\
			&\quad+\iint_0^t\bigg(\int_{\mathbb X}  r_{t-s}^\varepsilon(y,x)\sigma\big(s,z,u(s,z) \big) G_\varepsilon(z,y)\,m(\mathrm dy) \\
			&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad- G(t - s,z,x)\sigma\big(s,z,u(s,z)\big)\bigg)\,W(\mathrm dz,\mathrm ds).
		\end{align}
		We obtain uniformly in  $(t,x) \in [0,T]\times {\mathbb X}$,
		\begin{align}
			&{\mathbb E}\left[|u_\varepsilon(t,x) - u(t,x)|^2\right] \\
			\lesssim &\left|P^{\varepsilon,*}_tf(x) - P_t^*f(x)\right|^2 + {\mathbb E}\left[\left|\int_0^t e^{-(t-s)/\varepsilon} b(s,x,u_\varepsilon(s,x) )\,\mathrm ds \right|^2\right]\\
			&+{\mathbb E}\left[\left|\int_0^t \mathrm ds\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)\Big(b(s,y,u_\varepsilon(s,y)) - b(s,y,u(s,y))\Big) m(\mathrm dy)\, \right|^2\right]\\
			&+ {\mathbb E}\left[ \left|\int_0^t \mathrm ds\int_{\mathbb X} \Big(r_{t-s}^\varepsilon(y,x) - G(t-s,y,x) \Big) b(s,y,u(s,y)) \,m(\mathrm dy)\right|^2\right]\\
			&+ \int_0^t e^{-2(t-s)/\varepsilon} \sup_{x \in {\mathbb X}}{\mathbb E}\left[\sigma(s,x,u_\varepsilon(s,x))^2\right] \varepsilon^{-\alpha}\mathrm ds\\
			&+\int_0^t \Norm*{\Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)\Absolute*{\sigma(s,y,u_\varepsilon(s,y))-\sigma(s,y,u(s,y))} G_\varepsilon(\cdot,y)m(\mathrm dy)}_{L^2_\Omega}}_{\mathcal H_K}^2 \mathrm ds\\
			&+\int_0^t \Norm*{ \Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x) \Absolute*{\sigma(s,y,u(s,y)) - \sigma(s,\cdot,u(s,\cdot))} G_\varepsilon(\cdot,y) m(\mathrm dy)}_{L^2_\Omega}}_{\mathcal H_K}^2 \mathrm ds\\
			&+\int_0^t {\mathbb E}\left[\left\|\left(\int_{\mathbb X} r_{t - s}^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy) - G(t-s,\cdot,x) \right) \sigma(s,\cdot,u(s,\cdot))\right\|^2_{\mathcal H_K} \right] \mathrm ds\\
			:=& \sum_{i = 1}^8 J_i(\varepsilon,t,x).
		\end{align}
		Using \eqref{ineq:p_approx_m} of Lemma \ref{lem:approx_estimates} and the boundedness of $f$, we see that, for each $T>0$, there exists $c_T>0$ such that, uniformly in sufficiently small $\varepsilon>0$ and $t\in(0,T]$,
		\begin{align}
			\sup_{x \in {\mathbb X}}J_1(\varepsilon,t,x)
			\lesssim e^{-c_Tt/\varepsilon}+\frac{\gamma_\varepsilon}{t^\beta},
		\end{align}
		where $\beta$ is as in \eqref{cond:time_holder}.
		At $t=0$, $P_0^{\varepsilon,*}f=P_0^*f=f$, and hence $J_1(\varepsilon,0,x)=0$.

		Since $f$ is bounded, we see by Corollary~\ref{cor:moment} with $\lambda = 0$ and $p=2$ that
		\begin{align}\label{ineq:u_uniform_second_moment}
			\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}{\mathbb E}\bigl[|u(t,x)|^2\bigr]<\infty.
		\end{align}
		Together with \eqref{ineq:p_approx_m}  and Minkowski's inequality,
		\begin{align}
\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}J_4(\varepsilon,t,x)\lesssim(\varepsilon+\gamma_\varepsilon)^2\longrightarrow0,\qquad \text{ as }\varepsilon\downarrow0.
		\end{align}
		Also, by \eqref{cond:exp_hk_lamda} with $\lambda=0$, \eqref{eq:LiG}, and \eqref{boud: lp_loc_both}, we obtain, uniformly in $\varepsilon\in(0,1]$,
		\begin{align*}
\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}J_2(\varepsilon,t,x)\lesssim\varepsilon^2,\qquad
\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}J_5(\varepsilon,t,x)\lesssim\varepsilon^{1-\alpha},
		\end{align*}
		where $\alpha\in(0,1)$ is the exponent in \eqref{cond:exp_hk_lamda}.
		Hence, 
		\begin{align}
\lim_{\varepsilon\downarrow0}\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}\big(J_2(\varepsilon,t,x)+J_5(\varepsilon,t,x)\big)=0.
		\end{align}
		By \eqref{eq:LiG}, \eqref{ineq:u_uniform_second_moment}, and Lemma \ref{lem:approx_estimates},
		\begin{align}
			\lim_{\varepsilon \downarrow 0} \sup_{t \in [0,T]} \sup_{x \in {\mathbb X}} J_8(\varepsilon,t,x) &\lesssim \lim_{\varepsilon \downarrow 0}\sup_{x \in {\mathbb X}}\int_0^T\left\|\left|\int_{\mathbb X} r_s^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy) - G(s,\cdot,x)\right|\right\|^2_{\mathcal H_K} \mathrm ds \\ &\overset{\eqref{lim:p_approx}}{=}0.
		\end{align}
		Let $U_\varepsilon(t) = \sup_{x\in {\mathbb X}} \Norm*{u_\varepsilon(t,x) - u(t,x)}_{L^2_\Omega}^2$. By Minkowski's inequality, uniformly in $(t,x) \in [0,T]\times {\mathbb X}$ and sufficiently small $\varepsilon >0$,
		\begin{align}
			J_3(\varepsilon,t,x) &\overset{\eqref{ineq:g_lip}}{\lesssim} \int_0^t \left( \int_{\mathbb X} r_{t-s}^\varepsilon(y,x)m(\mathrm dy)\right)^2U_\varepsilon(s) \mathrm ds\\
			&\,\overset{\eqref{ineq:R_bound}}{\lesssim} \int_0^tU_\varepsilon(s)\mathrm ds\\
			&\,\,\,\lesssim \int_0^t (t-s)^{-\alpha}U_\varepsilon(s) \mathrm ds.
		\end{align}
		By Lemma \ref{cor:mtg+mink_cs} and Minkowski's inequality, it holds uniformly in  $(t,x) \in [0,T]\times {\mathbb X}$ and sufficiently small $\varepsilon>0$ that
		\begin{equation}\label{ineq:J6 step 1}
			\begin{aligned}
				J_6(\varepsilon,t,x) &\,\,\,\lesssim \int_0^t \Norm*{\Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)\Absolute*{\sigma(s,y,u_\varepsilon(s,y))-\sigma(s,y,u(s,y))} G_\varepsilon(\cdot,y)m(\mathrm dy)}_{L^2_\Omega}}_{\mathcal H_K}^2 \mathrm ds\\
				&\overset{\eqref{ineq:g_lip}}{\lesssim} \int_0^t\Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)\Absolute*{U_\varepsilon(s) }^\frac{1}{2}G_\varepsilon(\cdot,y)m(\mathrm dy)}_{\mathcal H_K}^2 \mathrm ds\\
				&\,\,\,= \int_0^t \Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy)}^2_{\mathcal H_K} U_\varepsilon(s)\, \mathrm ds.
			\end{aligned}
		\end{equation}
		Let $\widetilde \kappa \in \mathbb{R}$ be given by Lemma \ref{lem:hk longtime}. By the semigroup property, uniformly in $\varepsilon \in (0,1]$ and $(t,x) \in (0,T]\times {\mathbb X}$,
		\begin{equation}\label{ineq:mollified_conv_H_norm}
			\begin{aligned}
				\Norm*{\int_{\mathbb X} r_t^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy)}^2_{\mathcal H_K} &\,\,= \Norm*{e^{-t/\varepsilon}\sum_{n = 1}^\infty \frac{\Parentheses*{t/\varepsilon}^n}{n!} G(\varepsilon (n+1),\cdot,x)}^2_{\mathcal H_K}\\
				&\overset{\text{Minkowski\&Jensen}}{\le} \Parentheses*{e^{-t/\varepsilon}\sum_{n = 1}^\infty \frac{(t/\varepsilon)^n}{n!} \Norm*{G\Parentheses*{\varepsilon(n+1),\cdot,x}}_{\mathcal H_K}^2}\\
				&\overset{\eqref{ineq:hk_k long time} }{\lesssim} e^{-t/\varepsilon}\sum_{n = 0}^\infty \frac{(te^{\varepsilon\widetilde\kappa}/\varepsilon)^n}{n!} (\varepsilon(n+1))^{-\alpha}\\
				&\,\,\le e^{-t/\varepsilon + te^{\varepsilon \widetilde\kappa}/\varepsilon} \Parentheses*{e^{-te^{\varepsilon \widetilde\kappa}/\varepsilon}\sum_{n = 0}^\infty \frac{\Parentheses*{te^{\varepsilon \widetilde\kappa}/\varepsilon}^{n+1}}{(n+1)!} t^{-1}e^{-\varepsilon \widetilde\kappa}}^{\alpha}\\
				&\,\,\lesssim t^{-\alpha} \exp \left(\frac{te^{\varepsilon \widetilde\kappa} - t}{\varepsilon} \right)\\
				&\lesssim t^{-\alpha},
			\end{aligned}
		\end{equation}
		where Jensen's inequality was used in the second and fourth lines, $\alpha\in(0,1)$ is from \eqref{cond:exp_hk_lamda}, and there exists $\widetilde \kappa_0 \in \mathbb{R}$ such that, for all $t \ge 0$,
		\begin{align*}
			\sup_{\varepsilon \in (0,1]}\exp\Parentheses*{\frac{te^{\varepsilon \widetilde\kappa} - t}{\varepsilon}} \le e^{\widetilde \kappa_0 t}.
		\end{align*}
		Inserting this back into the inequality \eqref{ineq:J6 step 1}, we see uniformly in $\varepsilon \in (0,1]$ and $(t,x) \in [0,T]\times {\mathbb X}$ that
		\begin{align*}
			J_6(\varepsilon,t,x) \lesssim \int_0^t (t-s)^{-\alpha} U_\varepsilon(s) \mathrm ds.
		\end{align*}


		Now we consider $J_7$. By Lemma \ref{lem:hk longtime} and Minkowski's inequality, for each $\varepsilon \in (0,1)$ and $(t,x) \in [0,T]\times {\mathbb X}$,
		\begin{align}
			J_7(\varepsilon,t,x) &\le \int_0^t \left\|\int_{\mathbb X} r_{t-s}^\varepsilon(y,x) \|\sigma(s,y,u(s,y)) - \sigma(s,\cdot,u(s,\cdot))\|_{L^2_\Omega} G_\varepsilon(\cdot,y)m(\mathrm dy) \right\|_{\mathcal H_K}^2 \mathrm ds.
		\end{align}
		By the boundedness of $f$, \eqref{ineq:u_uniform_second_moment}, \eqref{ineq:spatial_holder_long_time}, and the calculations in the proof of Proposition \ref{prop:existence of C_tem modification} with $p=2$ and $\lambda=0$, there exists $\xi'\in(0,1)$ such that, uniformly in $s\in(0,T]$ and $y,z\in{\mathbb X}$,
		\begin{align}\label{ineq:u_bounded_spatial_increment}
			\Norm*{u(s,y)-u(s,z)}_{L^2_\Omega}
			\lesssim \left(\frac{d(y,z)^{\xi'}}{s^\beta}\right)\wedge1.
		\end{align}
		Set $\xi:=\eta\wedge\xi'$. For $d(y,z)\le1$, uniformly in $s\in(0,T]$,
		\begin{align}
			&{\quad} \Norm*{\sigma(s,y,u(s,y))-\sigma(s,z,u(s,z))}_{L^2_\Omega}\\
			&{\le} \Norm*{\sigma(s,y,u(s,y))-\sigma(s,z,u(s,y))}_{L^2_\Omega}
			+\Norm*{\sigma(s,z,u(s,y))-\sigma(s,z,u(s,z))}_{L^2_\Omega}\\
			&{\overset{\eqref{ineq:non_negative_approx_coef_ineq},\,\eqref{ineq:g_lip}}{\lesssim}}d(y,z)^\eta\Norm*{u(s,y)}_{L^2_\Omega}+\Norm*{u(s,y)-u(s,z)}_{L^2_\Omega}\\
			&{\overset{\eqref{ineq:u_bounded_spatial_increment}}{\lesssim}}
			\left(\frac{d(y,z)^\xi}{s^\beta}\right)\wedge1,
		\end{align}
		where $\beta\in[0,1)$ is as in \eqref{cond:time_holder}.
		For $d(y,z)>1$, \eqref{ineq:g_lip}, \eqref{ineq:non_negativity_coef_bound_at_zero}, and \eqref{ineq:u_uniform_second_moment} give the cap by $1$. Thus the last estimate holds for all $y,z\in{\mathbb X}$.

		Therefore,  it holds uniformly in $x,z \in {\mathbb X}$ and $\delta \in (0,1]$ that
		\begin{align}
			&\int_{\mathbb X} r_{t-s}^\varepsilon(y,x) \|\sigma(s,y,u(s,y)) - \sigma(s,z,u(s,z))\|_{L^2_\Omega} G_\varepsilon(z,y)m(\mathrm dy)\\
			\lesssim &\left( \left(\frac{\delta^\xi}{s^\beta}\wedge 1\right)\int_{d(z,y)\le \delta} + \int_{d(z,y) > \delta}\right) r_{t-s}^\varepsilon(y,x) G_\varepsilon(z,y)m(\mathrm{d}y)
		\end{align}
		Hence, for each $T>0$, it holds uniformly in $\varepsilon\in(0,1]$ and $(t,x)\in(0,T]\times{\mathbb X}$ that
		\begin{align}
			J_7(\varepsilon,t,x) \lesssim \int_0^{t} J_{7,1}(\varepsilon,t,s,x) + J_{7,2}(\varepsilon,t-s,x) \mathrm d s 
		\end{align}
		where 
		\begin{equation}\label{ineq:J71}
			\begin{aligned}
				J_{7,1}(\varepsilon,t,s,x)&\,\,: = \left(\frac{\delta^\xi}{s^\beta}\wedge 1 \right) \Norm*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)G_\varepsilon(\cdot,y)m(\mathrm dy)}_{\mathcal H_K}^2 \\
				&\overset{\eqref{ineq:mollified_conv_H_norm}}{\lesssim} \left(\frac{\delta^\xi}{s^\beta}\wedge 1 \right)(t-s)^{-\alpha},
			\end{aligned}
		\end{equation}
		uniformly in $\delta, \varepsilon \in (0,1]$, $0<s<t\le T$, $x \in {\mathbb X}$,  and 
		\begin{align}
			J_{7,2}(\varepsilon,t-s,x):&\,\,= \left\|\int_{\mathbb X} \mathbf 1_{B_\delta(y)^c}(\cdot) r_{t-s}^\varepsilon(y,x) G_\varepsilon(\cdot,y) m(\mathrm dy)\right\|_{\mathcal H_K}^2\\
			&\,\,\le  \Parentheses*{\int_{\mathbb X}  r_{t-s}^\varepsilon(y,x) \Norm*{\mathbf 1_{B_\delta(y)^c}(\cdot) G_\varepsilon(\cdot,y)}_{\mathcal H_K} m(\mathrm dy)}^2\\
			&\overset{\eqref{ineq:R_bound}}{\lesssim} \sup_{y \in {\mathbb X}} \Norm*{\mathbf 1_{B_\delta(y)^c}(\cdot) G_\varepsilon(\cdot,y)}_{\mathcal H_K}^2,
		\end{align}
		uniformly in $\delta,\varepsilon\in(0,1]$, $0<s<t\le T$, and $x\in{\mathbb X}$. Here we used Minkowski's inequality.


		Fix $\theta\in(0,1]$ so that $\alpha+\theta\beta<1$. Since $a\wedge1\le a^\theta$ for every $a\ge0$, \eqref{ineq:J71} gives, uniformly in $(t,x)\in (0,T]\times {\mathbb X}$ and $\delta, \varepsilon \in (0,1)$,
		\begin{align}
			\int_0^t J_{7,1}(\varepsilon,t,s,x) \mathrm ds
			&\lesssim \int_0^t\left(\frac{\delta^\xi}{s^\beta}\wedge 1 \right)(t-s)^{-\alpha}\mathrm ds \\
			&\le \delta^{\xi\theta}\int_0^t s^{-\theta\beta}(t-s)^{-\alpha}\mathrm ds\\
			&= \delta^{\xi\theta}t^{1-\alpha-\theta\beta}
			\int_0^1 r^{-\theta\beta}(1-r)^{-\alpha}\mathrm dr\\
			&\lesssim \delta^{\xi\theta}.
		\end{align}
		Hence, it holds uniformly in  $\delta \in (0,1]$ that 
		\begin{align}
			\limsup_{\varepsilon\downarrow0}\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}J_7(\varepsilon,t,x)
			&\lesssim \delta^{\xi\theta}+T\limsup_{\varepsilon\downarrow0}\sup_{y\in{\mathbb X}}
			\left\|\mathbf1_{B_\delta(y)^c}(\cdot)G_\varepsilon(\cdot,y)\right\|_{\mathcal H_K}^2
			\overset{\eqref{cond:hk_uni_bound}}{\le}\delta^{\xi\theta}.
		\end{align}
		Since $\delta>0$ is arbitrary, we see $\lim_{\varepsilon \downarrow 0 }\sup_{t\in[0,T]}\sup_{x \in {\mathbb X}} J_7(\varepsilon,t,x) = 0.$


		Since $u_\varepsilon(0,x)=u(0,x)=f(x)$ for all $x \in {\mathbb X}$, we have $U_\varepsilon(0)=0$. Collecting all terms, for every $t\in(0,T]$ and sufficiently small $\varepsilon>0$, we have
		\begin{align}
			&U_\varepsilon(t) \lesssim \int_0^t (t-s)^{-\alpha}U_\varepsilon(s) \mathrm ds +H_\varepsilon(t)+e^{-c_T \frac{t}{\varepsilon}} + \frac{\gamma_\varepsilon}{t^\beta}
		\end{align}
		for some $H_\varepsilon(t)$ with $\lim_{\varepsilon\downarrow 0} \sup_{t \in [0,T]} H_\varepsilon(t) = 0.$
		By the Volterra--Gr\"{o}nwall inequality (see for example, \cite{chu1967gronwall}), we obtain, uniformly in $t\in(0,T]$ and all sufficiently small $\varepsilon>0$,
		\begin{align}
			U_\varepsilon(t) &\lesssim H_\varepsilon(t) + e^{-c_T \frac{t}{\varepsilon}} + \frac{\gamma_\varepsilon}{t^\beta} \\
			&\quad\quad\quad+ \int_0^t \left( H_\varepsilon(s) + e^{-c_T \frac{s}{\varepsilon}} + \frac{\gamma_\varepsilon}{s^\beta}\right)(t-s)^{-\alpha} \exp \left( \int_s^t (t-\tau)^{-\alpha} \mathrm d\tau\right) \mathrm ds
		\end{align}
		which converges to zero for each $t>0$ by the dominated convergence theorem. 
		Since $u_\varepsilon(t,x)\ge 0$ almost surely for each $(t,x) \in \mathbb{R}_+\times {\mathbb X}$ and $\varepsilon \in (0,1]$, we see that $u(t,x)\ge 0$ almost surely for each $(t,x) \in \mathbb{R}_+\times {\mathbb X}$.
		Thus, by separability of $\mathbb{R}_+\times {\mathbb X}$ and the joint continuity of $u$, we see $u$ is non-negative.

\label{prop:approximation of coefficients}
		Under the standing assumptions of this section, suppose that $f$ is bounded and \eqref{ineq:non_negativity_coef_bound_at_zero} holds.
		Then there exist sequences $(b_n)_{n \in \mathbb{N}}$ and  $(\sigma_n)_{n \in \mathbb{N}}$ of predictable functions
		on the product space $\Omega \times \mathbb R_+ \times {\mathbb X} \times \mathbb R$ so that 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:FineNConditions}] for each $n\in \mathbb N$, \eqref{eq:LiG}, \eqref{ineq:g_lip}, \eqref{eq:con}, \eqref{ineq:non_negativity_coef_bound_at_zero} and \eqref{ineq:non_negative_approx_coef_ineq} hold with $b$ and $\sigma$ being replaced by $b_n$ and $\sigma_n$; and that
			\item[\refstepcounter{equation}(\theequation)\label{eq:Approximation}] for every $T>0$ and $\lambda>0$,
			\begin{align}
				\lim_{n\to\infty}\sup_{t\in[0,T]}\sup_{x\in{\mathbb X}}
				h(x)^{-\lambda}\Norm*{u^{(n)}(t,x)-u(t,x)}_{L^2_\Omega}=0,
			\end{align}
			where, for each $n\in \mathbb N$, $(u^{(n)}_t)_{t\geq 0}$ is the unique strong solution to the equation
			\begin{align}\label{eq:n}
				\begin{cases}
					\partial_t u^{(n)}_t(x) 
					= \mathcal L^* u^{(n)}_t(x)+b_n\Parentheses*{t,x,u^{(n)}_t(x)} + \sigma_n\Parentheses*{t,x,u^{(n)}_t(x)} \dot{W}_t(x), \quad (t,x)\in \mathbb R_+\times {\mathbb X},
					\\u^{(n)}_0(x) = f(x), \quad x\in {\mathbb X}.
				\end{cases}
			\end{align}
		\end{itemize}

\label{prop:non-negative2}
		Suppose that $f$ is non-negative and bounded, and that \eqref{ineq:non_negativity_coef_bound_at_zero} holds.
		Then, the unique strong solution $u$ to the SPDE  \eqref{eq:spde} is non-negative.

Define an adapted $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued continuous process $(v_t)_{t \ge 0}$ via
		\begin{align}
			v_t(x) = u_t(x) - u'_t(x),\qquad (t,x) \in \mathbb{R}_+\times {\mathbb X}.
		\end{align}
		Note that for every $T>0$ and  $(t,x)\in [0,T]\times {\mathbb X}$, almost surely,
		\begin{align}
			v_t(x) = P^*_t f_0(x)
			&+ \int_0^t \mathrm ds \int_{\mathbb X}  G(s,y;t,x) \widetilde b(s,y, v_s(y)) 
			m(\mathrm d y) \\
			&+ \iint_0^t  G(s,y;t,x) \widetilde \sigma(s,y,v_s(y)) 
			W(\mathrm ds,\mathrm dy), 
			\label{eq:vtx}
		\end{align}
		where $f_0 := f - f' \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ and for all $(s,y) \in \mathbb{R}_+\times {\mathbb X}$ and $r\in \mathbb R$ 
		\begin{align}
			(\tilde b(\omega,s,y,r))_{\omega \in \Omega} := 
			\widetilde b(s,y,r)&:= b\Parentheses*{s,y,
				r
				+u_s'(y)} - b(s,y,u'_s(y))\\
			(\tilde \sigma(\omega,s,y,r))_{\omega \in \Omega} := 
			\widetilde \sigma(s,y,
			r)&:= \sigma\Parentheses*{s,y, r+u_s'(y)} - \sigma(s,y,u'_s(y)).
		\end{align}
		Since $u'$ is adapted with continuous
		$\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued paths, it is predictable; hence
		$\widetilde b$ and $\widetilde\sigma$ are predictable. Moreover,
		\eqref{eq:con} and the continuity of $u'_t$ show that they also satisfy
		\eqref{eq:con}.
		We can verify that 
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:tildeL}] $\tilde b$ and $\tilde \sigma$ satisfy the linear growth condition \eqref{eq:LiG} and the Lipschitz condition \eqref{ineq:g_lip} with $b$ and $\sigma$ being replaced by $\tilde b$ and $\tilde \sigma$.  
		\end{itemize}
		In fact, for every $T>0$, uniformly for every $\omega\in \Omega\setminus\mathrm{N}_{\ref{c:Lip}}$, $t\in [0,T]$, $r,r'\in \mathbb R$ and $x\in {\mathbb X}$, it holds that
		\begin{align}
			|\tilde b(\omega, t,x,r) |+|\tilde\sigma(\omega, t,x,r)| 
			&= |b\Parentheses*{\omega,t,x,r+u'(\omega, t, x)} - b(\omega,t,x,u'(\omega, t, x))| 
			\\& \qquad +|\sigma\Parentheses*{\omega,t,x,r+u'(\omega, t, x)} - \sigma(\omega,t,x,u'(\omega, t, x))| 
			\\& \overset{\eqref{ineq:g_lip}}{\lesssim} |r|, \label{eq:tbtsr}
		\end{align}
		and that
		\begin{align}
			&\quad |\tilde b(\omega, t,x,r) - \tilde b(\omega, t,x,r')|+|\tilde \sigma(\omega, t,x,r)-\tilde \sigma(\omega, t,x,r')| 
			\\&=| b\Parentheses*{\omega,t,x,r+u'(\omega, t, x)}  - b\Parentheses*{\omega,t,x,r'+u'(\omega, t, x)}  | 
			\\&\qquad +| \sigma\Parentheses*{\omega,t,x,r+u'(\omega, t, x)}  - \sigma\Parentheses*{\omega,t,x,r'+u'(\omega, t, x)}  |
			\\&{\overset{\eqref{ineq:g_lip}}{\lesssim} }|r - r'|.
		\end{align}
		In particular,  Theorem \ref{thm:main2}, \eqref{eq:tildeL} and \eqref{eq:vtx} now say that $(v_t)_{t\geq 0}$ is the unique strong solution to the SPDE
		\begin{equation}
			\begin{cases}
				\partial_t v_t(x) 
				= \mathcal L^* v_t(x) + \tilde b\left(t, x, v_t(x)\right) + \tilde\sigma\left(t, x ,v_t(x)\right) \dot W_t(x),
				\quad t \in \mathbb R_+,\, x \in {\mathbb X},
				\\ v_0(x) = f_0(x), \quad x\in {\mathbb X}.
			\end{cases}
		\end{equation}

		Since $f_0\in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ is non-negative, we can take a sequence $(f^{(k)}_0)_{k \in \mathbb N}$ of non-negative bounded elements in $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ which converges to $f_0$ in $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.
		From Theorem \ref{thm:main2} and \eqref{eq:tildeL}, for each $k\in \mathbb N$, there exists a unique strong solution $(v^{(k)}_t)_{t\geq 0}$ to the SPDE 
		\begin{equation}
			\begin{cases}
				\partial_t v^{(k)}_t(x) 
				= \mathcal L^* v^{(k)}_t(x) + \tilde b\left(t, x, v^{(k)}_t(x)\right) + \tilde\sigma\left(t, x ,v^{(k)}_t(x)\right) \dot W_t(x),
				\quad t \in \mathbb R_+,\, x \in {\mathbb X},
				\\ v^{(k)}_0(x) = f_0^{(k)}(x), \quad x\in {\mathbb X}.
			\end{cases}
		\end{equation}
		By \eqref{eq:tildeL} and Proposition \ref{prop:continuity_initial}, we know that 
		\begin{equation}\label{eq:v}
			\lim_{k\to \infty}\|v^{(k)}  -v\|_{\mathbb M_{\lambda, p}(T)} = 0
		\end{equation}
		for every $p \ge 2$, $\lambda >0$ and $T>0$.

		Taking $r=0$ in \eqref{eq:tbtsr}, we obtain
		$\widetilde b(t,x,0)=\widetilde\sigma(t,x,0)=0$, and hence
		\begin{itemize}
			\item[\refstepcounter{equation}(\theequation)\label{eq:tildeLM}] $\tilde b$ and $\tilde \sigma$ satisfy  \eqref{ineq:non_negativity_coef_bound_at_zero} with $b$ and $\sigma$ being replaced by $\tilde b$ and $\tilde \sigma$.  
		\end{itemize}
		Now, for each $k\in \mathbb N$, by Proposition \ref{prop:non-negative2}, \eqref{eq:tildeLM}, and the fact that $f^{(k)}_0\in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ is non-negative and bounded, we have that $v^{(k)}$ is non-negative.  
		Combining this with the separability of ${\mathbb X}$, continuity of $v$  and \eqref{eq:v}, we see that $v=u-u'$ is also non-negative as desired.

\label{lem:product metric entropy}
		Suppose $(\mathcal X,d_\mathcal X)$ and $\Parentheses*{\mathcal Y,d_\mathcal Y}$ are metric spaces with finite radius such that for some $\beta_\mathcal X,\beta_\mathcal Y >0$, it holds uniformly in $\varepsilon\in (0,1]$ that 
		\begin{align}
			D(\mathcal X,d_\mathcal X; \varepsilon)\lesssim \varepsilon^{-\beta_\mathcal X},\qquad D(\mathcal Y,d_\mathcal Y; \varepsilon)\lesssim \varepsilon^{-\beta_\mathcal Y}.
		\end{align}
		Suppose $\xi_\mathcal X,\xi_\mathcal Y \in (0,1]$ and let $\mathcal S:= \mathcal X \times \mathcal Y$ equipped with the metric $d_\mathcal S\Parentheses*{(x,y),(x',y')}:= d_\mathcal X(x,x')^{\xi_\mathcal X}+d_\mathcal Y(y,y')^{\xi_\mathcal Y}$. Then 
		\begin{align}
			D\Parentheses*{\mathcal S,d_\mathcal S; \varepsilon} \lesssim \varepsilon^{-\Parentheses*{\frac{\beta_\mathcal X}{\xi_\mathcal X}+\frac{\beta_\mathcal Y}{\xi_\mathcal Y}}},\quad \text{ uniformly in }\varepsilon \in (0,1].
		\end{align}

\label{prop:MLDP}
		Let $T,R >0$, $x_0 \in {\mathbb X}$ and assume the following assumptions hold:
		\begin{enumerate}
			\item There is some $\beta_0 > 0$ so that $D(B_R(x_0),d; \varepsilon) \lesssim \varepsilon^{-\beta_0}$ uniformly for $\varepsilon \in (0,1]$, where $D$ is defined at the beginning of this subsection.
			\item $g_{t,x}(s,y):=g(t,s,x,y)$ on $ \mathbb{R}_+\times \mathbb{R}_+\times {\mathbb X} \times {\mathbb X}$ and $\eta(s,y)$ on $\mathbb{R}_+ \times {\mathbb X}$ are non-negative deterministic real-valued functions. There are $\xi_1,\xi_2 \in (0,1]$ such that the supremum below is finite, and we set
			\begin{align}\label{ineq:ldp local holder type condition}
				B:= \|Q\|\sup_{t,t' \in [0,T],\, x,x' \in B_R(x_0)} \frac{\int_0^\infty \left\| \left|g_{t,x}(s,\cdot) - g_{t',x'}(s,\cdot)\right| \eta(s,\cdot)\right\|_{\mathcal H_K}^2 \mathrm ds}{\left(\frac{d(x,x')}{2R}\right)^{\xi_1} + \left|\frac{t-t'}{T}\right|^{\xi_2}}.
			\end{align}
			Moreover, suppose there exists $(t_*,x_*)\in[0,T]\times B_R(x_0)$ such that
			\begin{align}
				\int_0^\infty
				\Norm*{g_{t_*,x_*}(s,\cdot)\eta(s,\cdot)}_{\mathcal H_K}^2
				\mathrm ds<\infty.
			\end{align}
			\item $\sigma$ is a predictable random field on $\mathbb{R}_+ \times {\mathbb X}$ so that 
			\begin{align}
				\left|\sigma(t,x) \right| \le \eta(t,x),\quad \text{almost surely for all } (t,x) \in \mathbb{R}_+ \times {\mathbb X}.
			\end{align}
		\end{enumerate}
		For $(t,x) \in [0,T]\times B_R(x_0)$, let
		\begin{align}\label{eq:s_conv}
			N(t,x):= \int_0^\infty \int_{\mathbb X} g(t,s,x,y)\sigma(s,y)  W(\mathrm ds,\mathrm dy).
		\end{align}
		Then there is a jointly continuous modification $\widetilde{N}(t,x)$ of $N(t,x)$ on $[0,T] \times B_R(x_0)$, so that for  $c:=  4\sum_{n= 1}^\infty  \sqrt{n}2^{-n/2} $, the following inequality holds uniformly in $\lambda > 0$, with an implicit constant independent of $T$, $B$ and $\sigma$,
		\begin{align}\label{ineq:MLDP_local}
			{\mathbb P} \left( \sup_{(t,x),(t',x') \in [0,T]\times B_R(x_0)} \left| \widetilde{N}(t,x) - \widetilde{N}(t',x') \right| > \lambda\right) \lesssim \exp\left(- \frac{\lambda^2}{2c^2B}\right).
		\end{align}
		When $B=0$, the right-hand side of \eqref{ineq:MLDP_local} is understood as $e^{-\infty}=0$.

\label{lem:mod_cont_sconv}
		Under the assumptions and notations of Proposition \ref{prop:MLDP}, for all \(t,t'\in[0,T]\), \(x,x'\in B_R(x_0)\), and \(\lambda>0\),
		\begin{align}\label{ineq:s_cont1}
			\mathbb{P} \left(\left|N(t,x) - N(t',x') \right| > \sqrt{B}\lambda \right) &\le 4 \exp\left(\frac{ -\,\lambda^2}{2\left( \left(\frac{d(x,x')}{2R} \right)^{\xi_1}+  \left| \frac{t-t'}{T}\right|^{\xi_2}\right)}\right).
		\end{align}

If $B=0$, then the stochastic-integral isometry, Lemma \ref{lem:HS}, \eqref{ineq:ldp local holder type condition}, and $|\sigma|\le\eta$ imply that $N(t,x)-N(t',x')=0$ in $L^2(\Omega)$ for every $(t,x),(t',x')\in[0,T]\times B_R(x_0)$, so \eqref{ineq:s_cont1} is immediate. Hence, we may assume $B>0$.

		For $t,t'\in[0,T]$, $x,x'\in B_R(x_0)$, and $\tau\ge0$, define the difference martingale
		\begin{align*}
			M_{(t,t'),(x,x')}(\tau)
			:=\int_0^\infty\int_{\mathbb X} \mathbf 1_{[0,\tau]}(s)
			\big(g_{t,x}(s,y)-g_{t',x'}(s,y)\big)\sigma(s,y)
			W(\mathrm ds,\mathrm dy).
		\end{align*}
		Then $\big(M_{(t,t'),(x,x')}(\tau)\big)_{\tau\ge0}$ is a continuous martingale. By  Lemma \ref{lem:HS}, it holds almost surely for every $\tau\ge0$ that
		\begin{align}
			\left[ M_{(t,t'),(x,x')} \right]_\tau &= \int_0^\tau \Norm*{Q^{1/2}\left[\left(g_{t,x}(s,\cdot) - g_{t',x'}(s,\cdot)\right) \sigma(s,\cdot)\right]_K}_{\tilde{\mathcal H}_{K}}^2 \mathrm ds\\
			&\,\,\le \|Q\|\int_0^\tau \left\| \left(g_{t,x}(s,\cdot) - g_{t',x'}(s,\cdot)\right)\sigma(s,\cdot)\right\|_{\mathcal H_K}^2 \mathrm ds\\
			&\,\,\le \|Q\|\int_0^\tau \left\| \left|g_{t,x}(s,\cdot) - g_{t',x'}(s,\cdot)\right| \eta(s,\cdot)\right\|_{\mathcal H_K}^2 \mathrm ds\\
			&\overset{\eqref{ineq:ldp local holder type condition}}{\le} \left( \left(\frac{d(x,x')}{2R} \right)^{\xi_1}+  \left| \frac{t-t'}{T}\right|^{\xi_2}\right) B.
		\end{align}
		The last bound shows that this martingale has finite energy and is bounded in $L^2(\Omega)$. Hence, by the martingale convergence theorem and the stochastic-integral isometry,
		\begin{align*}
			M_{(t,t'),(x,x')}(\tau)
			\longrightarrow M_{(t,t'),(x,x')}(\infty)
			=N(t,x)-N(t',x')
		\end{align*}
		almost surely and in $L^2(\Omega)$ as $\tau\to\infty$. By the Dambis--Dubins--Schwarz theorem \cite[Chapter~V, Theorem~(1.7)]{revuz1999continuous}, after enlarging the probability space if necessary, there is a Brownian motion $(\mathcal B_r)_{r\ge0}$ such that
		\(M_{(t,t'),(x,x')}(\tau)=\mathcal B_{[M_{(t,t'),(x,x')}]_\tau}\) for every $\tau\ge0$. Therefore, martingale convergence and the reflection principle give
		\begin{align}
			\mathbb{P}\left(\left|N(t,x)-N(t',x')\right| > \sqrt{B}\lambda\right)
			&=\mathbb{P}\left(\left|M_{(t,t'),(x,x')}(\infty)\right| > \sqrt{B}\lambda\right)\\
			&\le \mathbb{P}\left(\sup_{0 \le r \le  \left( \left(\frac{d(x,x')}{2R} \right)^{\xi_1}+  \left| \frac{t-t'}{T}\right|^{\xi_2}\right) B} |\mathcal B_r| > \sqrt{B}\lambda\right)\\
			&\le 4 \exp\left(\frac{ -\,\lambda^2}{2\left( \left(\frac{d(x,x')}{2R} \right)^{\xi_1}+  \left| \frac{t-t'}{T}\right|^{\xi_2}\right)}\right).
		\end{align}
		Where we used the standard Gaussian tail bound: if $X$ is a centered Gaussian random variable with variance $\nu>0$, then
		\begin{align}
			{\mathbb P} \left(|X|> \lambda \right) \le 2 e^{- \frac{\lambda^2}{2\nu}}.
		\end{align}

If $B=0$, then the same zero-increment argument shows that $\widetilde N(t,x):=N(t_*,x_*)$ is a jointly continuous modification of $N$ on $[0,T]\times B_R(x_0)$. Consequently, the probability in \eqref{ineq:MLDP_local} is zero for every $\lambda>0$, and the conclusion follows from the convention above. Hence, suppose $B>0$ for the remainder of the proof.

		Since $\xi_1,\xi_2 \in (0,1]$, we may define the set ${\mathcal T}:= [0,T] \times B_R(x_0)$ and the new metric $d_{\mathcal T}$ on $\mathcal T$ by 
		\begin{align}
			d_{\mathcal T}((s,x),(s',x')):= \frac{1}{2} \left(\left(\frac{d(x,x')}{2R} \right)^{\xi_1}+ \left|\frac{s-s'}{T} \right|^{\xi_2}\right),\quad (s,x),\, (s',x') \in \mathcal T.
		\end{align}
		Then $({\mathcal T}, d_\mathcal T)$ is a metric space with diameter  at most $1$.   Recall $D(\mathcal T,d_\mathcal T; \varepsilon)$ defined right before Lemma \ref{lem:product metric entropy}, by Lemma \ref{lem:product metric entropy}, we see for  $\beta = \frac{1}{\xi_2} + \frac{\beta_0}{\xi_1}$, there is a positive constant $\refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:lld_tem1} = \ensuremath{C_{\ref{c:lld_tem1}}}>0$, depending on the covering constant in assumption~(1) and on $R,\beta_0,\xi_1,\xi_2$, so that 
		\begin{align}\label{ineq:comb_entro}
			D({\mathcal T},d_{\mathcal T}; \varepsilon) \le \ensuremath{C_{\ref{c:lld_tem1}}} \varepsilon^{-\beta},\quad  \text{ uniformly in }0<\varepsilon  <1.
		\end{align}
		Next, we construct a countable dense sequence of points in $\mathcal T$.
		Denote $B_{\mathcal T}(t,r)$ as the open ball in ${\mathcal T}$ centered at $t \in {\mathcal T}$ with radius $r>0$ under the metric $d_{\mathcal T}$.
		Pick any $t_0 \in {\mathcal T}$ and let ${\mathcal T}_0 = \{t_0\}$.
		For $n \ge 1$, we can find  ${\mathcal T}_n := \{x_i\}_{i \in I_n}$ with $|I_n| \le \ensuremath{C_{\ref{c:lld_tem1}}} 2^{\beta n}$, where $|I_n|$ denotes the cardinality of $I_n$,  and
		\begin{align}
			{\mathcal T} \subset \bigcup_{i \in I_n} B_{\mathcal T}\left(x_i,\frac{1}{2^{n}}\right).
		\end{align}
		Finally, we let ${\mathcal T}_\infty := \bigcup_{n \ge 0} {\mathcal T}_n$ which is dense in ${\mathcal T}$. 

		Now we define the chaining map $\pi_n : {\mathcal T}_{n} \to {\mathcal T}_{n-1}$ for $n \ge 1$ that ‘chains' the points that are close together. By construction, for any $n \ge 1$ and $t \in {\mathcal T}_n$, there is $t_{n-1} \in {\mathcal T}_{n-1}$ so that $d_{\mathcal T}(t,t_{n-1}) \le 2^{-n+1}.$ For each $t \in {\mathcal T}_n$, we choose exactly one such $t_{n-1} \in {\mathcal T}_{n-1}$ and define $\pi_n(t):= t_{n-1}$ and  set $\pi_0(t_0) = t_0$.

		For $\rho > 2^{2\beta }$, we define the  events
		$$
		A_\rho := \bigcap_{n \ge 1} \left\{\left|N(t) - N(\pi_n(t)) \right| \le c_n(\rho),\quad \text{ for all } t \in {\mathcal T}_n\right\}
		$$
        where $c_n(\rho) = 2\sqrt{Bn\ln(\rho)}\,2^{-n/2}$.
		Observe that on the event $A_\rho$, for any $n \ge 1$ and $t \in {\mathcal T}_n$, where $\pi_{n+1}\circ \dots \circ \pi_n$ denotes the identity map,
			\begin{align}
				\left|N(t) - N(t_0)\right| &\le \sum_{i = 1}^n \left|N\left(\pi_{i+1}\circ \dots \circ \pi_n(t)\right) - N\left(\pi_i \circ \dots \circ \pi_n(t) \right) \right|\\
				&\le 2\sqrt{B \ln (\rho)} \sum_{i = 1}^\infty  \sqrt{i2^{-i}},
			\end{align}
		and hence  
		\begin{align}\label{ineq: sup distance a rho}
			\sup_{t,t' \in {\mathcal T}_\infty}\left|N(t) - N(t') \right| \le 4\sqrt{B\ln (\rho)} \sum_{n \ge 1}\sqrt{n}2^{-n/2}.
		\end{align}
		Then by Lemma \ref{lem:mod_cont_sconv},
		\begin{align}
			{\mathbb P} \left( A^c_\rho\right) &\,\,\,\le \sum_{n = 1}^\infty \sum_{t \in {\mathcal T}_n} {\mathbb P} \left(\left|N(t) - N(\pi_n(t)) \right| > c_n(\rho)\right)\\
			&\,\,\,\le 4 \sum_{n = 1}^\infty \sum_{t \in {\mathcal T}_n} \exp\left(-  \frac{c_n(\rho)^2}{4d_{\mathcal T}(t,\pi_n(t)) B} \right)\\
			&\overset{\eqref{ineq:comb_entro}}{\le} 4\ensuremath{C_{\ref{c:lld_tem1}}}\sum_{n = 1}^\infty 2^{\beta n} \exp \left(-  n \ln(\rho)/2 \right)\\
			&\,\,\,= 4 \ensuremath{C_{\ref{c:lld_tem1}}} \sum_{n = 1}^\infty\left( 2^\beta  \rho^{-\frac{1}{2}}\right)^n\\
			&\,\,\,= \frac{4 \ensuremath{C_{\ref{c:lld_tem1}}} 2^\beta }{ \rho^{\frac{1}{2}}- 2^\beta }.
		\end{align}

		Fix $\lambda>0$ and set $\rho:=\exp(\lambda^2)$. Let $c:=  4\sum_{n = 1}^\infty  \sqrt{n}2^{-n/2} $. If $\rho > 2^{2\beta +2}$, then by \eqref{ineq: sup distance a rho},
		\begin{align}\label{ineq:mldp_last}
			{\mathbb P} \left(\sup_{t,t' \in {\mathcal T}_\infty}\left|N(t) - N(t') \right| > c \lambda \sqrt{B} \right) \le {\mathbb P} \left( A_\rho^c\right) \le  \frac{4 \ensuremath{C_{\ref{c:lld_tem1}}} 2^\beta }{ \rho^{\frac{1}{2}}- 2^\beta } \le \frac{8 \ensuremath{C_{\ref{c:lld_tem1}}} 2^\beta}{\rho^{\frac{1}{2}}} = \frac{8 \ensuremath{C_{\ref{c:lld_tem1}}} 2^{\beta}}{\exp\left(\lambda^2/2\right)}.
		\end{align}
		If $\rho  \in \left[1, 2^{2\beta+2}\right]$, we see $\exp \left(-\frac{\lambda^2}{2} \right)\ge 2^{-\beta -1}$.
		Hence $8 \max\left\{\ensuremath{C_{\ref{c:lld_tem1}}},1 \right\}2^\beta \exp\left(- \lambda^2/2 \right) \ge 1$.
		So we get for all $\lambda >0$
		\begin{align}
			{\mathbb P} \left(\sup_{t,t' \in {\mathcal T}_\infty}\left|N(t) - N(t') \right| > c \lambda \sqrt{B} \right) \le \frac{8\max\left\{ \ensuremath{C_{\ref{c:lld_tem1}}} ,1\right\} 2^{\beta}}{\exp\left(\lambda^2 / 2 \right)}.
		\end{align}
			Finally, integrating \eqref{ineq:s_cont1} yields, for every $p\ge1$ and $z,z'\in\mathcal T$,
			\[
				\mathbb E\left[|N(z)-N(z')|^p\right]\le C_p B^{p/2}d_{\mathcal T}(z,z')^{p/2}.
			\]
			Choosing $p>2\beta$, \cite[Theorem 2.3.1]{khoshnevisan2002multiparameter} gives a continuous modification. Since ${\mathcal T}_\infty$ is countable, on a common full-measure event the modification agrees with $N$ on ${\mathcal T}_\infty$, and by density and continuity the preceding dense-set supremum bound transfers to the supremum over all of ${\mathcal T}$, yielding the desired inequality.

\label{lem:exp_ineq_elementary}
		Suppose $y >0$ and $x \ge 1$, then
		$\exp\left( - yx\right) \le  \frac{\exp\left( - y/2\right)}{xy}$.

\label{lem:mldp_global}
		Suppose the conditions of Proposition \ref{prop:MLDP} hold, $({\mathbb X},d)$ satisfies \eqref{ineq:entropy bound} and  $h:{\mathbb X} \to [1,\infty)$ is a weight function.
		Let  $\lambda_0>0$ be as in \eqref{ineq:faster_than_ms} and $\lambda > 0$.
			Assume there is $\alpha > 0$ so that for each $T>0$,  the following inequality holds uniformly in $  (t,x) \in (0,T]\times {\mathbb X}$,
			\begin{align}\label{ineq:var_bound_h}
				\sup_{s,s' \in [0,t],\, y,y' \in B_1(x)} \frac{\int_0^\infty \left\| \left|g_{s,y}(\tau,\cdot) - g_{s',y'}(\tau,\cdot)\right| \eta(\tau,\cdot)\right\|_{\mathcal H_K}^2 \mathrm d\tau}{\left(\frac{d(y,y')}{2}\right)^{\xi_1} + \left|\frac{s-s'}{t}\right|^{\xi_2}}
				\lesssim h(x)^{2\lambda - \lambda_0}t^\alpha.
			\end{align}
			Let $N(t,x)$ be as in \eqref{eq:s_conv}, and assume that the continuous modification provided by Proposition \ref{prop:MLDP} satisfies $N(0,\cdot)\equiv0$ almost surely. Then, for each $T>0$, there exists $ \refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:gld_4} = \ensuremath{C_{\ref{c:gld_4}}}(T,\lambda) > 0$ so that uniformly for $t \in (0,T]$ and $\varepsilon \in (0,1)$,
			\begin{align}
				{\mathbb P} \left(\sup_{(s,x) \in [0,t]\times {\mathbb X}} |N(s,x)|h(x)^{-\lambda} > \varepsilon \right) \lesssim  \varepsilon^{-2} t^\alpha \exp\left( - \frac{\ensuremath{C_{\ref{c:gld_4}}}}{2t^\alpha}\varepsilon^2\right).
			\end{align}
			For $t=0$, the left hand side is zero, so the estimate is trivial.

\label{lem:m_ldp_g}
		Under the assumptions of Theorem  \ref{thm:main2} with $\lambda_0>0$ as in \eqref{ineq:faster_than_ms}{, let} $\alpha \in (0,1)$, $\lambda>0$ and $\eta:\mathbb{R}_+ \times {\mathbb X} \to \mathbb{R}_+$ be a deterministic measurable function. Suppose there exist $\xi_1,\xi_2\in(0,1]$ so that, for each $T>0$, the following inequality holds uniformly in $(t,x) \in (0,T]\times {\mathbb X}$:
		\begin{align}\label{ineq:var_bound_h_k}
			\sup_{s,s' \in [0,t],\, y,y' \in B_1(x)} \frac{\int_0^{s\vee s'} \left\|\left|G_{s - \tau}(\cdot,y) - G_{s' - \tau}(\cdot,y')\right|\eta(\tau,\cdot)\right\|_{\mathcal H_K}^2 \mathrm d\tau}{d(y,y')^{\xi_1} + \left|s-s'\right|^{\xi_2}}
			\lesssim h(x)^{2\lambda - \lambda_0}t^{1-\alpha}.
		\end{align}
		 Let $T>0$ and suppose $(f(t,x),\, (t,x) \in \mathbb{R}_+ \times {\mathbb X})$ is a predictable random field so that   $|f(t,x)| \le \eta(t,x)$ almost surely for all $(t,x) \in [0,T] \times {\mathbb X}$. If we let 
		\begin{align}
			N(t,x):= \int_0^t \int_{\mathbb X} G_{t-s}(y,x)f(s,y)W(\mathrm dy\,\mathrm ds),\quad (t,x) \in \mathbb{R}_+ \times {\mathbb X},
		\end{align}
		then  there exists $ \refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:gld_3} = \ensuremath{C_{\ref{c:gld_3}}}(T,\lambda) > 0$ so that 
		\begin{align}
			{\mathbb P} \left(\sup_{(s,x) \in [0,t]\times {\mathbb X}} |N(s,x)|h(x) ^{-\lambda}> \varepsilon \right) \lesssim \varepsilon^{-2} t^{1-\alpha} \exp\left( - \frac{\ensuremath{C_{\ref{c:gld_3}}}}{2t^{1-\alpha}}\varepsilon^2\right),
		\end{align}
		uniformly in $t\in (0,T],\, \varepsilon\in (0,1)$.

\label{lem:metric_entropy_Lp_chain}
	Let $(\mathcal T, d_{\mathcal T})$ be a complete metric space of diameter at most $2$, suppose  there exists $c_0>0$ so that $D(\mathcal T, d_{\mathcal T}; \varepsilon) \le c_0 \varepsilon^{-\mathfrak{b}}$ for all $\varepsilon \in (0,2)$. Suppose $B>0$, $p >\mathfrak{b}$ and  $(N(t))_{t \in \mathcal T}$ is an almost surely continuous random field on $\mathcal T$ such that
	\begin{align}\label{ineq:metric_entropy_Lp_chain_moment_bound}
		\Norm*{N(t) - N(t')}_{L^p_\Omega} \le B d_{\mathcal T}(t,t'),\quad \text{ for all } t,t' \in \mathcal T.
	\end{align}
	Then there exists $\refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:kol_constant} = \ensuremath{C_{\ref{c:kol_constant}}}(p,\mathfrak{b},c_0)>0$ so that for every $t_0 \in \mathcal T$, 
	\begin{align*}
		\Norm*{\sup_{t \in \mathcal T} |N(t) - N(t_0)|}_{L^p_\Omega} \le \ensuremath{C_{\ref{c:kol_constant}}} B.
	\end{align*}

\label{lem:unit_scale_stochastic_part_bound}
		Let $u$ be the $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued solution to \eqref{eq:spde_driftless} with $f \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ so that $|f(x)| \le 2$ for all $x \in {\mathbb X}$. Recall $Z$ as in \eqref{eq:nt}. Then for each $\lambda >0$, there exists $p_0 = p_0(\lambda) \ge 2$ such that for all $p \ge p_0$, there exists $\kappa := \kappa(p,\lambda)>0$ so that for all $N >0$, 
		\begin{align*}
			\mathbb P \left( \sup_{(t,x) \in [0,1]\times {\mathbb X}} |Z(t,x)|h(x)^{-\lambda} > N \right) \le S_0 \Parentheses*{\frac{\kappa}{N}}^p.
		\end{align*}
		In particular, the constants depend on the noise coefficient $\sigma$ only through the implicit constant $L>0$ in \eqref{ineq:g_lip} with $T=1$.

Note that since $f$ is continuous and bounded by $2$, we have $|u(0,x)|  = |f(x)| \le 2$ for all $x \in {\mathbb X}$. Let $\{x_n\}_n \subset {\mathbb X}$ be as in \eqref{ineq:faster_than_ms} and set $\mathcal T_n := [0,1] \times \overline{B_1(x_n)}$ for each $n \in \mathcal I$ and $d_\mathcal T((t,x),(t',x')) := \frac12\left(|t-t'|^{\xi} + d(x,x')^{\xi}\right)$ for all $(t,x),(t',x') \in \mathcal T_n$, where $\xi \in (0,1]$ is as in Proposition \ref{prop:existence of C_tem modification}. By examining the proof of Proposition \ref{prop:existence of C_tem modification}, we see for each $\lambda'\in(0,1/2)$, there exists $\refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:moment_for_stochastic_integral} = \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}(p,\lambda')>0$ so that for all $n \in \mathcal I$ and $(t,x),(t',x') \in \mathcal T_n$, it holds that
		\begin{align*}
			\Norm*{Z(t,x) - Z(t',x')}_{L^p_\Omega} \le \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}L h(x)^{\lambda'} \left(|t-t'|^{\xi} + d(x,x')^{\xi}\right) = 2\ensuremath{C_{\ref{c:moment_for_stochastic_integral}}} L h(x)^{\lambda'}d_{\mathcal T}((t,x),(t',x')),
		\end{align*}
		where $L$ is as in \eqref{ineq:g_lip} with $T=1$. First let $\lambda\in(0,1/2]$, and take $p$ sufficiently large so that $\lambda':=\lambda-\lambda_0/p\in(0,1/2)$.

		Since the implicit constant in \eqref{ineq:entropy bound} is independent of $x \in {\mathbb X}$, we see by Lemma \ref{lem:metric_entropy_Lp_chain} and Proposition \ref{prop:existence of C_tem modification}, by choosing $p > \mathfrak{b}$,  there exists $\ensuremath{C_{\ref{c:kol_constant}}} = \ensuremath{C_{\ref{c:kol_constant}}}(p,\mathfrak{b})>0$ so that for each $n \in \mathcal I$, upon taking $t_0=(0,x_n)$ and using $Z(0,x_n)=0$,
		\begin{align}
			\Norm*{\sup_{(t,x) \in \mathcal T_n} |Z(t,x)|}_{L^p_\Omega} \le 2\ensuremath{C_{\ref{c:kol_constant}}} \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}L h(x_n)^{\lambda'}.
		\end{align}
		This implies 
		\begin{align*}
			\Norm*{\sup_{(t,x) \in \mathcal T_n} |Z(t,x)|h(x)^{-\lambda}}_{L^p_\Omega}  \le 2\mathfrak{c}\ensuremath{C_{\ref{c:kol_constant}}} \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}L h(x_n)^{\lambda' - \lambda}= 2\mathfrak{c}\ensuremath{C_{\ref{c:kol_constant}}} \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}L h(x_n)^{-\lambda_0/p}.
		\end{align*}
		Therefore, by Markov's inequality, we see for each $N>0$, it holds that 
		\begin{align*}
			\mathbb P \left(\sup_{(t,x) \in [0,1]\times {\mathbb X}} |Z(t,x)|h(x)^{-\lambda} > N \right) &\le \mathbb P \left(\bigcup_{n \in \mathcal I} \left\{\sup_{(t,x) \in \mathcal T_n} |Z(t,x)|h(x)^{-\lambda} > N \right\}\right)\\
			&\le \sum_{n \in \mathcal I} \mathbb P \left(\sup_{(t,x) \in \mathcal T_n} |Z(t,x)|h(x)^{-\lambda} > N \right)\\
			&\le \sum_{n \in \mathcal I} N^{-p} \Norm*{\sup_{(t,x) \in \mathcal T_n} |Z(t,x)|h(x)^{-\lambda}}_{L^p_\Omega}^p\\
			&\le \sum_{n \in \mathcal I} N^{-p} \left(2\mathfrak{c}\ensuremath{C_{\ref{c:kol_constant}}} \ensuremath{C_{\ref{c:moment_for_stochastic_integral}}}L\right)^p h(x_n)^{-\lambda_0}\\
			&:= S_0 \Parentheses*{\frac{\kappa}{N}}^p,
		\end{align*}
		which is the desired result for $\lambda\in(0,1/2]$. If $\lambda>1/2$, then $h\ge1$ implies $h^{-\lambda}\le h^{-1/2}$, so the estimate follows from the case $\lambda=1/2$.

\label{prop:one_step_estimates}
		Let $\lambda \in (0,1/2]$, $x_0 \in {\mathbb X}$, $M,t>0$ and $0<r_0<R$ be arbitrary but fixed. Let $N_0=N_0(x_0,t,M,r_0,R)$ be as in \eqref{ineq:ip_explicite}, and denote $H:= \sup_{x \in B_R(x_0)}h(x)^{\lambda+\lambda_0/2}$.

		Suppose $\sigma(t,x,0)=0$ almost surely for all $(t,x)\in\mathbb{R}_+\times{\mathbb X}$, and let $L$ be a Lipschitz constant for $\sigma$ on $[0,1]$.
		Then, for all sufficiently large $p \ge2$, all $N \ge4 \ensuremath{C_{\ref{c:semi_group_norm}}}$, and all sufficiently large $Q\ge 1$ (independent of $N$ and $\sigma$), there exists $\kappa := \kappa(p,\lambda) >0$ such that the following holds uniformly for $r\in[r_0,R-M/Q]$: if $u$ is the solution to \eqref{eq:spde_driftless} with initial condition $g \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$ satisfying $\mathbf 1_{B_r(x_0)}(x) \le g(x) \le 2$ for all $x \in {\mathbb X}$, then
		\begin{align*}
			\mathbb{P}\left(u(s,x) \ge  \frac{1}{2N_0} \mathbf 1 _{B_{r+M/Q}(x_0)}(x),\,\, \forall(s,x) \in \left[\frac{t}{Q},\frac{2t}{Q}\right]\times {\mathbb X}\right) \ge 1- \varepsilon_{N,Q,p}
		\end{align*}
		where 
		\begin{align*}
			\varepsilon_{N,Q,p} = \ensuremath{C_{\ref{c:one_step_pre}}}S_0 \Parentheses*{LNHN_0}^2 \Parentheses*{\frac{t}{Q}}^{1-\alpha_0} \exp \left(-\ensuremath{C_{\ref{c:one_step_rate}}}\Parentheses*{LNHN_0}^{-2} \Parentheses*{\frac{Q}{t}}^{1-\alpha_0} \right) + S_0 \Parentheses*{\frac{\kappa}{N}}^p,
		\end{align*}
		for some $\refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:one_step_pre},\,\refstepcounter{constant}\ensuremath{C_{\theconstant}}\label{c:one_step_rate}>0$, independent of $L,N,Q,N_0$, where $\alpha_0\in(0,1)$ is as in Lemma~\ref{lem:hk_abs}, \eqref{ineq:hk abs holder k weighted}.

For each $N >0$, let us define 
		\begin{align}
			\tau_N:=\inf\left\{ t>0: \sup_{x \in {\mathbb X}} \Absolute*{u(t,x)}h(x)^{-\lambda} > N \right\},
		\end{align}
		which is a stopping time by the continuity of sample paths. Define for each $N >0$ that 
		\begin{align}
			Z_N(t,x):= \int_0^{t } \int_{\mathbb X} \mathbf 1_{\{s<\tau_N\}}G_{t-s}(y,x) \sigma(s,y,u(s,y)) W(\mathrm dy,\mathrm ds),\quad (t,x) \in \mathbb{R}_+ \times {\mathbb X}.
		\end{align}
		Note that for $s < \tau_N\wedge 1$, by \eqref{ineq:g_lip} and the fact that $\sigma(t,x,0) = 0$ almost surely for all $(t,x) \in \mathbb{R}_+ \times {\mathbb X}$, we see
		\begin{align}
			|\sigma(s,y,u(s,y))| \le L |u(s,y)| \le L N h(y)^{\lambda},\quad \text{ for all } (s,y) \in [0,\tau_N\wedge 1)\times {\mathbb X}.
		\end{align}
		Therefore, by Corollary \ref{lem:m_ldp_g} applied to $(LN)^{-1}Z_N$, with $\eta=h^\lambda$, $\lambda$ replaced by $\lambda+\lambda_0/2$, $\alpha=\alpha_0$, $T=1$, and $\xi_1=\xi_2$ equal to the H\"older exponent in Lemma \ref{lem:hk_abs} \eqref{ineq:hk abs holder k weighted} (which gives its hypothesis), with $\varepsilon= (2LNN_0H)^{-1}$ (we may take $L\ge1$, so that $\varepsilon<1$), there exist $\ensuremath{C_{\ref{c:one_step_pre}}},\, \ensuremath{C_{\ref{c:one_step_rate}}}>0$ so that for all $N \ge 1$ and sufficiently large $Q \ge 1$,
		\begin{align}\label{ineq:one_step_noise_LDP}
			&{\mathbb P} \left(\sup_{(s,x) \in [0,2t/Q]\times {\mathbb X}} |Z_N(s,x)|h(x)^{-\lambda- \lambda_0/2} > (2N_0H)^{-1} \right)\\
			 \le &\ensuremath{C_{\ref{c:one_step_pre}}}S_0 \Parentheses*{LNHN_0}^2 \Parentheses*{\frac{t}{Q}}^{1-\alpha_0}\exp \left(-\ensuremath{C_{\ref{c:one_step_rate}}}\Parentheses*{LNHN_0}^{-2} \Parentheses*{\frac{Q}{t}}^{1-\alpha_0} \right).
		\end{align}

		Since $g(x) \ge \mathbf{1}_{B_r(x_0)}(x)$ for all $x \in {\mathbb X}$, we see by \eqref{ineq:ip_explicite} that for all $s \in [t/Q,2t/Q]$ and $x \in B_{r+M/Q}(x_0)$,
		\begin{align}\label{ineq:in_proof_inst_prop}
			P_s^*g(x) \ge \int_{B_r(x_0)} G_s(y,x) m(\mathrm dy) \ge \frac{1}{N_0}.
		\end{align}
		By weak comparison with the zero solution (Theorem \ref{thm:comparison} \eqref{part:main2 weak comparison}), there is a full-measure event
		\begin{align*}
			\Omega_+:=\{u(s,x)\ge0\text{ for all }(s,x)\in\mathbb{R}_+\times{\mathbb X}\}.
		\end{align*}
		On the event $\{\tau_N>2t/Q\}$, one has $u(s,x) = P^*_sg(x) +Z_N(s,x)$ for all $(s,x) \in [0,2t/Q]\times {\mathbb X}$. Hence, on the event
		$$
		\mathcal A_Q:=\left\{\sup_{(s,x) \in [0,2t/Q]\times {\mathbb X}} |Z_N(s,x)|h(x)^{-\lambda- \lambda_0/2} \le  (2N_0H)^{-1}\right\}\bigcap \left\{\tau_N>\frac{2t}{Q}\right\}\bigcap\Omega_+,
		$$
		we see for all  $x \in B_{r+M/Q}(x_0)$, it holds for all $s \in [t/Q,2t/Q]$ that
		\begin{align}\label{ineq:one_step_inclusion_relation}
			 u(s,x) \overset{\eqref{ineq:in_proof_inst_prop}}\ge \frac{1}{N_0} - \Absolute*{Z_N(s,x)} \ge \frac{1}{N_0} - \sup_{x \in B_{r+M/Q}(x_0)}\frac{h(x)^{\lambda+\lambda_0/2}}{2HN_0} \ge \frac{1}{2N_0}.
		\end{align}
		Since $u\ge0$ on $\Omega_+$ we see 
		\begin{align*}
			\mathcal A_Q \subset \left\{u(s,x) \ge  \frac{1}{2N_0} \mathbf 1 _{B_{r+M/Q}(x_0)}(x),\,\, \forall(s,x) \in \left[\frac{t}{Q},\frac{2t}{Q}\right]\times {\mathbb X} \right\}.
		\end{align*}		
		By the continuity of sample paths, we see 
		$$
    		\left\{\tau_N \le \frac{2t}{Q}\right\}\subset \left\{\sup_{(s,x) \in [0,2t/Q]\times {\mathbb X}} \Absolute*{u(s,x)}h(x)^{-\lambda } \ge N\right\}.
		$$
		Since $g(x) \le 2$ for all $x\in {\mathbb X}$, we see $P^*_sg(x) \le 2\ensuremath{C_{\ref{c:semi_group_norm}}}$ for all $s \in [0,1]$ and $x \in {\mathbb X}$. So if $N \ge 4\ensuremath{C_{\ref{c:semi_group_norm}}}$, then for large $Q>0$ so that $2t/Q\le 1$, 
		$$
			\left\{\sup_{(s,x) \in[0,2t/Q]\times {\mathbb X} }\Absolute*{u(s,x)}h(x)^{-\lambda } \ge N \right\} \subset \left\{\sup_{(s,x) \in [0,2t/Q]\times {\mathbb X}} \Absolute*{Z(s,x)}h(x)^{-\lambda } \ge N/2 \right\}.
		$$
		We see by Lemma \ref{lem:unit_scale_stochastic_part_bound} that, for $p\ge p_0(\lambda)$, with $p_0(\lambda)$ as in Lemma~\ref{lem:unit_scale_stochastic_part_bound}, there exists $\kappa = \kappa(p,\lambda) >0$, enlarged by a factor of $2$ if necessary, so that  
		\begin{align*}
			\mathbb P\left(\tau_N \le\frac{2t}{Q} \right) \le \mathbb P \left(\sup_{(s,x) \in [0,2t/Q]\times {\mathbb X}} \Absolute*{Z(s,x)}h(x)^{-\lambda} \ge \frac{N}{2}\right)\le S_0 \Parentheses*{\frac{\kappa}{N}}^p.
		\end{align*}
		Therefore, by \eqref{ineq:one_step_noise_LDP}, the preceding bound, and the fact that $\mathbb P(\Omega_+)=1$, we see 
		\begin{align*}
			\mathbb{P}\left(u(s,x) \ge  \frac{1}{2N_0} \mathbf 1 _{B_{r+M/Q}(x_0)}(x)\, \forall(s,x) \in \left[\frac{t}{Q},\frac{2t}{Q}\right]\times {\mathbb X}\right)
			&\overset{\eqref{ineq:one_step_inclusion_relation}}{\ge}\mathbb P \left( \mathcal A_Q\right)\\
			&=1- \mathbb P \left(\mathcal A_Q ^c\right)\ge 1 - \varepsilon_{N,Q,p}
		\end{align*}
		which is the desired inequality.

To prove Theorem \ref{thm:comparison} \eqref{part:main2 strong comparison}, let $u$ and $u'$ be as in Theorem~\ref{thm:comparison}~\eqref{part:main2 strong comparison}, and denote $v_t(x) : =u_t(x) - u'_t(x)$ and $f_0(x):= f(x) - f'(x)$ for $t > 0$ and $x \in {\mathbb X}$. Then $v$ solves the integral equation
		\begin{align}
			v_t(x) = P_t^*f_0(x) + &\int_0^t \int_{\mathbb X} G_{t-s}(y,x)\widetilde{b}(s,y,v_s(y)) m(\mathrm{d}y)\mathrm{d}s\\
			&+\int_0^t \int_{\mathbb X} G_{t-s}(y,x)\widetilde{\sigma}(s,y,v_s(y))W(\mathrm{d}y,\mathrm{d}s),
		\end{align}
		for $t>0$ and $x \in {\mathbb X}$, where for $r\in \mathbb{R}$,
		\begin{align}
			\widetilde{b}(t,x,r) &:= b(t,x,r +u'_t(x)) - b(t,x,u'_t(x))\\ \widetilde{\sigma}(t,x,r) &:= \sigma(t,x,r +u'_t(x)) - \sigma(t,x,u'_t(x)). \label{eq:tilde_coef_diff}
		\end{align}
		By \eqref{ineq:g_lip}, $\widetilde b$ and $\widetilde\sigma$ satisfy the same local Lipschitz condition, and $\widetilde b(t,x,0)=\widetilde\sigma(t,x,0)=0$ almost surely for all $(t,x)\in\mathbb{R}_+\times{\mathbb X}$.

		By Theorem~\ref{thm:comparison}~\eqref{part:main2 weak comparison} and the argument of \cite[pp.~427--428, equations~(4.17)--(4.22)]{MR1271224}, it is enough to consider \eqref{eq:spde_driftless} and assume that, for some $x_0\in{\mathbb X}$ and $\beta,a>0$, the initial value $f$ satisfies
		\begin{align}
			2\beta\ge f(x)\ge\beta\mathbf1_{B_a(x_0)}(x),\qquad x\in{\mathbb X}.
		\end{align}

		Let $t,M>0$ be arbitrary but fixed, and let $L>0$ be a Lipschitz constant for $\sigma$ in \eqref{ineq:g_lip} on $[0,t+1]$. Fix $\lambda\in(0,1/2]$ and any $\gamma\in(0,(1-\alpha_0)/2)$, where $\alpha_0\in(0,1)$ is as in Lemma~\ref{lem:hk_abs}, \eqref{ineq:hk abs holder k weighted}.
		By \eqref{ineq:instant_propagation}, we see there exists $N_0 = N_0(x_0,t,M,a/2,a+M) \ge 1$ so that for all sufficiently large $Q\ge 1$, 
		\begin{align*}
			\inf_{s \in [t/Q,2t/Q]} \inf_{r \in [a/2,a+M]} \inf_{x \in B_{r+M/Q}(x_0)}\int_{B_r(x_0)} G_s(y,x)m(\mathrm dy) \ge \frac{1}{N_0}.
		\end{align*}
		Let $H:=\sup_{B_{a+M}(x_0)}h(x)^{\lambda+\lambda_0/2}$ and let $p \ge 2$ be sufficiently large as in Proposition \ref{prop:one_step_estimates} and  assume in addition that $p > 1/\gamma$. Define
		\begin{align*}
			\varepsilon_{Q}: =\ensuremath{C_{\ref{c:one_step_pre}}}S_0 \Parentheses*{LQ^\gamma HN_0}^2 \Parentheses*{\frac{t}{Q}}^{1-\alpha_0}\exp \left(-\ensuremath{C_{\ref{c:one_step_rate}}}\Parentheses*{LQ^\gamma HN_0}^{-2} \Parentheses*{\frac{Q}{t}}^{1-\alpha_0} \right) + S_0 \Parentheses*{\frac{\kappa}{Q^\gamma}}^p.
		\end{align*}
		We note that 
		\begin{align}\label{ineq:strict_pos_Qepsilon_to_0}
			\lim_{Q \to \infty}Q \varepsilon_Q = 0. 
		\end{align}
		Indeed, since $\gamma < \frac{1-\alpha_0}{2}$ and $p > 1/\gamma$, we see for some $C>0$, it holds uniformly in $Q\ge 1$ that 
		\begin{align*}
			Q \varepsilon_Q \lesssim Q^{\alpha_0+2\gamma} \exp \left(-C Q^{1-\alpha_0 - 2\gamma}\right) +Q^{-p\gamma +1}
		\end{align*}
		which converges to $0$ as $Q \to \infty$, which verifies \eqref{ineq:strict_pos_Qepsilon_to_0}.

		For $Q\in \mathbb{N}$ sufficiently large, set $s_j=jt/Q$ for $j=0,\dots,Q+1$, and, for $j=0,\dots,Q$, set
		\begin{align*}
			\zeta_j:=\frac{jM}{2Q^2},\qquad B_j:=B_{a+\frac{jM}{Q}-\zeta_j}(x_0),\qquad \theta_j:=\beta(2N_0)^{-j}.
		\end{align*}
		For $k=1,\dots,Q$, set $B_k':=B_{a+\frac{(k-1)M}{Q}-\zeta_k}(x_0)$ and define
		\begin{gather}\label{def:strict_pos_set_A_J_def}
			\mathcal A_k:=\Braces*{u(s,x)\ge\theta_k\mathbf 1_{B_k}(x)\ \forall(s,x)\in\Brackets*{s_k,s_{k+1}}\times{\mathbb X}},\\
			J_j:=\Braces*{u(s_j,\cdot)\ge\theta_j\mathbf 1_{B_j}(\cdot)},\qquad j=0,\dots,Q.
		\end{gather}
		Since $\theta_0=\beta$, $B_0=B_a(x_0)$, and $f\ge\beta\mathbf 1_{B_a(x_0)}$, we have $J_0=\Omega$.

		For each sufficiently large $Q\in \mathbb{N}$ and $k = 1,\dots, Q$, let $\varphi_{k-1} :{\mathbb X} \to [0,1]$ be a continuous function so that $\varphi_{k-1}\equiv 1$ on the closure of $B_k'$ and $\varphi_{k-1}\equiv 0$ outside of $B_{k-1}$. 

		Define for $k = 1,\dots, Q$ that $\sigma_{k}(s,x,r):=\theta_{k-1}^{-1}\sigma(s_{k-1}+s,x,\theta_{k-1}r)$ for $r \in \mathbb{R}$, which is predictable with respect to the filtration $(\mathcal F_{s_{k-1}+s})_{s \ge 0}$ and satisfies \eqref{ineq:g_lip} on $[0,1]$ with the same Lipschitz constant $L>0$ (since $s_{k-1}+1\le t+1$) and $\sigma_k(t,x,0) = 0$ almost surely for all $(t,x) \in \mathbb{R}_+\times {\mathbb X}$.

		Therefore, by Theorem \ref{thm:main2}, there exists a unique continuous $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued solution to the integral equation with the shifted noise,
		\begin{align*}
			w_k(t,x) = P^*_t\varphi_{k-1}(x)+ \int_0^t \int_{\mathbb X} G_{t-s}(y,x)\sigma_{k}(s,y,w_k(s,y))W\Parentheses*{s_{k-1}+\mathrm ds, \mathrm dy}.
		\end{align*}
		Denote 
		\begin{align*}
			\mathcal B_k:=\left\{w_k(s,x) \ge \frac{1}{2N_0}\mathbf 1_{B_k}(x),\, \forall (s,x) \in \left[\frac{t}{Q},\frac{2t}{Q} \right]\times {\mathbb X}\right\}.
		\end{align*}
		For all large $Q$, the radius of $B_k'$ lies in $[a/2,a+M-M/Q]$ and the radius of $B_k'$ plus $M/Q$ is exactly the radius of $B_k$. Hence Proposition \ref{prop:one_step_estimates}, applied with $r$ equal to the radius of $B_k'$ and $N=Q^\gamma$, gives
		\begin{align}\label{ineq:strict_pos_one_step_estimates}
			\mathbb P \left(\mathcal B_k\right) \ge 1 - \varepsilon_{Q}.
		\end{align}
		We claim that 
		\begin{align}\label{ineq:strict_pos_main_step_claim}
			\mathcal A_{k}^c \cap J_{k-1} \subset \mathcal B_k^c\quad \text{and hence }\mathbb{P}\left( \mathcal A_{k}^c \cap J_{k-1} \right) \le \varepsilon_Q.
		\end{align}
		Now define $v_k(t,x):= \theta_{k-1}w_k(t,x)$ for $(t,x) \in \mathbb R_+\times {\mathbb X}$. Then $v_k$ is the solution to the following shifted integral equation:
		\begin{align*}
			v_k(t,x)= P^*_t\Parentheses*{\theta_{k-1}\varphi_{k-1}}(x) + \int_0^t \int_{\mathbb X} G_{t-s}(y,x)\sigma(s_{k-1}+s,y,v_k(s,y))W\Parentheses*{s_{k-1}+\mathrm ds, \mathrm dy}.
		\end{align*}
		Therefore, on the event $\mathcal B_k$, we have 
		\begin{align*}
			v_k(s,x) \ge \theta_{k-1} (2N_0)^{-1}\mathbf{1}_{B_k}(x) = \theta_{k}\mathbf{1}_{B_k}(x),\qquad \text{ for all }(s,x)\in \left[\frac{t}{Q},\frac{2t}{Q} \right]\times {\mathbb X}.
		\end{align*}

		Now we set $\widetilde{\varphi}_{k}:= \mathbf{1}_{J_{k-1}} \theta_{k-1}\varphi_{k-1}$, then $\widetilde{\varphi}_{k}$ is $\mathcal F_{s_{k-1}}$ measurable since $J_{k-1}\in \mathcal F_{s_{k-1}}$ and it belongs to $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$. We see 
		\begin{align*}
			\mathbf{1}_{J_{k-1}}v_k(t,x) &= P_t^*\widetilde{\varphi}_k(x)+ \int_0^t \int_{\mathbb X} G_{t-s}(y,x)\mathbf{1}_{J_{k -1}}\sigma(s_{k-1}+s, y, v_k(s,y))W\Parentheses*{s_{k-1}+\mathrm ds, \mathrm dy}\\
			&=P_t^*\widetilde{\varphi}_{k}(x) + \int_0^t\int_{\mathbb X} G_{t-s}(y,x)\sigma(s_{k-1}+s,y,\mathbf{1}_{J_{k-1}}v_k(s,y))W\Parentheses*{s_{k-1}+\mathrm ds, \mathrm dy},
		\end{align*}
		where we used the fact that $\sigma(t,x,0) = 0$ in the last line. In other words, $\mathbf{1}_{J_{k-1}}v_k$ is a solution to the shifted equation with initial condition $\widetilde{\varphi}_k$.  

		By Corollary \ref{cor:MfT}, \eqref{ineq:bcc D pair explicit}, and \eqref{ineq:hk_m long time}, Lemma \ref{thm:stochastic_fubini} applies. Thus, splitting the mild equation at $s_{k-1}$ and using the semigroup property, we obtain, for $s\ge0$,
		\begin{align*}
			u(s_{k-1}+s,x)
			&=P_{s_{k-1}+s}^*f(x)+\int_0^{s_{k-1}}\int_{\mathbb X} G_{s_{k-1}+s-r}(y,x)\sigma(r,y,u_r(y))W(\mathrm dr,\mathrm dy)\\
			&\quad+\int_{s_{k-1}}^{s_{k-1}+s}\int_{\mathbb X} G_{s_{k-1}+s-r}(y,x)\sigma(r,y,u_r(y))W(\mathrm dr,\mathrm dy)\\
			&=P_s^*\big(u(s_{k-1},\cdot)\big)(x)+\int_0^s\int_{\mathbb X} G_{s-r}(y,x)\sigma(s_{k-1}+r,y,u_{s_{k-1}+r}(y))W\Parentheses*{s_{k-1}+\mathrm dr,\mathrm dy}.
		\end{align*}
		Thus $(u(s_{k-1}+s,\cdot))_{s\ge0}$ solves the same shifted equation with initial condition $u(s_{k-1},\cdot)\in\mathcal C^{\mathrm{tem},+}_{{\mathbb X},h}$ almost surely. It holds for all $x \in {\mathbb X}$ that 
		\begin{align*}
			u(s_{k-1},x) \ge \mathbf{1}_{J_{k-1}} u(s_{k-1},x) \ge  \mathbf{1}_{J_{k-1}}\theta_{k-1} \mathbf{1}_{B_{k-1}}(x) \ge \widetilde{\varphi}_k(x),
		\end{align*}
		where we used the fact that $\widetilde \varphi_{k}$ is supported on $B_{k-1}$. 
		        Set $\mathcal G_s:=\mathcal F_{s_{k-1}+s}$ for $s\ge0$. The shifted noise is a (generalized) Wiener process relative to $(\mathcal G_s)_{s\ge0}$, and the shifted coefficient satisfies the same assumptions. The same contraction, nonnegativity, and truncation arguments extend Theorem~\ref{thm:main2} and Theorem~\ref{thm:comparison}~\eqref{part:main2 weak comparison} to $\mathcal G_0$-measurable $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$-valued initial conditions $g$ satisfying
		\begin{equation}\label{ineq:random_initial_moment}
			\sup_{x\in{\mathbb X}}h(x)^{-\lambda}\Norm*{g(x)}_{L^p_\Omega}<\infty,
			\qquad \lambda\in(0,1],\quad p\ge2,
		\end{equation}
		with the initial ordering understood in the almost sure sense. The bound \eqref{ineq:random_initial_moment} holds for $u(s_{k-1},\cdot)$ by Corollary~\ref{cor:moment}, and for $\widetilde\varphi_k$ since $0\le\widetilde\varphi_k\le\theta_{k-1}$.

        		Therefore, by the comparison principle (Theorem \ref{thm:comparison} \eqref{part:main2 weak comparison}), we see
		\begin{align*}
			u(s_{k-1}+s,x) \ge \mathbf{1}_{J_{k-1}}v_k(s,x),\qquad \forall (s,x) \in\mathbb{R}_+\times {\mathbb X}. 
		\end{align*}
		This implies, on $J_{k-1}$, we have $\mathcal A^c_k \subset \mathcal B_k^c$, combined with \eqref{ineq:strict_pos_one_step_estimates}, we see \eqref{ineq:strict_pos_main_step_claim} holds. 

		Observe that for sufficiently large $Q\in \mathbb{N}$, 
		\begin{align}\label{ineq:strict_pos_last_inclusion}
			\cap_{k = 1}^Q\mathcal A_k \subset \left\{ u_s(x)>0\ \text{on }\Brackets*{\tfrac t2,t}\times B_{a+\tfrac M4}(x_0)\right\}.
		\end{align}
		Indeed, on $\cap_{k = 1}^Q\mathcal A_k$, for each $s \in [t/2,t]$, there is some $Q/2 -1\le k < Q$ so that $s \in [s_{k},s_{k+1}]$, and hence for sufficiently large $Q \in \mathbb{N}$,
		\begin{align*}
			B_{a+ \frac{M}{4}}(x_0) \subset B_{a+ \frac{kM}{Q} - \frac{kM}{2Q^2}}(x_0) \subset B_k,\qquad \frac{Q}{2}-1 \le k <Q. 
		\end{align*}
		Then $\mathcal A_k$ gives $u(s,x) \ge\theta_k>0$ on $B_k$, which implies \eqref{ineq:strict_pos_last_inclusion}.

		Since $J_0=\Omega$ and, for $k\ge2$, $\mathcal A_{k-1} \subset J_{k-1}$ and $\bigcap_{j<k}\mathcal A_j \subset \mathcal A_{k-1}$, we see for all sufficiently large $Q \in \mathbb{N}$,
		\begin{align*}
			1-{\mathbb P}\Parentheses*{\bigcap_{k=1}^Q\mathcal A_k}
			\ =\ {\mathbb P}\Parentheses*{\bigcup_{k=1}^{Q}\mathcal A_k^c}
			\ &=\ \sum_{k=1}^{Q}{\mathbb P}\Parentheses*{\mathcal A_k^c\cap\bigcap_{j<k}\mathcal A_j}\\
			\ &\le\ \sum_{k=1}^{Q}{\mathbb P}\Parentheses*{\mathcal A_k^c\cap J_{k-1}}
			\ \overset{\eqref{ineq:strict_pos_main_step_claim}}{\le }\ \sum_{k=1}^{Q}{\mathbb P}\Parentheses*{\mathcal B_k^c}
			\ \le\ Q\,\varepsilon_Q.
		\end{align*}
		whence
		\[
			{\mathbb P}\Parentheses*{u_s(x)>0\ \text{on }\Brackets*{\tfrac t2,t}\times B_{a+\tfrac M4}(x_0)}\ \overset{\eqref{ineq:strict_pos_last_inclusion}}{\ge}\ \limsup_{Q \uparrow \infty} {\mathbb P}\Parentheses*{\bigcap_{k=1}^Q\mathcal A_k}\ \ge\ 1-\lim_{Q \uparrow \infty}Q\,\varepsilon_Q \overset{\eqref{ineq:strict_pos_Qepsilon_to_0}}{=} 1.
		\]
		Apply this with $t_n=2^n$, $n\in\mathbb Z$, and $M_m=m$, $m\in\mathbb N$, and intersect the resulting countable family of probability-one events. Since the union of the intervals $[2^{n-1},2^n]$ covers $(0,\infty)$ for $n \in \mathbb{Z}$ and the balls $B_{a+m/4}(x_0)$ exhaust ${\mathbb X}$ for $m \in \mathbb{N}$, we obtain
		\begin{align*}
			{\mathbb P}\Parentheses*{u(t,x)>0\ \text{for all }(t,x) \in (0,\infty) \times {\mathbb X} } = 1.
		\end{align*}
		This proves Theorem \ref{thm:comparison} \eqref{part:main2 strong comparison}.

		Finally, Theorem \ref{thm:comparison} \eqref{part:main2 strictly positivity} follows by applying \eqref{part:main2 strong comparison} to the solutions with initial conditions $f$ and $0$, since the latter is non-negative by Proposition \ref{prop:non-negative2} under \eqref{cond:pos_zero}.

\label{prop:sub_g_condition_noise}
		Let $V,\Psi$, and $({\mathbb X},d,m, \mathcal E, \mathcal F)$ and the function $h$ on ${\mathbb X}$ be as in Proposition \ref{prop:sub_g_cond_no_noise}.  Suppose $\alpha_0 \in (0,1)$. 
		Then the following holds:  
		\begin{enumerate}
			\item \label{it_prop_subg_noise:1} If $\Parentheses*{V\Parentheses*{\Psi^{-1}(t)}}^{-1} \lesssim t^{-\alpha_0}$ uniformly in $t \in (0,1]$, then the second inequality in \eqref{cond:exp_hk_lamda} and \eqref{cond:hk_uni_bound} hold with $\alpha$ being replaced by $\alpha_0$ and the underlying measure $K$ in the definition of $\mathcal H_K$ being replaced by $K_0$.
			\item \label{it_prop_subg_noise:2} If $\gamma\neq 0$ and it holds uniformly in $t \in (0,1]$ that 
			\begin{align*}
				\int_0^\infty \frac{s^\gamma}{V\Parentheses*{\Psi^{-1}(t+s)}} \frac{\mathrm ds}{s} \lesssim t^{-\alpha_0},
			\end{align*}
			then the second inequality in \eqref{cond:exp_hk_lamda} and \eqref{cond:hk_uni_bound} hold with $\alpha$ being replaced by $\alpha_0$, and the underlying measure $K$ in the definition of $\mathcal H_K$ being replaced by $K_\gamma$. 
		\end{enumerate}

\label{lem_CM:doubling_function_polynomial_bound}
		Suppose $V:\mathbb{R}_+\to \mathbb{R}_+$ is a doubling function as in \eqref{ineq:doubling_function}. Then there exists a constant $D>1$ such that
		\begin{align*}
			\frac{V(R)}{V(r)} \le D \Parentheses*{\frac{R}{r}}^{\log_2(D)},\qquad \text{ for }0<r\le R.
		\end{align*}

Let $0<r\le R$, choose $n \in \mathbb{N}\cup\{0\}$ so that $2^{n-1} < \frac{R}{r}\le 2^n$, then by \eqref{ineq:doubling_function}, there exists $D>1$ so that 
		\begin{align*}
			V(R) \le V(2^n r) \le D^n V(r).
		\end{align*}
		Since $D^n = 2^{n \log_2(D)}$, we get for $0<r\le R$, 
		\begin{align*}
			\frac{V(R)}{V(r)} \le D^n \le D\Parentheses*{\frac{R}{r}}^{\log_2(D)}.
		\end{align*}

\label{lem_CM:escape_polynomial_bound}
		Let $V,\Psi$ be as in Remark \ref{rem:sub-g-general}. Then there exists $\beta\ge 1$ so that 
		\begin{align*}
			\frac{V(R)}{V(r)} \lesssim \Parentheses*{\frac{R}{r}}^\beta,\qquad \text{ uniformly in }0<r\le R.
		\end{align*}
		In addition, for any $T>0$, it holds uniformly in $t \in (0,T]$ that 
		\begin{align*}
			\sqrt{t} \lesssim \Psi^{-1}(t) \lesssim t^{\frac{1}{\beta+1}}.
		\end{align*}

By \eqref{ineq:sub_g_escape_vol_constrain} and Lemma \ref{lem_CM:doubling_function_polynomial_bound}, we see there exist $C,C'>1$ and $\beta>0$ so that 
		\begin{align*}
			C^{-1} \Parentheses*{\frac{R}{r}}^2 \le \frac{\Psi(R)}{\Psi(r)} \le C'\frac{RV(R)}{rV(r)} \le C\Parentheses*{\frac{R}{r}}^{\beta+1},\qquad \text{for }0<r\le R. 
		\end{align*}
		This implies $\beta \ge 1$. It also implies that for $0<t\le T$, 
		\begin{align*}
			C^{-1} \Parentheses*{\frac{T}{t}}^{\frac{1}{\beta+1}} \le \frac{\Psi^{-1}(T)}{\Psi^{-1}(t)} \le C \Parentheses*{\frac{T}{t}}^{1/2}.
		\end{align*}
		We may now fix any $T>0$ and multiply this inequality by $\Psi^{-1}(t)$ to see the desired result.

For \eqref{it_prop_subg_no_noise:1}, it is known that when a metric measure space $({\mathbb X},d,m)$ has volume growth profile $V$ for a doubling function $V$, then by \eqref{ineq_CM:volume_all_scales} a stronger version of \eqref{ineq:entropy bound} holds (cf. \cite[pp.~167--168]{kaenmaki2017measures}): there exists $b >0$ so that
		\begin{align}\label{ineq_CM:entropy_grwoth_sub_g_case}
			D_r\Parentheses*{B_R(x)} \lesssim \Parentheses*{\frac{r}{R}}^{-b},\qquad \text{uniformly in }x \in {\mathbb X}, \, 0<r<R.
		\end{align}
		It can be easily checked that condition \eqref{ineq:ref_regular} holds for exponential functions.
		For \eqref{ineq:faster_than_ms}, we see from \eqref{ineq_CM:entropy_grwoth_sub_g_case} by setting $r = 1$ that for each $N \in \mathbb{N}$, the ball $B_N(x_0)$, hence $A_N:= B_{N}(x_0) \backslash B_{N-1}(x_0)$, can be covered by $\lfloor CN^b\rfloor$ unit balls, where $C\ge1$ does not depend on $N$, denote their centers as $\{x^N_i\}_{i = 1}^{\lfloor CN^b\rfloor}$.
		Now define $I_N:=\{x_i^N: A_N \cap B_1(x_i^N) \neq \emptyset\}$.
		Clearly,
		\begin{align*}
			A_N \subset\bigcup_{x_i \in I_N}B_1(x_i),\qquad \Absolute*{I_N} \lesssim N^b \text{ uniformly in }N.
		\end{align*}
		Let $I = \cup_{N =1}^\infty I_N$, then 
		\begin{align*}
			{\mathbb X} = \bigcup_{N \in \mathbb{N}}A_N \subset \bigcup_{N \in \mathbb{N}}\bigcup_{x_i \in I_N}B_1(x_i) = \bigcup_{x_i \in I} B_1(x_i).
		\end{align*}
		Now consider 
		\begin{align*}
			\sum_{x_i \in I} \exp \Parentheses*{-d(x_0,x_i)} = \sum_{N = 1}^\infty \sum_{x_i \in I_N} \exp \Parentheses*{-d(x_0,x_i)}\lesssim\sum_{N = 1}^\infty e^{-(N-2)}N^b < \infty,
		\end{align*}
		which gives \eqref{ineq:faster_than_ms}. 

		For \eqref{it_prop_subg_no_noise:2}, we see from \cite[Lemma 4.8 \& Theorem 3.1]{barlow2012equivalence}, there exist $c_1,c_2>0$ so that for each $k \in \mathbb{N}$, 
		\begin{align}\label{ineq_CM:sub_g_exponential_moment_bound}
			\int_{\mathbb X} \exp \left(c_1 \frac{d(x,y)}{\Psi^{-1}(t/k)} \right)G_t(x,y) m(\mathrm dy) \le c_2^k,\qquad\text{ for all }x \in {\mathbb X},\, t>0. 
		\end{align}
		Note that for each $\lambda >0$, we may select a sufficiently large $k_\lambda  \ge 1$ so that $\frac{c_1}{\Psi^{-1}(t/k_\lambda)} \ge \lambda$ for all $t \in (0,1]$. Hence, consider for $t \in (0,1]$ that 
		\begin{align*}
			e^{-\lambda d(x_0,x)}\int_{\mathbb X} e^{\lambda d(x_0,y)}G_t(x,y) m(\mathrm dy)&\le \int_{\mathbb X} e^{\lambda d(x,y)}G_t(x,y)m(\mathrm dy)\\
			&\le \int_{\mathbb X} \exp \left(c_1 \frac{d(x,y)}{\Psi^{-1}(t/k_\lambda)} \right) G_t(x,y) m(\mathrm dy)\\
			&\le c_2^{k_\lambda},
		\end{align*}
		which implies the first inequality of \eqref{cond:exp_hk_lamda}. 

		It remains to show \eqref{cond:ctem continuous}, that is, for any $f \in \mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$, 
		\begin{align}\label{ineq_CM:ctemp_continuous_subg}
			\lim_{t \downarrow 0}\Norm*{P_tf - f}_{(\lambda)}	 = 0,\qquad \text{ for all } \lambda > 0. 
		\end{align}
		Let us denote $r(x):=d(x_0,x)$ for $x \in {\mathbb X}$, then $e^{-\lambda r(x)} f(x) \in \mathcal C^0_{\mathbb X}$ for any $\lambda >0$, hence uniformly continuous on ${\mathbb X}$. Next, we note that by \eqref{ineq_CM:volume_all_scales} and \cite[Theorem 3.2]{lierl2015scale}, we have $\int_{\mathbb X} G_t(x,y)m(\mathrm dy) = 1$ for all $x \in {\mathbb X} $ and $t>0$.

		Let $\lambda >0$ be arbitrary but fixed,  denote $g(x):= e^{-\lambda r(x)/2}f(x)$ and consider
		\begin{align*}
			P_tf(x) - f(x)&=\int_{\mathbb X} G_t(x,y) \Parentheses*{g(y)e^{\lambda r(y)/2} - g(x)e^{\lambda r(x)/2}}m(\mathrm dy)\\
			&=\int_{\mathbb X} G_t(x,y) \Parentheses*{\bigl(g(y)-g(x)\bigr)e^{\lambda r(y)/2}
				+
				g(x)\Parentheses*{e^{\lambda r(y)/2}-e^{\lambda r(x)/2}}}m(\mathrm dy).
		\end{align*}
		Hence 
		\begin{align*}
			e^{-\lambda r(x)}\Absolute*{P_tf(x) - f(x)} \le A_t(x)+B_t(x)
		\end{align*}
		where 
		\begin{align*}
			A_t(x) &:= \int_{\mathbb X} G_t(x,y)e^{-\lambda r(x)}\Absolute*{g(y) - g(x)}e^{\lambda r(y)/2}m(\mathrm dy)\\
			B_t(x) &:= \int_{\mathbb X} G_t(x,y) e^{-\lambda r(x)}\Absolute*{g(x)}\, \Absolute*{e^{\lambda r(y) / 2} - e^{\lambda r(x) /2}} m(\mathrm dy).
		\end{align*}
		We will consider $B_t(x)$ first by noting 
		\begin{align*}
			e^{-\lambda r(x)}\Absolute*{e^{\lambda r(y)/2} - e^{\lambda r(x)/2}} = e^{-\lambda r(x)/2}\Absolute*{e^{\lambda (r(y) - r(x))/2} -1} \le e^{-\lambda r(x)/2}\Absolute*{e^{\lambda d(x,y)/2}-1}
		\end{align*}
		Therefore, 
		\begin{align*}
			B_t(x) &\le \Absolute*{g(x)}e^{-\lambda r(x)/2}\int_{\mathbb X} G_t(x,y) \Parentheses*{e^{\lambda d(x,y)/2}-1}m(\mathrm dy)\\
			&\mathrel{\le} \Norm*{g}_{L^\infty_{\mathbb X}}\int_{\mathbb X} G_t(x,y) \Parentheses*{e^{\lambda d(x,y)/2}-1}m(\mathrm dy)
		\end{align*}
		Let $c_1 > 0$ be as in \eqref{ineq_CM:sub_g_exponential_moment_bound} and denote $\eta_t:= c_1/ \Psi^{-1}(t)$.
		Let $\varepsilon >0$ be arbitrary but fixed, then choose $\delta >0$ so that $e^{\lambda \delta/2} - 1 < \varepsilon $.
		Consider
		\begin{align*}
			\int_{\mathbb X} G_t(x,y) \Parentheses*{e^{\lambda d(x,y) /2} -1}m(\mathrm dy)  &= \Parentheses*{\int_{d(x,y) \mathrel{<} \delta} + \int_{d(x,y) \ge \delta}} G_t(x,y) \Parentheses*{e^{\lambda d(x,y) /2} -1}m(\mathrm dy)\\
			&:=I_1(t,x) +I_2(t,x). 
		\end{align*}
		Note that $I_1(t,x) < \varepsilon $ for all $t>0$ and $x \in {\mathbb X}$.
		Now, let $t_0>0$ be sufficiently small so that $\eta_t > \lambda$ for $0< t< t_0$.
		Hence for $d(x,y) \mathrel{\ge} \delta$ and $0<t<t_0$, we have
		\begin{align*}
			e^{\lambda d(x,y)/2} = e^{-(\eta_t -\lambda/2)\delta}e^{(\eta_t - \lambda/2) \delta}e^{\lambda d(x,y)/2} \mathrel{\le} e^{-(\eta_t - \lambda/2)\delta}e^{\eta_t d(x,y)}.
		\end{align*}
		Therefore, for all $0<t<t_0$ 
		\begin{align*}
			\sup_{x \in {\mathbb X}}I_2(t,x) &\le e^{-(\eta_t - \lambda/2)\delta} \sup_{x\in {\mathbb X}} \int_{\mathbb X} G_t(x,y) e^{\eta_t d(x,y)} m(\mathrm dy)\\
			&\overset{\eqref{ineq_CM:sub_g_exponential_moment_bound}}{\le} e^{-(\eta_t-\lambda/2)\delta}c_2.
		\end{align*}
		Hence 
		\begin{align*}
			\mathop{\limsup}\limits_{t \downarrow 0} \sup_{x \in {\mathbb X}}B_t(x) \le \Norm*{g}_{L^\infty_{\mathbb X}}\mathop{\limsup}\limits_{t \downarrow 0} \sup_{x\in {\mathbb X}} \Parentheses*{I_1(t,x) +I_2(t,x)} \le \Norm*{g}_{L^\infty_{\mathbb X}}\varepsilon,
		\end{align*}
		since $\varepsilon >0$ can be arbitrarily small, we see the limit is zero.

		For ${A}_t(x)$, for any $\varepsilon > 0$,  we can choose sufficiently small $\delta \mathrel{\in} (0,1]$ so that $\Absolute*{g(x) - g(y)} < \varepsilon$ if $d(x,y) < \delta$. Hence, 
		\begin{align*}
			A_t(x) &\le \Parentheses*{\int_{d(x,y) < \delta} +\int_{d(x,y) \ge \delta}}G_t(x,y) \Absolute*{g(y)-g(x)}e^{-\lambda r(x) +\lambda r(y)}{m(\mathrm dy)}\\
			&\le \Parentheses*{\int_{d(x,y) < \delta} +\int_{d(x,y) \ge \delta}}G_t(x,y) \Absolute*{g(y)-g(x)}e^{\lambda d(x,y)}m(\mathrm dy)\\
			&:= I_3(t,x)+I_4(t,x).
		\end{align*}
		Note that $I_3(t,x) \le e^{\lambda}\varepsilon$ for all $t>0,\, x \in {\mathbb X}$. In addition, since $\sup_{x \in {\mathbb X}} \Absolute*{g(x)} < \infty$, it follows from the same argument as in $I_2$ that 
		\begin{align*}
			\lim_{t \downarrow 0} \sup_{x \in {\mathbb X}} I_4(t,x) = 0. 
		\end{align*}
		Hence, $\mathop{\limsup}_{t \downarrow 0} \sup_{x\in {\mathbb X}} A_t(x) \mathrel{\le} e^{\lambda}\varepsilon$, and since $\varepsilon>0$ can be arbitrarily small, we see the limit is zero. Finally, collecting all terms, we see \eqref{ineq_CM:ctemp_continuous_subg} holds.  

		For \eqref{it_prop_subg_no_noise:3}, we let $L^{\infty,c}_{\mathbb X}$ denote the collection of $L^\infty_{\mathbb X}$ functions with compact essential support. Note by \cite[Theorem 3.1 \& Corollary  4.2 \& Corollary 4.5]{barlow2012equivalence} (also see \cite[p. 1122]{barlow2012equivalence}), there exist $\alpha, \delta \in (0,1)$ and $C>0$ so that for any $(t,x) \in (0,\infty)\times {\mathbb X}$, $0< R< \Psi^{-1}(t)$,  $f \in L^{\infty,c}_{\mathbb X}$, the function $u(s,y):= P_{s}f(y)$ for $s>0$ and $y \in {\mathbb X}$ satisfies
		\begin{align}\label{ineq_CM:osc_inequality}
			\Absolute*{u(s_1,y_1) - u(s_2,y_2)} \le C \Parentheses*{\frac{\Psi^{-1}\Parentheses*{\Absolute*{s_1-s_2}} +d(y_1,y_2)}{R}}^\alpha \sup_{(s,y) \in D((t,x), R)} \mathopen{\lvert}u(s,y)\mathclose{\rvert}
		\end{align}
		for all $(s_1,y_1),(s_2,y_2) \in D((t,x),\delta R)$, where $D((t,x),r):= (t-\Psi(r), t]\times B_r(x)$ for $t\in \mathbb{R}$, $x \in {\mathbb X}$ and $r>0$.

		Recall $\delta, \alpha \in (0,1)$ in \eqref{ineq_CM:osc_inequality}, we note by \cite[p.1126 Proof of Lemma 4.6]{barlow2012equivalence}, it holds uniformly in $t>0$, $x',x'' \in {\mathbb X}$ with $d(x',x'') \le \delta \Psi^{-1}(t/2)$ and $f \in L^{\infty,c}_{\mathbb X}$,
		\begin{align*}
			\Absolute*{\int_{\mathbb X} \Parentheses*{G_t(x',y) - G_t(x'',y)} f(y)m(\mathrm dy)} \lesssim \Parentheses*{\frac{d(x',x'')}{\Psi^{-1}(t/2)}}^\alpha \Norm*{f}_{L^\infty_{\mathbb X}}.
		\end{align*}
		On the other hand, if $\Norm*{f}_{L^\infty_{\mathbb X}} \le 1$, then by conservativeness, the left hand side is bounded above by $2$. Hence, 
		\begin{align*}
			\Norm*{G_t(x',\cdot) - G_t(x'',\cdot)}_{L^1_{\mathbb X}}&= \sup_{f \in L^{\infty,c}_{\mathbb X}\atop \Norm*{f}_{L^\infty_{\mathbb X}} \le 1 }\Absolute*{\int_{\mathbb X} \Parentheses*{G_t(x',y) - G_t(x'',y)} f(y)m(\mathrm dy)}\\
			&\lesssim \min\left\{1,\Parentheses*{\frac{d(x',x'')}{\Psi^{-1}(t/2)}}^\alpha  \right\}.
		\end{align*}
		Now let $x \in {\mathbb X}$ be arbitrary and let $0<t< t'< \infty$. Suppose first that 
		$$
		t'-t < \Psi(\delta \Psi^{-1}(t/2)),
		$$
		then $(t,x),(t',x) \in D\Parentheses*{(t^{\prime},x),\delta \Psi^{-1}(t/2)}$. By \eqref{ineq_CM:osc_inequality}, we see it holds uniformly in   $f \in L^{\infty,c}_{\mathbb X}$ with $\Norm*{f}_{L^\infty_{\mathbb X}} \le 1$, $0<t'-t<\Psi(\delta\Psi^{-1}(t/2))$ and $x \in {\mathbb X}$ that
		\begin{align*}
			\Absolute*{P_tf(x) - P_{t'}f(x)}\lesssim\Parentheses*{\frac{\Psi^{-1}\Parentheses*{\Absolute*{t-t'}}}{\Psi^{-1}(t/2)}}^\alpha.
		\end{align*}
		If instead $t'-t\ge  \Psi\Parentheses*{\delta \Psi^{-1}(t/2)}$, by monotonicity of $\Psi^{-1}$, 
		\begin{align*}
			\Psi^{-1}\Parentheses*{t'-t} \ge \delta \Psi^{-1}(t/2),
		\end{align*}
		which implies 
		\begin{align*}
			\delta^\alpha\le \Parentheses*{\frac{\Psi^{-1}(t'-t)}{\Psi^{-1}(t/2)} }^\alpha.
		\end{align*}
		Hence, for any $f \in L^{\infty,c}_{\mathbb X}$ with $\Norm*{f}_{L^\infty_{\mathbb X}} \le 1$, $x \in {\mathbb X}$ and $\Psi\Parentheses*{\delta \Psi^{-1}(t/2)}\le t'-t$,
		\begin{align*}
			\Absolute*{P_tf(x) - P_{t'}f(x)} \le 2\mathrel{\le}2\delta^{-\alpha} \Parentheses*{\frac{\Psi^{-1}(t'-t)}{\Psi^{-1}(t/2)} }^\alpha.
		\end{align*}
		Therefore, it holds uniformly in $0<t< t'< \infty$ and $x \in {\mathbb X}$ that 
		\begin{align*}
			\Norm*{G_t(x,\cdot) - G_{t'}(x,\cdot)}_{L^1_{\mathbb X}} &= \sup_{f \in L^{\infty,c}_{\mathbb X}\atop \Norm*{f}_{L^\infty_{\mathbb X}} \le 1}\Absolute*{P_tf(x) -P_{t'}f(x)}\\
			&\lesssim \min\left\{ 1, \Parentheses*{\frac{\Psi^{-1}(t'-t)}{\Psi^{-1}(t/2)} }^\alpha\right\}.
		\end{align*}
		Finally, we see \eqref{it_prop_subg_no_noise:3} holds by Lemma \ref{lem_CM:escape_polynomial_bound} and the fact that $\alpha \in (0,1]$.

\label{lem_CM:subg_space_time_scaling}
		There exists $a>0$ so that for each $\lambda>0$, 
		\begin{align*}
			\exp \Parentheses*{\lambda \frac{d(x,y)}{\Psi^{-1}(t)}}G_t(x,y) \lesssim G_{at}(x,y),
		\end{align*}
		uniformly in $t>0$, $x,y \in {\mathbb X}$. Furthermore, it holds uniformly in $t>0,x,y \in {\mathbb X}$ that
		\begin{align*}
			d(x,y)^\lambda G_{t}(x,y) \lesssim \Psi^{-1}(t)^\lambda G_{at}\left( x,y\right).
		\end{align*}

Let $b_U,b_L,c_U,c_L>0$ be as in $\mathrm{HKE}_{\rm full}(\Psi)$, and we may assume without loss of generality that $b_U\le b_L$, $c_U \le c_L$ and $b_U,c_U \le 1$. Observe by Lemma \ref{lem_CM:escape_polynomial_bound}, for each $\theta >0$, 
		\begin{align*}
			\Psi(\theta r) \asymp \Psi(r),\qquad \text{ uniformly in }r >0. 
		\end{align*}

		Let $r_\lambda(t):= \frac{b_Uc_U}{2\lambda}\Psi^{-1}(t)$ and $K_\lambda(t) := \frac{c_U}{2 \Psi\Parentheses*{r_\lambda(t)}}$, then for $r>0$, 
		\begin{align*}
			\frac{c_U}{2}t\Psi^*\Parentheses*{b_U \frac{r}{t}} \ge \frac{c_Ub_U r}{2r_\lambda(t)} - \frac{c_U t}{2\Psi(r_\lambda(t))}= \frac{\lambda r}{\Psi^{-1}(t)} - K_\lambda(t) t,
		\end{align*}
		In other words, 
		\begin{align*}
			\frac{\lambda r}{\Psi^{-1}(t)} - c_U t\Psi^*\Parentheses*{b_U \frac{r}{t}} \le K_\lambda(t) t - \frac{c_U}{2} t\Psi^*\Parentheses*{b_U \frac{r}{t}}.
		\end{align*}
		However, $K_\lambda(t) \asymp \frac{1}{t}$, hence by \eqref{ineq_CM:volume_all_scales} it holds uniformly in $t>0,x,y \in {\mathbb X}$ that
		\begin{align*}
			\exp \left(\lambda \frac{d(x,y)}{\Psi^{-1}(t)} \right)G_t(x,y) \lesssim \frac{1}{V(\Psi^{-1}(t)\wedge \text{diam}({\mathbb X}))} \exp \Parentheses*{-\frac{c_U}{2} t\Psi^*\Parentheses*{b_U \frac{d(x,y)}{t}} }.
		\end{align*}
		By Lemma \ref{lem_CM:escape_polynomial_bound}, for any $\theta\ge 1$, there exist $\beta \ge 1$ and $C>0$ so that $\Psi(\theta r) \le C \theta^{\beta + 1}\Psi(r)$ for all $r>0$.  Hence, we may choose an appropriate $a>0$ so that for all $t,r>0$, 
		\begin{align*}
			c_L (at)\Psi^*\Parentheses*{b_L  \frac{r}{at}} &= \sup_{s>0} \frac{c_Lb_L r}{s}- \frac{c_Lat}{\Psi(s)}\\
			&= \sup_{s>0} \frac{c_Ub_U r}{s} - \frac{c_L at}{\Psi\Parentheses*{s \frac{c_Lb_L}{c_Ub_U}}}\\
			&\le \sup_{s>0} \frac{c_Ub_Ur}{s} - \frac{c_La}{C \Parentheses*{\frac{c_L b_L}{c_Ub_U}}^{\beta+1}}\frac{t}{\Psi(s)}\\
			&\le \sup_{s>0} \frac{c_Ub_U r}{s} - \frac{c_U t}{\Psi(s)}\\
			&=c_Ut\Psi^*\Parentheses*{b_U \frac{r}{t}}
		\end{align*}
		Hence, by replacing $c_U$ by $c_U/2$ if needed and \eqref{ineq_CM:volume_all_scales},  it holds uniformly in $t>0, x,y \in {\mathbb X}$ that
		\begin{align*}
			\exp \left(\lambda \frac{d(x,y)}{\Psi^{-1}(t)} \right)G_t(x,y) \lesssim \frac{1}{V(\Psi^{-1}(t)\wedge \text{diam}({\mathbb X}))} \exp \Parentheses*{-c_L at\Psi^*\Parentheses*{b_L \frac{d(x,y)}{at}} } \lesssim G_{at}(x,y).
		\end{align*}
		The second inequality is obtained by noting  
		\begin{align*}
			d(x,y)^\lambda = \Psi^{-1}(t)^\lambda \Parentheses*{\frac{d(x,y)}{\Psi^{-1}(t)}}^{\lambda} \lesssim \Psi^{-1}(t)^\lambda \exp \Parentheses*{\lambda \frac{d(x,y)}{\Psi^{-1}(t)}}.
		\end{align*}

We note \eqref{cond:exp_hk_lamda} of \eqref{it_prop_subg_noise:1} is a direct consequence of the sub-Gaussian heat kernel upper bound and Proposition \ref{prop:sub_g_cond_no_noise}. For \eqref{cond:hk_uni_bound}, fix $\delta\in(0,1)$ and let $k \ge 1$ to be determined later and consider by Lemma \ref{lem_CM:subg_space_time_scaling} that 
		\begin{align*}
			\int_{\mathbb X} \mathbf 1_{d(x,y)\ge \delta} G_t(x,y)^2 m(\mathrm dy) &\lesssim  t^{-\alpha_{0}} \delta^{-k}\int_{\mathbb X} d(x,y)^k G_t(x,y) m(\mathrm dy)\\
			&\lesssim t^{-\alpha_{0}} \delta^{-k} \Psi^{-1}(t)^k.
		\end{align*}
		By Lemma \ref{lem_CM:escape_polynomial_bound}, we see there exists $k \ge 1$ so that $\Psi^{-1}(t)^k \lesssim t$ uniformly in $t \in (0,1]$, which implies the desired inequality. 

		To see \eqref{it_prop_subg_noise:2}, let us denote $r(x):= d(x_0,x)$ and let $\lambda \ge 0$ and $T\ge 1$ be fixed. It holds uniformly in $t \in (0, T]$ and $x \in {\mathbb X}$ that  
		\begin{align*}
			&e^{-2\lambda r(x)}\iint_{{\mathbb X}^2}G_t(x,y)e^{\lambda \Parentheses*{r(y)+r(z)}}G_s(y,z) G_t(x,z) m(\mathrm dz)m(\mathrm dy)\\
			\le & \quad\iint_{{\mathbb X}^2}  e^{\lambda \Parentheses*{d(x,y)+d(x,z)}} G_t(x,y)G_{s}(z,y)G_t(x,z)m(\mathrm dy)m(\mathrm dz)\\
			\overset{\text{Lem }\ref{lem_CM:subg_space_time_scaling} }{\lesssim} &\quad \iint_{{\mathbb X}^2} G_{at}(x,y)G_{at}(x,z) G_s(z,y) m(\mathrm dy)m(\mathrm dz)\\
			=& \quad G_{2at+s}(x,x).
		\end{align*}
		Since $V$ is increasing, $\frac{1}{V(r\wedge \text{diam}({\mathbb X}))}\le \frac{1}{V(r)}+\frac{1}{V(1\wedge \text{diam}({\mathbb X}))}$ for all $r>0$. Therefore, by \eqref{ineq_CM:volume_all_scales}, uniformly in $t \in (0,1]$ and $x \in {\mathbb X}$
		\begin{align*}
			e^{-2\lambda r(x)}\Norm*{G_t(x,\cdot)h(\cdot)^\lambda}_{\mathcal H_{K_{\gamma}}}^2
			&\lesssim \int_0^\infty e^{-s}s^{\gamma} G_{2at +s}(x,x) \frac{\mathrm ds}{s}\\
			&\mathrel{\lesssim} \int_0^\infty e^{-s}s^\gamma \frac{1}{V\Parentheses*{\Psi^{-1}(2at+s)\wedge \text{diam}({\mathbb X})}}\frac{\mathrm ds}{s}\\
			&\mathrel{\le} \int_0^\infty s^\gamma \frac{1}{V\Parentheses*{\Psi^{-1}(2at+s)}}\frac{\mathrm ds}{s} + \frac{\Gamma(\gamma)}{V(1\wedge \text{diam}({\mathbb X}))}\\
			&\lesssim \int_0^\infty s^{\gamma} \frac{1}{V\Parentheses*{\Psi^{-1}(t+s)}}\frac{\mathrm ds}{s} \mathbin{+} 1\\
			&\lesssim t^{-\alpha_{0}},
		\end{align*}
		which implies \eqref{cond:exp_hk_lamda} holds. Finally, we may take $k \ge 1$ sufficiently large so that $\Psi^{-1}(t/a)^{2k} \lesssim t$ uniformly in $t \in (0,1]$ and consider for each $\delta>0$ that
		\begin{align*}
			\Norm*{\mathbf 1_{B_\delta(x)^{\mathrm c}} G_{t/a}(x,\cdot)}_{\mathcal H_{K_{\gamma}}}^2&\le \delta^{-2k}\Norm*{d(x,\cdot)^kG_{t/a}(x,\cdot)}_{\mathcal H_{K_{\gamma}}}^2\\
			&\lesssim \delta^{-2k} \Psi^{-1}(t/a)^{2k} \Norm*{G_{t}(x,\cdot)}_{\mathcal H_{K_{\gamma}}}^2\\
			&\lesssim \delta^{-2k}\, t\, t^{-\alpha_0}\\
			&\lesssim \delta^{-2k}\, t^{1-\alpha_{0}}
		\end{align*}
		uniformly in $t \in (0,1]$ and $x \in {\mathbb X}$. Since $0< \alpha_{0}<1$, we see the desired result holds.

\label{prop:on_diagonal_to_instant_propagation}
		Let $\rho:{\mathbb X}\times {\mathbb X} \to \mathbb{R}_+$ be a geodesic metric on the measure space $({\mathbb X},m)$, denote $B_r^\rho(x)$ be the open ball of radius $r>0$ centered at $x \in {\mathbb X}$ under the metric $\rho$. Let $V:\mathbb{R}_+\to \mathbb{R}_+$ be a doubling function so that for some $s_0>0$, 
		\begin{align}\label{ineq:local_volume_doubling}
			V(s) \asymp m(B_s^\rho(x)),\qquad \text{uniformly in } x \in {\mathbb X}, \, s \in (0,s_0]. 
		\end{align}
		Let $\Psi:\mathbb{R}_+\to \mathbb{R}_+$ be an increasing homeomorphism for which there exists $\delta_0>0$ so that 
		\begin{align}\label{ineq:on_diagonal_lower_bound}
			G_t(y,x) \gtrsim \frac{1}{V(\Psi^{-1}(t))}, \qquad \text{ uniformly for } t \in (0,1]\text{ and } \rho(x,y) \le \delta_0 \Psi^{-1}(t),
		\end{align}
		and 
		\begin{align}\label{ineq:on_diagonal_space_time_scaling}
			\lim_{t\downarrow 0}\frac{t}{\Psi^{-1}(t)} =0.
		\end{align}
		Then condition \eqref{ineq:instant_propagation} holds under the metric $\rho$.

Let $x_0 \in {\mathbb X}$ and $0<r_0<v$ be arbitrary but fixed. By \eqref{ineq:on_diagonal_space_time_scaling}, there exists $\varepsilon_0 \in (0,1/2]$ so that for all $\varepsilon \in (0, \varepsilon_0)$, 
		\begin{align}\label{ineq:on_diagonal_to_ip_step_1}
			v \varepsilon \le \frac{\delta_0}{8} \Psi^{-1}(t),\qquad \frac{\delta_0}{8}\Psi^{-1}(t) < r_0 \wedge s_0,\qquad \text{ for all }t \in (\varepsilon, 2\varepsilon).
		\end{align}
		Let $\varepsilon \in (0,\varepsilon_0),\, t \in (\varepsilon, 2\varepsilon),\, r \in (r_0, v)$ and $x \in B_{r+\varepsilon v}^\rho(x_0)$. Set 
		\begin{align*}
			r_x:= \rho(x, B^\rho_r(x_0)):= \inf_{y \in B^\rho_r(x_0)} \rho(x,y).
		\end{align*}
		Since $\rho$ is a geodesic metric, $r_x=\max\{\rho(x,x_0)-r,0\}\leq v\varepsilon$. Let $\zeta:[0, \rho(x,x_0)]\to {\mathbb X}$ be a geodesic from $x$ to $x_0$ and set
		\begin{align*}
			\ell:= \min\{ r_x +\frac{\delta_0}{4} \Psi^{-1}(t), \rho(x,x_0)\},\qquad w := \zeta(\ell).
		\end{align*}
		We claim that
		\begin{align}\label{ineq:on_diagonal_set_inclusion}
			B^\rho_{\frac{\delta_0}{8}\Psi^{-1}(t)}(w) \subset B_r^{\rho}(x_0).
		\end{align}
		Indeed, if $\ell = r_x +\frac{\delta_0}{4}\Psi^{-1}(t)$, then $\rho(x_0,w) = \rho(x_0,x) - \rho(x,w)= \rho(x,x_0) - r_x - \frac{\delta_0}{4}\Psi^{-1}(t)$.
		Hence for all $y \in B^\rho_{\frac{\delta_0}{8}\Psi^{-1}(t)}(w)$, we see 
		\begin{align*}
			\rho(y,x_0)& \le \rho(w,y)+\rho(w,x_0) \\
			&\le \frac{\delta_0}{8}\Psi^{-1}(t) +\rho(x,x_0) - r_x - \frac{\delta_0}{4}\Psi^{-1}(t)\\
			&= \rho(x,x_0)-r_x-\frac{\delta_0}{8}\Psi^{-1}(t)\\
			&\le r - \frac{\delta_0}{8}\Psi^{-1}(t)\\
			&< r.
		\end{align*}
		If $\ell = \rho(x,x_0)$, then $w = x_0$ and \eqref{ineq:on_diagonal_set_inclusion} holds by \eqref{ineq:on_diagonal_to_ip_step_1}. This proves \eqref{ineq:on_diagonal_set_inclusion}.

		In addition, we see it holds for all $y \in B^\rho_{\frac{\delta_0}{8}\Psi^{-1}(t)}(w)$ that
		\begin{align*}
			\rho(y,x) &\le \rho(y,w) + \rho(w,x) \\
			&\le \frac{\delta_0}{8}\Psi^{-1}(t) + r_x +\frac{\delta_0}{4}\Psi^{-1}(t)\\
			& \le  \frac{3\delta_0}{8}\Psi^{-1}(t) + r_x \\
			&\le  \frac{3\delta_0}{8}\Psi^{-1}(t) +v\varepsilon\\
			&\overset{\eqref{ineq:on_diagonal_to_ip_step_1}}{\le} \frac{\delta_0}{2}\Psi^{-1}(t)\\
			&< \delta_0 \Psi^{-1}(t).
		\end{align*}
		Therefore,
		\begin{align*}
			\int_{B^\rho_r(x_0)} G_t(y,x) m(\mathrm dy) &\overset{\eqref{ineq:on_diagonal_set_inclusion}}{\ge} \int_{B^\rho_{\frac{\delta_0}{8}\Psi^{-1}(t)}(w)} G_t(y,x) m(\mathrm dy)\\
			&\overset{\eqref{ineq:on_diagonal_lower_bound}{,\,\eqref{ineq:local_volume_doubling}}}{\gtrsim} \frac{V(\frac{\delta_0}{8}\Psi^{-1}(t))}{V(\Psi^{-1}(t))}\\
			&\overset{\eqref{ineq:doubling_function}}{\gtrsim} 1,
		\end{align*}
		note that the implicit constant depends only on the doubling property of $V$ and the constant in \eqref{ineq:on_diagonal_lower_bound}, which gives the desired inequality.

By \cite[Theorem 2.11]{murugan2020length} and \cite[Proposition A.1]{kajino2020singularity}, there exists a geodesic metric $\rho$ on ${\mathbb X}$ so that 
		\begin{align*}
			\rho(x,y) \asymp d(x,y),\qquad \text{uniformly in }x,y \in {\mathbb X}. 
		\end{align*}
		Note that $\mathrm{HKE}_{\rm full}(\Psi)$ holds with $d(x,y)$ replaced by $\rho(x,y)$ for $x,y \in {\mathbb X}$. 

		By Lemma \ref{lem_CM:escape_polynomial_bound}, we see \eqref{ineq:on_diagonal_space_time_scaling} holds and the desired inequality is a direct consequence of Lemma \ref{prop:on_diagonal_to_instant_propagation}.

\label{lem:manifold_gaussian_consequences}
 Assume \eqref{eq:manifold_gaussian}. The heat kernel is conservative:
 \begin{align}
  \int_M G_t(x,y)\,m(\mathrm dy)=1,
  \qquad t>0,\quad x\in M.
  \label{eq:manifold_conservation}
 \end{align}
  Moreover, the following estimates hold.
 \begin{enumerate}
  \item There are constants $c,C,\kappa>0$, independent of the centers and radii, such that
 \begin{align}
  c r^n\leq m(B_r(x))\leq C r^n,
  \qquad x\in M,\quad 0<r\leq1.
  \label{eq:manifold_local_volume}
 \end{align}
  At all radii,
 \begin{align}
  m(B_R(x))\leq C R^n e^{\kappa R},\qquad x\in M,\quad R>0.
  \label{eq:manifold_volume_growth}
 \end{align}
  \item For every $q\geq0$,
 \begin{align}
  \sup_{x\in M,\,0<t\leq1}
  \int_M G_t(x,y)e^{q d(x,y)}\,m(\mathrm dy)<\infty.
  \label{eq:manifold_exp_moment}
 \end{align}
  \item There are constants $\eta\in(0,1)$ and $C>0$ such that, uniformly for $x,x'\in M$ and $t,t'\in(0,1]$,
 \begin{align}
  \|G_t(x,\cdot)-G_t(x',\cdot)\|_{L^1_M}
  &\leq C\frac{d(x,x')^\eta}{t^{\eta/2}},\nonumber\\
  \|G_t(x,\cdot)-G_{t'}(x,\cdot)\|_{L^1_M}
  &\leq C\frac{|t-t'|^{\eta/2}}{(t\wedge t')^{\eta/2}}.
  \label{eq:manifold_holder}
 \end{align}
 \end{enumerate}

The volume-to-covering argument in \cite[pp.~167--168]{kaenmaki2017measures}, applied at bounded scales using \eqref{eq:manifold_local_volume}--\eqref{eq:manifold_volume_growth}, gives $D_\varepsilon(B_R(x))\leq C_R\varepsilon^{-n}$ uniformly in $x\in M$ and $0<\varepsilon\leq1$, for each $R\geq1$. This proves \eqref{ineq:entropy bound}.

 By the $5r$-covering lemma \cite[Theorem~1.2, p.~2]{heinonen2001lectures} and separability, there is an at most countable family $(x_j)_{j\in\mathcal I}$ such that $M=\bigcup_{j\in\mathcal I}B_1(x_j)$ and the balls $B_{1/10}(x_j)$ are pairwise disjoint. Recall $\kappa>0$ in \eqref{eq:manifold_volume_growth} and fix $\lambda_0>\kappa$. By \eqref{eq:manifold_local_volume}, the triangle inequality and disjointness, followed by Tonelli's theorem, there exists $C_{\lambda_0}>0$ such that
 \begin{align*}
  \sum_{j\in\mathcal I}h(x_j)^{-\lambda_0}
  \leq C_{\lambda_0}\int_M e^{-\lambda_0d(o,y)}\,m(\mathrm dy)
  =C_{\lambda_0}\lambda_0\int_0^\infty e^{-\lambda_0r}m(B_r(o))\,\mathrm dr\overset{\eqref{eq:manifold_volume_growth}}{<}\infty,
 \end{align*}
this proves \eqref{ineq:faster_than_ms} for every $\lambda\geq\lambda_0$. Condition \eqref{ineq:ref_regular} follows from $h(y)\leq e^{d(x,y)}h(x)$.

 The Gaussian upper bound in \eqref{eq:manifold_gaussian} and the semigroup property yield $P_t\mathcal C_M^0\subset\mathcal C_M^0$ for all $t>0$. The Feller property then follows from \cite[Example~4.2, p.~10]{benamor2023essential}. Moreover, \eqref{eq:manifold_exp_moment} gives  the $L^1$ inequality in \eqref{cond:exp_hk_lamda}.

 Fix $\lambda>0$ and $f\in\mathcal C^{\mathrm{tem}}_{M,h}$. By Lemma~\ref{lem:C_temp_density_0} (whose proof does not depend on this  subsection), choose $f_j\in\mathcal C_M^0$ with $\|f-f_j\|_{(\lambda)}\to0$. Then for each $\lambda>0$, there exists $C_\lambda >0$ so that 
 \[
  \limsup_{t\downarrow0}\|P_t f-f\|_{(\lambda)}
  \leq C_\lambda\|f-f_j\|_{(\lambda)}
       +\limsup_{t\downarrow0}\|P_t f_j-f_j\|_\infty =C_\lambda\|f-f_j\|_{(\lambda)}
 \]
 which converges to $0$ as $j\to\infty$. The same approximation shows that $P_t f\in\mathcal C^{\mathrm{tem}}_{M,h}$, and the semigroup property gives continuity at every time. Since $P_t^*=P_t$, this proves \eqref{cond:ctem continuous}. Equation~\eqref{eq:manifold_holder} gives \eqref{cond:time_holder}.

 Finally, $(M,d)$ is geodesic by the Hopf--Rinow theorem \cite[Chapter~7, Theorem~2.8]{docarmo1992riemannian}. With $\rho=d$, $V(r)=r^n$ and $\Psi(r)=r^2$, \eqref{eq:manifold_local_volume} and the Gaussian lower bound verify the volume and near-diagonal hypotheses of Lemma~\ref{prop:on_diagonal_to_instant_propagation}. Since $t/\Psi^{-1}(t)=\sqrt t\to0$, that lemma gives \eqref{ineq:instant_propagation}.

\label{lem:manifold_covariance}
 Assume \eqref{eq:manifold_gaussian} and \eqref{eq:manifold_gamma}. The measure $K$ in \eqref{eq:manifold_covariance} is symmetric, non-negative definite and Radon. Moreover, $L^2_M\subset\mathcal H_K$ and
 \begin{align}
  0\leq\|v\|_{\mathcal H_K}^2\leq\|v\|_{L^2_M}^2,
  \qquad v\in L^2_M.
  \label{eq:manifold_noise_contraction}
 \end{align}
 For every $\alpha$ with $\max\{0,n/2-\gamma\}<\alpha<1$, the $\mathcal H_K$ inequality in \eqref{cond:exp_hk_lamda} and condition~\eqref{cond:hk_uni_bound} hold.

\label{lem:ref_grow}
		Let $({\mathbb X},d)$ be a metric space with infinite diameter and let $h$ be a  weight function on it satisfying \eqref{ineq:faster_than_ms} and \eqref{ineq:ref_regular}. Then for each $x_0 \in {\mathbb X}$,
		\begin{align}\label{cond:ref_grow}
			\lim_{R \to \infty} \inf_{x \in B_R(x_0)^c} h(x) = \infty.
		\end{align}

Suppose, to the contrary, that \eqref{cond:ref_grow} fails. Then for some $x_0\in{\mathbb X}$ and $M\geq1$, there are points $y_k\in{\mathbb X}$ such that $d(x_0,y_k)\to\infty$ and $h(y_k)\leq M$. Let $\lambda_0>0$ and $(x_n)_{n\in\mathcal I}$ be as in \eqref{ineq:faster_than_ms}. For each $k$, choose $n_k$ so that $y_k\in B_1(x_{n_k})$. Since $d(x_0,x_{n_k})\geq d(x_0,y_k)-1\to\infty$ as $k \to \infty$, after passing to a subsequence we may assume that the indices $n_k$ are distinct. By \eqref{ineq:ref_regular}, there is some $C\geq1$ such that $h(x_{n_k})\leq Ch(y_k)\leq CM$. Consequently,
		\begin{align*}
			\sum_{n\in\mathcal I}h(x_n)^{-\lambda_0}
			\geq\sum_{k\in\mathbb{N}}h(x_{n_k})^{-\lambda_0}
			\geq\sum_{k\in\mathbb{N}}(CM)^{-\lambda_0}=\infty,
		\end{align*}
		contradicting \eqref{ineq:faster_than_ms}.

If ${\mathbb X}$ has finite diameter, then \eqref{ineq:entropy bound} and completeness imply that ${\mathbb X}$ is compact, so the assertion is immediate. Suppose that ${\mathbb X}$ has infinite diameter. Fix $x_0\in{\mathbb X}$ and let $(\mathcal X_n)_{n\in\mathbb{N}}$ be the compactly supported cutoff functions used in the proof of Lemma \ref{lem:PS}, chosen so that $0\leq\mathcal X_n\leq1$ with $\mathcal X_n=1$ on $B_n(x_0)$ and $\mathcal X_n =0$ on $B_{n+1}(x_0)^c$. For $f\in\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$, set $f_n:=f\mathcal X_n\in\mathcal C^0_{\mathbb X}$. Then for every $\lambda>0$, 
		\begin{align*}
			\lim_{n \to \infty}\Norm*{f-f_n}_{(\lambda)}
			&\leq \lim_{n \to \infty}\Norm*{f}_{(\lambda/2)}
			\sup_{x\in B_n(x_0)^\mathrm c}h(x)^{-\lambda/2}=0,
		\end{align*}
		by Lemma \ref{lem:ref_grow}. Hence $f_n\to f$ in $\mathcal C^{\mathrm{tem}}_{{\mathbb X},h}$.

Fix $g\in\mathcal H_K$.
		By the self-adjointness of $Q^{1/2}$, for every $f\in\widetilde{\mathcal H}_K$,
		\[
			(\Gamma_g\circ Q^{1/2})(f)
			=\left\langle[g]_K,Q^{1/2}f\right\rangle_{\widetilde{\mathcal H}_K}
			=\left\langle Q^{1/2}[g]_K,f\right\rangle_{\widetilde{\mathcal H}_K}.
		\]
		Thus $\Gamma_g\circ Q^{1/2}$ is a Hilbert--Schmidt  operator on $\widetilde{\mathcal H}_K$, whose norm is $\|Q^{1/2}[g]_K\|_{\widetilde{\mathcal H}_K}$ by Parseval's identity.
		For every $f\in\operatorname{Ker}(Q^{1/2})^\bot$, the definitions of $Q^{-1/2}$ and the induced norm give
		\[
			\|Q^{1/2}f\|_{Q^{1/2}\widetilde{\mathcal H}_K}
			=\|Q^{-1/2}Q^{1/2}f\|_{\widetilde{\mathcal H}_K}
			=\|f\|_{\widetilde{\mathcal H}_K};
		\]
		see \cite[Appendix~B.2, p.~429]{da2014stochastic}.
		Thus $Q^{1/2}$ restricts to an isometric isomorphism from $\operatorname{Ker}(Q^{1/2})^\bot$ onto $Q^{1/2}\widetilde{\mathcal H}_K$.
		Since $\Gamma_g\circ Q^{1/2}$ vanishes on $\operatorname{Ker}(Q^{1/2})$, the Hilbert--Schmidt norm identity in \cite[p.~96 and Section~4.2.1]{da2014stochastic} applies.
		Consequently, $\Gamma_g$ is Hilbert--Schmidt and
		\begin{align*}
			\|\Gamma_g\|^2_{\mathcal L^{\mathrm{HS}}_{Q^{1/2}\widetilde{\mathcal H}_K}}
			=\|\Gamma_g\circ Q^{1/2}\|^2_{\mathcal L^{\mathrm{HS}}_{\widetilde{\mathcal H}_K}}
			=\left\|Q^{1/2}[g]_K\right\|^2_{\widetilde{\mathcal H}_K}
			\leq\|Q^{1/2}\|^2\|g\|^2_{\mathcal H_K}.
		\end{align*}

\label{lem:Min_H}
		Suppose that $(\Psi(z,x): z\in E, x\in {\mathbb X})$ is a non-negative measurable function on the product space $(E\times {\mathbb X}, \mathscr E\otimes \mathscr B_{\mathbb X}, \nu\otimes m)$ where $(E, \mathscr E, \nu)$ is a $\sigma$-finite measure space.
		Set
		\begin{align*}
			F(x):=\int_{E}\Psi(z,x)\nu(\mathrm dz),\qquad x\in{\mathbb X},
		\end{align*}
		and suppose that $F\in\mathcal B_{\mathbb X}$, $\Psi(z,\cdot)\in\mathcal H_K$ for $\nu$-almost every $z\in E$, and
		\begin{align*}
			\int_{E}\Norm*{\Psi(z,\cdot)}_{\mathcal H_K}\nu(\mathrm dz)<\infty.
		\end{align*}
		Then $F\in\mathcal H_K$ and
		\begin{equation}
			\Norm*{\int_{E} \Psi(z, \cdot)\nu(\mathrm dz)}_{\mathcal H_K}
			\leq \int_{E} \Norm*{\Psi(z, \cdot)}_{\mathcal H_K} \nu(\mathrm dz).
		\end{equation}

By Lemma \ref{lem:HS} and the boundedness of $Q$ on $\tilde{\mathcal H}_{K}$, we see by the  Burkholder-Davis-Gundy inequality (cf. \cite[Theorem 4.37]{da2014stochastic}) that, uniformly in $T >0$, 
		\begin{equation}\label{ineq:bdg_gen_mtg_bdg}
			\begin{aligned}
				\Norm*{\sup_{t \in [0,T]}\left|\iint_0^t \Phi(s,y)W(\mathrm ds,\mathrm dy)\right|}_{L^p_\Omega} &\lesssim \Parentheses*{\int_0^T \mathbb E\left[\langle Q[\Phi(s,\cdot)]_K,[\Phi(s,\cdot)]_K\rangle_{\tilde{\mathcal H}_{K}}^\frac{p}{2}\right]^\frac{2}{p}\mathrm ds}^\frac{1}{2}\\
				&\lesssim \Parentheses*{\int_0^T \mathbb E\left[\langle \Phi(s,\cdot),\Phi(s,\cdot)\rangle_{\mathcal H_K}^\frac{p}{2}\right]^\frac{2}{p}\mathrm ds}^\frac{1}{2}.
			\end{aligned}
		\end{equation}
		For each $s \ge 0$, we see by Minkowski's and the Cauchy-Schwarz inequalities  that
		\begin{align}
			\mathbb E\left[\langle \Phi(s,\cdot),\Phi(s,\cdot)\rangle_{\mathcal H_K}^\frac{p}{2}\right]^\frac{2}{p}&=  \Norm*{\iint_{{\mathbb X}^2}\Phi(s,x) \Phi(s,y)K\Parentheses*{\mathrm dy,\mathrm dx}}_{L^\frac{p}{2}_\Omega}\\
			&\le \iint_{{\mathbb X}^2} \Norm*{\Phi(s,x)\Phi(s,y)}_{L^\frac{p}{2}_\Omega} K\Parentheses*{\mathrm dy,\mathrm dx}\\
			&= \iint_{{\mathbb X}^2}\mathbb E \left[\Absolute*{\Phi(s,x)}^\frac{p}{2}\Absolute*{\Phi(s,y)}^\frac{p}{2} \right]^\frac{2}{p}K(\mathrm dy,\mathrm dx)\\
			&\le \iint_{{\mathbb X}^2} \Norm*{\Phi(s,x)}_{L^p_\Omega} \Norm*{\Phi(s,y)}_{L^p_\Omega} K(\mathrm dy,\mathrm dx)\\
			&=\Norm*{\Norm*{\Phi(s,\cdot)}_{L^p_\Omega}}_{\mathcal H_K}^2.
		\end{align}
		Inserting this into \eqref{ineq:bdg_gen_mtg_bdg}, we see the following inequality holds uniformly in $T>0$,
		\begin{align}
			\Norm*{\sup_{t \in [0,T]}\left|\iint_0^t \Phi(s,y)W(\mathrm ds,\mathrm dy)\right|}_{L^p_\Omega}\lesssim \Parentheses*{\int_0^T \Norm*{\Norm*{\Phi(s,\cdot)}_{L^p_\Omega}}_{\mathcal H_K}^2\mathrm ds}^\frac{1}{2} = \Norm*{\Phi}_{L^2_{[0,T]}\mathcal H_K L^p_\Omega},
		\end{align}
		which is the desired result.

Suppose that \eqref{cond:exp_hk_lamda} holds for the given $\lambda$ with $\alpha$ replaced by $\tilde\alpha$, and let $t>0$.
		Then $t = n+a$ for some $n \in \mathbb{N}\cup\{0\}$ and $a \in [0,1]$.
		Hence, there is $C>1$ such that for all $x \in {\mathbb X}$ and $a \in [0,1]$, we have
		\begin{align}
			\left(P_a^* h^\lambda\right)(x) \le  C h(x)^\lambda.
		\end{align}
		Therefore, by the semigroup property, we see 
		\begin{equation}\label{ineq:weighted semigroup bound long time temporary}
			\begin{aligned}
				\left(P_t^* h^\lambda\right)(x) &= \left(\left(P_{1}^* \right)^n P_a^* h^\lambda\right) (x)\\
				&\le C^{n+1}h(x)^\lambda\\
				&\le b e^{\kappa t}h(x)^\lambda
			\end{aligned}
		\end{equation}
		where $b = \sup_{a \in [0,1]} C^{1-a}$, and $\kappa = \ln(\max\{1,C\})>0$, which proves \eqref{ineq:hk_m long time}.

		By Lemma \ref{lem:H0} and the assumed bound with exponent $\tilde\alpha$, the following inequality holds uniformly in $\delta \in (0,1]$ and $y_1,y_2 \in {\mathbb X}$,
		\begin{align}\label{ineq:weighted cs temporary}
			\left \langle G_\delta(\cdot,y_1) h^\lambda,G_\delta(\cdot,y_2) h^\lambda \right \rangle_{ \mathcal H_K } &\le \|G_\delta(\cdot, y_1)h^\lambda\|_{\mathcal H_K}\|G_\delta(\cdot, y_2)h^\lambda\|_{\mathcal H_K}\\
			&\lesssim\delta^{-\tilde\alpha} h(y_1)^{\lambda} h(y_2)^{\lambda}.
		\end{align}
		For any $t >1$, fix $\delta \in [1/2,1]$. Then by the semigroup property and Fubini's theorem, we see that 
		\begin{align}
			\left\|G_t(\cdot,x) h(\cdot)^\lambda\right\|_{ \mathcal H_K}^2 & = \iint_{{\mathbb X}^2}G_t(z_1,x) h(z_1)^\lambda G_t(z_2,x) h(z_2)^\lambda K(\mathrm dz_1,\mathrm dz_2)\\
			&= \iint_{{\mathbb X}^2} \Parentheses*{\int_{{\mathbb X}} G_\delta(z_1,y_1)G_{t-\delta}(y_1,x) m(\mathrm dy_1)} h(z_1)^\lambda  \\
			&\qquad  \qquad\qquad \times \Parentheses*{\int_{\mathbb X}  G_{\delta}(z_2,y_2) G_{t-\delta}(y_2,x) m(\mathrm dy_2)} h(z_2)^\lambda K(\mathrm dz_1,\mathrm dz_2) \\
			&= \int_{\mathbb X} \int_{\mathbb X} G_{t - \delta}(y_1,x)G_{t-\delta}(y_2,x)\\
			&\quad \quad \quad  \times \iint_{{\mathbb X}^2} G_\delta(z_1,y_1) h(z_1)^\lambda G_\delta(z_2,y_2) h(z_2)^\lambda K(\mathrm dz_1,\mathrm dz_2) m(\mathrm d y_1) m(\mathrm dy_2)\\
			&=\int_{\mathbb X} \int_{\mathbb X} G_{t-\delta}(y_1,x) G_{t-\delta}(y_2,x)\left \langle G_\delta(\cdot,y_1)h^\lambda, G_{\delta}(\cdot,y_2) h^\lambda\right\rangle _{\mathcal H_K} m(\mathrm dy_1) m(\mathrm dy_2)\\
			&\overset{\eqref{ineq:weighted cs temporary}}{\lesssim} \delta^{-\tilde\alpha}\Parentheses*{P^*_{t-\delta}\Parentheses*{h^\lambda}(x)}^2\\
			&\overset{\eqref{ineq:weighted semigroup bound long time temporary}}{\lesssim} \delta^{-\tilde\alpha}b^2e^{-2\kappa \delta}e^{2\kappa t}h(x)^{2\lambda}\\
			&\lesssim t^{-\tilde\alpha}e^{\tilde\kappa t}h(x)^{2\lambda},
		\end{align}
		where $\tilde\kappa:=2\kappa+1$ and we used $\delta\ge1/2$ and $t^{\tilde\alpha}\le e^t$ for $t>1$.
		Together with the assumed bound for $t\in(0,1]$, this proves \eqref{ineq:hk_k long time}.

		To show \eqref{ineq:time_holder_long_time}, we first note that for each $T>0$, it holds uniformly for $T\ge t' \ge t>0$ with $t'-t \le \frac{1}{2}$ and $x \in {\mathbb X}$ that 
		\begin{align}\label{ineq:time_holder_proof_half}
			\Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x)}_{L^1_{\mathbb X}} \lesssim \frac{\Absolute*{t-t'}^{\xi_1}}{t^\beta}.
		\end{align}
		To see this, consider the case where $0 < t \le \frac{1}{2}$, then $t' \le 1$ and the estimate is exactly \eqref{cond:time_holder}. Now suppose $t > \frac{1}{2}$ then by the semi-group property, we see uniformly in $T \ge t' >t \ge \frac{1}{2}$ and $x \in {\mathbb X}$, 
		\begin{align}
			&\Norm*{\int_{\mathbb X} G_{t - \frac{1}{2}}(\cdot, y)\Parentheses*{G_{\frac{1}{2}}(y,x) - G_{t'-t+ \frac{1}{2}}(y,x)  } m(\mathrm dy)    }_{L^1_{\mathbb X}}\\
			\le & \int_{\mathbb X} \Norm*{G_{t - \frac{1}{2}}(\cdot,y)}_{L^1_{\mathbb X}} \Absolute*{G_{\frac{1}{2}}(y,x) - G_{t'-t+ \frac{1}{2}}(y,x) } m(\mathrm dy) \\
			\overset{\eqref{ineq:hk_m long time} }\lesssim & \int_{\mathbb X} \Absolute*{G_{\frac{1}{2}}(y,x) - G_{t'-t+ \frac{1}{2}}(y,x) } m(\mathrm dy)\\
			\overset{\eqref{cond:time_holder} }\lesssim& \frac{\Absolute*{t-t'}^{\xi_1}}{(1/2)^\beta } \lesssim \frac{\Absolute*{t-t'}^{\xi_1}}{t^\beta },
		\end{align}
		where we used the fact that $t'-t+\frac{1}{2} \in (0,1]$.
		This proves \eqref{ineq:time_holder_proof_half}.
		Suppose $0< t< t' \le T$, and $\Absolute*{t-t'} \ge \frac{1}{2}$.
		Let $n_1  \le n_N\in \mathbb{N}$ be
		\begin{align}
			n_1 := \min\left\{n \in \mathbb{N}: t \le \frac{n}{2}\right\},\qquad n_N:= \max\left\{n \in \mathbb{N}: \frac{n}{2} \le t' \right\},
		\end{align} 		
		Then by \eqref{ineq:time_holder_proof_half}, it holds uniformly in $x \in {\mathbb X}$ that 
		\begin{equation}\label{ineq:time_holder_end_case}
			\begin{aligned}
				\Norm*{G_t(\cdot,x) - G_{\frac{n_1}{2}}(\cdot,x)}_{L^1_{\mathbb X}} &\lesssim \frac{\Absolute*{t - \frac{n_1}{2}}^{\xi_1\wedge 1}}{t^\beta}\\
				\Norm*{G_{t'}(\cdot,x) - G_{\frac{n_N}{2}}(\cdot,x)}_{L^1_{\mathbb X}} &\lesssim \frac{\Absolute*{t' - \frac{n_N}{2}}^{\xi_1\wedge 1}}{(n_N/2)^\beta}.
			\end{aligned}
		\end{equation}
		By the triangle inequality,
		\begin{align}
			\Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x)}_{L^1_{\mathbb X}}
			&\le \Norm*{G_t(\cdot,x) - G_{\frac{n_1}{2}}(\cdot,x)}_{L^1_{\mathbb X}}
			+\Norm*{G_{t'}(\cdot,x) - G_{\frac{n_N}{2}}(\cdot,x)}_{L^1_{\mathbb X}} \\
			&\qquad + \sum_{j=n_1+1}^{n_N}\Norm*{G_{\frac{j}{2}}(\cdot,x)-G_{\frac{j-1}{2}}(\cdot,x)}_{L^1_{\mathbb X}} \\
			&\overset{\eqref{ineq:time_holder_end_case},\,\eqref{ineq:time_holder_proof_half}}{\lesssim}
			\frac{\Absolute*{t-\frac{n_1}{2}}^{\xi_1\wedge1}}{t^\beta}
			+\frac{\Absolute*{t'-\frac{n_N}{2}}^{\xi_1\wedge1}}{(n_N/2)^\beta}
			+\sum_{j=n_1+1}^{n_N}\frac{\Parentheses*{\frac12}^{\xi_1}}{\Parentheses*{\frac{j-1}{2}}^\beta} \\
			&\lesssim \frac{\Absolute*{t-\frac{n_1}{2}}^{\xi_1\wedge1}}{t^\beta}
			+\frac{\Absolute*{t'-\frac{n_N}{2}}^{\xi_1\wedge1}}{t^\beta}
			+\frac{n_N-n_1}{t^\beta} \\
			&\le t^{-\beta}\Parentheses*{2\Absolute*{t-t'}^{\xi_1\wedge1}+2|t-t'|} \\
			&\lesssim \frac{\Absolute*{t-t'}^{\xi_1\wedge1}}{t^\beta}.
		\end{align}
		Here we used that $(j-1)/2\ge n_1/2\ge t$ in the third inequality. 
		This proves the desired result.
		To prove \eqref{ineq:spatial_holder_long_time}, fix $T>0$. For $t\in(0,1]$, the estimate is exactly \eqref{cond:time_holder}. If $1<t\le T$, then the semigroup property, \eqref{ineq:hk_m long time} with $\lambda=0$ and \eqref{cond:time_holder} at  $t=1$ give
		\begin{align}
			\Norm*{G_t(\cdot,x)-G_t(\cdot,x')}_{L^1_{\mathbb X}}
			&\le \int_{\mathbb X} \Norm*{G_{t-1}(\cdot,y)}_{L^1_{\mathbb X}}
			\Absolute*{G_1(y,x)-G_1(y,x')}m(\mathrm dy)\\
			&\lesssim d(x,x')^{\xi_2}\\
			&\lesssim \frac{d(x,x')^{\xi_2}}{t^\beta},
		\end{align}
		uniformly in $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$, and $t \in [1,T]$. This proves \eqref{ineq:spatial_holder_long_time}.

We first show \eqref{ineq:hk abs holder m} holds for $\lambda =0$.  Let $x,x' \in {\mathbb X}$  with $d(x,x') \le 1$, consider first for $t > 1$ that
		\begin{align}
			\int_0^{t} \int_{\mathbb X} \left|G_{t - s}(y,x) - G_{t - s}(y,x') \right|m(\mathrm dy)\mathrm ds & = I_1+I_2,
		\end{align}
		where 
		\begin{align}
			I_1 &{=}\int_{t-1}^t\int_{\mathbb X}\Absolute*{G_{t - s}(y,x) - G_{t-s}(y,x')}m(\mathrm dy)\mathrm ds  \\
			&{=}\int_0^1 \int_{\mathbb X} \left|G_{1-s}(y,x) - G_{1-s}(y,x') \right|m(\mathrm dy) \mathrm ds \\
			&{\overset{\eqref{cond:time_holder}}{\lesssim}} d(x,x')^{\xi_2},
		\end{align}
		uniformly in $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ and $t>1$, and 
		\begin{align}
			I_2 &= \int_0^{t - 1}\int_{\mathbb X}\left| G_{t - s}(y,x) - G_{t - s}(y,x')\right| m(\mathrm dy) \mathrm ds.
		\end{align}
		By the semigroup property and Tonelli's theorem, it holds uniformly in $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ and $t>1$ that
		\begin{align}
			I_2 
			&\,\,\,= \int_0^{t-1} \int_{\mathbb X} \left|\int_{\mathbb X} G_{t - s -1} (y,z) \left(G_{1}(z,x) - G_1(z,x') \right) m(\mathrm dz) \right| m(\mathrm dy) \mathrm ds\\
			&\,\,\,\le \int_0^{t-1}\int_{\mathbb X} \left(\int_{\mathbb X} G_{t-s-1}(y,z)m(\mathrm dy)\right)
			\left|G_1(z,x)-G_1(z,x')\right|m(\mathrm dz)\mathrm ds\\
			&\overset{\eqref{ineq:hk_m long time}}{\lesssim} \int_0^{t-1} e^{\kappa(t-s-1)}\mathrm ds
			\int_{\mathbb X} \left|G_1(z,x)-G_1(z,x')\right|m(\mathrm dz)\\
			&\overset{\eqref{cond:time_holder}}{\lesssim} d(x,x')^{\xi_2}\int_0^{t-1}e^{\kappa(t-s-1)}\mathrm ds,
		\end{align}
		where \eqref{ineq:hk_m long time} was used with $\lambda=0$.
		Note that the time integral is increasing in $t$ and bounded for each $t \ge 1$.
		For $t\in(0,1]$, the same spatial bound follows by integrating \eqref{cond:time_holder}, since $\beta<1$.
		Hence we see for each $T> 0$, it holds uniformly for $d(x,x') \le 1$ and $t \in [0,T]$ that
		\begin{align}\label{ineq:hk spatial temporary}
			\int_0^t \int_{\mathbb X} \left|G_{t - s}(y,x) - G_{t - s}(y,x') \right| m(\mathrm dy) \mathrm ds \lesssim d(x,x')^{\xi_2}.
		\end{align}

		Fix $T>0$ and consider $\delta\in(0,1]$ and $t\in[0,T]$. Then
		\begin{align}
			\int_0^{t+\delta} \int_{\mathbb X} \left| G_{t+\delta - s}(y,x) - G_{t-s}(y,x) \right| m(\mathrm dy) \mathrm ds = I_1+ I_2,
		\end{align}
		where 
		\begin{align}
			I_1 = \int_{t}^{t+\delta} \int_{\mathbb X} G_{t+\delta-s}(y,x) m(\mathrm dy) \mathrm ds\overset{\eqref{cond:exp_hk_lamda}}{\lesssim} \delta,
		\end{align}
		uniformly in $(t,x) \in [0,T] \times {\mathbb X}$ and $\delta \in (0,1]$, and 
		\begin{align}
			I_2 = \int_0^t \int_{\mathbb X} \left| G_{t+\delta-s}(y,x) - G_{t-s} (y,x)\right| m(\mathrm dy) \mathrm ds.
		\end{align}

		By the change of variables  and \eqref{ineq:time_holder_long_time}, applied with time horizon $T+1$, we see it holds uniformly in $(t,x) \in [0,T] \times {\mathbb X}$ and $\delta \in (0,1]$ that
		\begin{align}
			I_2
			=\int_0^t\Norm*{G_{r+\delta}(\cdot,x)-G_r(\cdot,x)}_{L^1_{\mathbb X}}\mathrm dr
			\lesssim \delta^{\xi_1\wedge1}\int_0^t r^{-\beta}\mathrm dr
			\lesssim \delta^{\xi_1\wedge1},
		\end{align}
		where the endpoint $r=0$ is immaterial and the last inequality follows from $\beta\in[0,1)$. Since $\delta\in(0,1]$, we also have $\delta\le\delta^{\xi_1\wedge1}$.

		Therefore, for each $T>0$,  it holds uniformly for $(t,x) \in [0,T] \times {\mathbb X}$ and $\delta \in (0,1]$  that
		\begin{align}\label{ineq:hk temporal temporary}
			\int_0^{t+\delta} \int_{\mathbb X} \left|G_{t +\delta- s}(y,x) - G_{t-s}(y,x) \right| m(\mathrm dy) \mathrm ds \lesssim \delta^{\xi_1\wedge 1}.
		\end{align}
		Therefore, we see by \eqref{ineq:hk temporal temporary}, \eqref{ineq:hk spatial temporary} and the triangular inequality that, for each $T>0$, it holds uniformly for $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$,  $t \in [0,T]$ and $\delta \in (0,1]$ that
		\begin{align}
			\int_0^{t+\delta} \int_{\mathbb X} \left|G_{t+\delta-s}(y,x') - G_{t-s}(y,x) \right|m(\mathrm dy) \mathrm ds \lesssim \delta^{\xi_1\wedge 1} + d(x,x')^{\xi_2}.
		\end{align}
		For $t,t'\in[0,T]$ with $|t-t'|>1$, \eqref{eq:GC}, the triangle inequality and \eqref{ineq:hk_m long time} with $\lambda=0$ give
		\begin{align*}
			\int_0^T\Norm*{G_{t-s}(\cdot,x)-G_{t'-s}(\cdot,x')}_{L^1_{\mathbb X}}\,\mathrm ds
			&\le \int_0^t\Norm*{G_{t-s}(\cdot,x)}_{L^1_{\mathbb X}}\,\mathrm ds
			+\int_0^{t'}\Norm*{G_{t'-s}(\cdot,x')}_{L^1_{\mathbb X}}\,\mathrm ds\\
			&\lesssim \int_0^t e^{\kappa(t-s)}\,\mathrm ds
			+\int_0^{t'}e^{\kappa(t'-s)}\,\mathrm ds\\
			&\le 2T e^{\kappa T}
			\lesssim |t-t'|^{\xi_1\wedge1}.
		\end{align*}
		The last inequality uses $|t-t'|^{\xi_1\wedge1}\ge1$.
		Thus, by the triangle inequality, uniformly for $t,t'\in[0,T]$ and $x,x'\in{\mathbb X}$ with $d(x,x')\le1$,
		\begin{align}\label{ineq:hk abs holder m lambda = 0}
			\Norm*{G(\cdot,\cdot;t,x) - G(\cdot,\cdot; t',x')}_{L^1_{[0,T)} L^1_{\mathbb X}} \lesssim  \Absolute*{t - t'}^{\xi_1\wedge 1} + d(x,x')^{\xi_2},
		\end{align}
		which implies \eqref{ineq:hk abs holder m} when $\lambda=0$. To show \eqref{ineq:hk abs holder m} for $\lambda \in [0,1/2]$, we see by H\"{o}lder's inequality that
		\begin{align}
			\Norm*{h(\cdot)^\lambda \Parentheses*{G(\cdot,\cdot;t,x) - G(\cdot,\cdot; t',x')}}_{L^1_{[0,T)} L^1_{\mathbb X}} &\lesssim \Norm*{ \Absolute*{G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')}^{1/2} h(\cdot)^\lambda }_{L^2_{[0,T]\times{\mathbb X}}}
			\\& \qquad \times \left\| \left|G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')\right|^{1/2} \right\|_{L^2_{[0,T]\times{\mathbb X}}}. \label{eq:Phi1U}
		\end{align}

		Noticing $2\lambda \in [0,1]$, uniformly for every $t,t'\in [0,T]$ and $x,x'\in {\mathbb X}$ with $d(x, x')\leq 1$,
		\begin{align}
			& \Norm*{\left|G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')\right|^{1/2}h(\cdot)^\lambda }^2_{L^2_{[0,T]\times{\mathbb X}}}
			\\& = \int_0^T \mathrm ds \int_{\mathbb X} \Absolute*{G(s,y;t,x) - G(s,y;t',x')} h(y)^{2\lambda} m(\mathrm dy)
			\\&\leq \int_0^T \left(\left\| G_{t-s}(\cdot,x) h(\cdot)^{2\lambda} \right\|_{L^1_{\mathbb X}} + \left\| G_{t'-s}(\cdot,x') h(\cdot)^{2\lambda} \right\|_{L^1_{\mathbb X}}\right) \mathrm ds 
			\\&\label{eq:Phi1Ua}
			\overset{\text{Lemma \ref{lem:hk longtime}}} \lesssim 
			h(x)^{2\lambda} + h(x')^{2\lambda}
			\overset{\eqref{ineq:ref_regular}} \lesssim 
			h(x)^{2\lambda}. 
		\end{align}
		On the other hand, uniformly for every $t,t'$ in $[0,T]$ and $x,x'\in {\mathbb X}$ with $d(x,x')\leq 1$,
		\begin{align}
			&\left\| \left|G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x')\right|^{1/2} \right\|_{L^2_{[0,T]\times{\mathbb X}}} = \left\| G(\cdot,\cdot;t,x) - G(\cdot,\cdot;t',x') \right\|^{1/2}_{L^1_{[0,T]\times{\mathbb X}}}
			\\
			& \overset{\eqref{ineq:hk abs holder m lambda = 0}} \lesssim 
			\left(|t-t'|^{\xi_1 \wedge 1} + d(x,x')^{\xi_2}\right)^{1/2} \leq |t-t'|^{(\xi_1\wedge 1)/2}+ d(x,x')^{\xi_2/2}
			\\
			\label{eq:Phi1Ub} 
			&\lesssim |t-t'|^{(\xi_1\wedge 1)\over 2}+ d(x,x')^{{\xi_2 \over 2}\wedge 1}.
		\end{align}
		Putting \eqref{eq:Phi1Ua} and \eqref{eq:Phi1Ub} back to \eqref{eq:Phi1U}, we obtain that uniformly for every $t,t'\in [0,T]$ and $x,x'\in {\mathbb X}$ with $d(x, x')\leq 1$,
		\begin{align}
			\Norm*{h(\cdot)^\lambda \Parentheses*{G(\cdot,\cdot;t,x) - G(\cdot,\cdot; t',x')}}_{L^1_{[0,T)} L^1_{\mathbb X}}
			\lesssim \left(|t-t'|^{{{\xi_1 \wedge 1}\over 2}} + d(x,x')^{{\xi_2 \over 2}\wedge 1}\right) h(x)^{\lambda},
		\end{align}
		which is exactly \eqref{ineq:hk abs holder m}.

		To prove \eqref{ineq:hk abs holder k}, recall that $\alpha\in(0,1)$ in \eqref{cond:exp_hk_lamda}, and that $\beta\in[0,1)$ and $\xi_1,\xi_2>0$ are given in \eqref{cond:time_holder}. Take $q\ge2$ large enough so that $0<\bar\alpha:=\alpha/2+\beta/q<1/2$ and $\xi_2/q<1$.
		Take $q' \geq 1$ so that $\frac{1}{q} + \frac{1}{q'} = 1$.
		Define $\tilde \xi_1:=\min(\frac{\xi_1\wedge 1}{q}, \frac{1-\alpha}{2}) \in (0,1)$ and $\tilde \xi_2 = \frac{\xi_2}{q} \in (0,1)$. Let $\lambda_1\in[0,\frac{1}{2}]\subset[0,1/q']$.
		Pay attention that \eqref{cond:exp_hk_lamda} holds with $\lambda$ being replaced by either $\lambda_1 q'$ or $\lambda_1$.

		Hence, it holds uniformly for  every $0< t \leq t'$ in $[0,T]$, and $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ that,
		\begin{align}
			&\qquad
			\Norm*{\Absolute*{G_t(\cdot,x) - G_{t'}(\cdot,x')} 
				h(\cdot)^{\lambda_1}}_{\mathcal H_K}
			\\ &\overset{\eqref{eq:G}}=\Norm*{\Absolute*{\int_{\mathbb X} G_{\frac{t}{2}}(\cdot,y)\Parentheses*{G_{\frac{t}{2}}(y, x)- G_{t'-\frac{t}{2}}(y,x')} m(\mathrm dy) }
				h(\cdot)^{\lambda_1}
			}_{\mathcal H_K}
			\\  &\leq 
			\Norm*{\Parentheses*{\int_{\mathbb X} G_{\frac{t}{2}}(\cdot,y)\Absolute*{G_{\frac{t}{2}}(y, x)- G_{t'-\frac{t}{2}}(y,x')} m(\mathrm dy)}h(\cdot)^{\lambda_1}}_{\mathcal H_K} 
			\\ &\overset{\text{Lemma \ref{lem:Min_H}}}\le \int_{\mathbb X} \Norm*{G_{\frac{t}{2}}(\cdot, y) 
				h(\cdot)^{\lambda_1}
			}_{\mathcal H_K} \Absolute*{G_{\frac{t}{2}}(y, x)- G_{t'-\frac{t}{2}}(y,x')} m(\mathrm dy)
			\\ & \overset{\text{Lemma \ref{lem:hk longtime}}}{\lesssim } t^{-\alpha/2}\int_{\mathbb X} h(y)^{\lambda_1} \Absolute*{G_{\frac{t}{2}}( y, x)- G_{t'-\frac{t}{2}}(y,x')} m(\mathrm dy). \label{ineq:continuity stochastic part middle step 1} 
		\end{align}

		Note uniformly in  $t, t'$ in $[0,T]$ and $x,x'\in {\mathbb X}$
		with $d(x,x') \le 1$ that
		\begin{align}
			&\int_{\mathbb X} h(y)^{\lambda_1}  \left|G_t(y,x) -G_{t'}(y,x') \right| m(\mathrm dy)
			\\&=\int_{\mathbb X} h(y)^{\lambda_1}  \left|G_t(y,x) -G_{t'}(y,x') \right|^\frac{1}{q'} \left|G_t(y,x) -G_{t'}(y,x') \right|^\frac{1}{q} m(\mathrm dy)
			\\&\overset{\text{H\"older}}{\leq} \Norm*{h(\cdot)^{\lambda_1} \Absolute*{G_t(\cdot,x)- G_{t'}(\cdot,x')}^{\frac{1}{q'}}}_{L^{q'}_{{\mathbb X}}} \Norm*{\Absolute*{G_t(\cdot,x)- G_{t'}(\cdot,x')}^{\frac{1}{q}}}_{L^{q}_{{\mathbb X}}}
			\\&=\Norm*{h(\cdot)^{\lambda_1 q'} \Absolute*{G_t(\cdot,x)- G_{t'}(\cdot,x')}}^{1\over q'}_{L^1_{{\mathbb X}}} \Norm*{G_t(\cdot,x)- G_{t'}(\cdot,x')}^{1\over q}_{L^1_{{\mathbb X}}}
			\\&\le \Norm*{h(\cdot)^{\lambda_1 q'} \Parentheses*{ G_t(\cdot,x)+G_{t'}(\cdot,x')}}^{1\over q'}_{L^1_{\mathbb X}} \Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x')}^{1\over q}_{L^1_{\mathbb X}}
			\\&\overset{\text{Minkowski}}\le \Parentheses*{\Norm*{h(\cdot)^{\lambda_1 q'}  G_t(\cdot,x)}_{L^1_{\mathbb X}} + \Norm*{h(\cdot)^{\lambda_1 q'} G_{t'}(\cdot,x')}_{L^1_{\mathbb X}}}^{1\over q'} \Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x')}^{1\over q}_{L^1_{\mathbb X}}
			\\&\overset{\text{Lemma \ref{lem:hk longtime}}}\lesssim  \Parentheses*{h(x)^{\lambda_1 q'} +h(x')^{\lambda_1 q'}}^{\frac{1}{q'}} \Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x')}^{1\over q}_{L^1_{\mathbb X}}
			\\&\overset{\eqref{ineq:ref_regular}}\lesssim  h(x)^{\lambda_1} \Norm*{G_t(\cdot,x) - G_{t'}(\cdot,x')}^{1\over q}_{L^1_{\mathbb X}}. \label{eq:Gtt}
		\end{align}
		Therefore, by the triangular inequality, we have uniformly for every 
		$0< t \leq t'$ in $[0,T]$, and $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ that, 

		\begin{align}
			&\Norm*{\Absolute*{G_t(\cdot,x) - G_{t'}(\cdot,x')} 
				h(\cdot)^{\lambda_1}
			}_{\mathcal H_K}
			\\ & {\overset{\eqref{ineq:continuity stochastic part middle step 1}}{\lesssim}} t^{-\alpha/2}\int_{\mathbb X} h(y)^{\lambda_1} \left|G_{\frac{t}{2}}( y, x)- G_{t'-\frac{t}{2}}(y,x') \right|m(\mathrm dy)
			\\ & {\overset{\eqref{eq:Gtt}}{\lesssim} }t^{-\alpha/2} h(x)^{\lambda_1} \Norm*{ 
				G_{\frac{t}{2}}(\cdot,x) - 
				G_{t'-\frac{t}{2}}(\cdot,x')
			}^{1\over q}_{L^1_{\mathbb X}} 
			\\& {\overset{\text{
					Minkowski
			}}{\leq}} t^{-\alpha/2} h(x)^{\lambda_1} \Parentheses*{\Norm*{ G_{\frac{t}{2}}(\cdot,x) - G_{\frac{t}{2}}(\cdot,x')}_{L^1_{\mathbb X}} + \Norm*{G_{\frac{t}{2}}(\cdot,x') - G_{t'-\frac{t}{2}}(\cdot,x') }_{L^1_{\mathbb X}} }^{1\over q}
			\\& {\overset{
			\eqref{ineq:spatial_holder_long_time},\ \eqref{ineq:time_holder_long_time}}{\lesssim}}t^{-\alpha/2} h(x)^{\lambda_1} \Parentheses*{\frac{d(x,x')^{\xi_2}}{\Parentheses*{t/2}^\beta} + \frac{\Absolute*{t'-t}^{\xi_1 \wedge 1}}{\Parentheses*{t/2}^\beta}}^{\frac{1}{q}}
			\\& \lesssim t^{-\bar\alpha} h(x)^{\lambda_1} \Parentheses*{d(x,x')^{\xi_2} + \Absolute*{t'-t}^{\xi_1 \wedge 1}}^{\frac{1}{q}}. \label{eq:G-GS}
		\end{align}
		On one hand, uniformly for $0<t\leq t'$ in $[0,T]$, and $x,x'\in{\mathbb X}$ with $d(x,x')\leq1$, since $2\bar\alpha\in(0,1)$,
		\begin{align}
			&\int_0^t \Norm*{\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} 
				h(\cdot)^{\lambda_1}
			}_{\mathcal H_K}^2\mathrm ds 
			\\& \overset{\eqref{eq:G-GS}}\lesssim \int_0^t (t-s)^{-2\bar\alpha}h(x)^{2\lambda_1}\Parentheses*{d(x,x')^{\xi_2}+\Absolute*{t'-t}^{\xi_1\wedge1}}^{\frac{2}{q}}\,\mathrm ds
			\\& \lesssim t^{1-2\bar\alpha}h(x)^{2\lambda_1}\Parentheses*{d(x,x')^{\xi_2}+\Absolute*{t'-t}^{\xi_1\wedge1}}^{\frac{2}{q}}. \label{eq:Gtq}
		\end{align}
		On the other hand, uniformly in $0<t\leq t'$ in $[0,T],$ and $x,x' \in {\mathbb X}$ with $d(x,x')\leq 1$, 
		\begin{align}
			\int_{t}^{t'} \Norm*{G_{t'-s}(\cdot,x') h(\cdot)^{\lambda_1}}_{\mathcal H_K}^2\mathrm ds 
			& \overset{\text{Lemma \ref{lem:hk longtime}}}\lesssim \int_{t}^{t'} (t'-s)^{-\alpha} h(x')^{2\lambda_1} \mathrm ds \\
			&= h(x')^{2\lambda_1} \int_0^{t'-t} r^{-\alpha} \mathrm dr \\
			&\lesssim h(x')^{2\lambda_1} |t'-t|^{1-\alpha}\\
			&\overset{\eqref{ineq:ref_regular}}{\lesssim} h(x)^{2\lambda_1} |t'-t|^{1-\alpha}. \label{eq:Gt'q}
		\end{align}
		Now, we see uniformly in $0 <t\leq t'$ in $[0,T]$, and $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ that   
		\begin{align}
			&\int_0^T \Norm*{\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} h(\cdot)^{\lambda_1}}_{\mathcal H_K}^2\mathrm ds
			\\&\overset{\eqref{eq:GC}}=\int_0^t \Norm*{\Absolute*{G_{t-s}(\cdot,x) - G_{t'-s}(\cdot,x')} h(\cdot)^{\lambda_1}}_{\mathcal H_K}^2\mathrm ds +  \int_{t}^{t'} \Norm*{G_{t'-s}(\cdot,x')h(\cdot)^{\lambda_1}}_{\mathcal H_K}^2\mathrm ds
			\\&\overset{\eqref{eq:Gtq} \& \eqref{eq:Gt'q}}\lesssim h(x)^{2\lambda_1} \Parentheses*{d(x,x')^{\xi_2} + \Absolute*{t'-t}^{\xi_1\wedge1}}^{\frac{2}{q}} + h(x)^{2\lambda_1} |t'-t|^{1-\alpha}
			\\&\lesssim h(x)^{2\lambda_1} \Parentheses*{d(x,x')^{\frac{2\xi_2}{q}}+ |t'-t|^{\frac{2\Parentheses*{\xi_1\wedge1}}{q}} + |t'-t|^{1-\alpha}}
			\\& \lesssim h(x)^{2\lambda_1} \Parentheses*{d(x,x')^{2\tilde \xi_2}+ |t'-t|^{2\tilde \xi_1}}.
		\end{align}
		This proves \eqref{ineq:hk abs holder k}.

		It remains to prove \eqref{ineq:hk abs holder k weighted}. Let us fix $T>0$. Since $q\ge2$, its conjugate exponent satisfies $q'\le2$, and hence $\lambda q'\le1$ for every $\lambda\in[0,1/2]$. Thus, by \eqref{eq:Gtq} and \eqref{eq:Gt'q}, with $\lambda_1$ replaced by $\lambda$, it holds uniformly in $0<t\leq t'$ in $[0,T]$, and $x,x' \in {\mathbb X}$ with $d(x,x') \le 1$ that
		\begin{align*}
			&\int_0^{t'}\left\|\left|G_{t-s}(\cdot,x)-G_{t'-s}(\cdot,x')\right|h(\cdot)^\lambda\right\|_{\mathcal H_K}^2\,\mathrm ds\\
			\lesssim &h(x)^{2\lambda}\left[t^{1-2\bar\alpha}\left(d(x,x')^{2\xi_2/q}+|t-t'|^{2(\xi_1\wedge1)/q}\right)+|t-t'|^{1-\alpha}\right].
		\end{align*}
		Set
		\[
			\alpha_0:=\frac{1+2\bar\alpha}{2},\qquad
			\xi:=1\wedge\frac{2\xi_2}{q}\wedge\frac{2(\xi_1\wedge1)}{q}\wedge(\alpha_0-\alpha).
		\]
		Since $t\le t'$ and $|t-t'|\le t'$, this proves \eqref{ineq:hk abs holder k weighted}; the same estimate also covers $t=0$.

\label{cor:hk_abs}
		For each $T>0$, there
		exist $\xi\in (0,1]$ and $\alpha_0\in(0,1)$ so that the following inequality holds uniformly in $t,t' \in (0,T]$ and $x,y \in {\mathbb X}$ with $d(x,y) \le 1$,
		\begin{align*}
			\Norm*{
			\Absolute*{G_t(\cdot,x) - G_{t'}(\cdot,y)}
			}_{\mathcal H_K}^2 \lesssim \frac{\Absolute*{t-t'}^\xi + d(x,y)^\xi}{\Parentheses*{t\wedge t'}^{
			\alpha_0}},
		\end{align*}

Let $T\geq1$ and let $j\leq T$ be a non-negative integer. Then, for any $\lambda>0$ and sufficiently large $p\geq1$, the following inequality holds uniformly in $x\in{\mathbb X}$:
		\begin{align}
			{\mathbb E}\left[ |X(j,x)|^p\right] &\lesssim {\mathbb E}\left[|X(0,x)|^p \right] + \sum_{k = 1}^{j} {\mathbb E}\left[\left|X(k - 1,x)- X(k,x) \right|^p \right]\\
			&\lesssim h(x)^{\lambda}.
		\end{align}
		Let $d_\mathcal S$ be the metric on $\mathbb{R}_+\times{\mathbb X}$ defined by
		\begin{align}
			d_\mathcal S((t,y),(t',y')):=|t-t'|^{\tilde \xi_1}+d(y,y')^{\tilde \xi_2},
		\end{align}
		and, for each non-negative integer $j$ and $x\in{\mathbb X}$, set $\mathcal S_{j,x}:=[j,j+1]\times B_1(x)$. Let $b>0$ be as in \eqref{ineq:entropy bound} for $R=1$ and set $\kappa:=1/\tilde \xi_1+b/\tilde \xi_2$. By Lemma \ref{lem:product metric entropy}, each $\mathcal S_{j,x}$ is totally bounded under $d_\mathcal S$ and
		\begin{align}
			D(\mathcal S_{j,x},d_\mathcal S;\varepsilon)\lesssim\varepsilon^{-\kappa}
		\end{align}
		uniformly in $j$, $x$ and $\varepsilon\in(0,1]$. Hence, using \eqref{cond:tight_moment} with time horizon $T+1$, we may apply \cite[Theorem~1.1]{kratschmer2022kolmogorov} to $\mathcal S_{j,x}$ for each $j$ and $x$.
		Patching the resulting modifications over the unit time intervals and the countable spatial cover in \eqref{ineq:faster_than_ms}, we obtain a single locally H\"older-continuous modification, which we still denote by $X$, such that, for any $\lambda>0$, sufficiently large $p\geq1$ and $\varrho\in(0,1-\kappa/p)$,
		\begin{align}\label{ineq:holder norm bound temp}
			{\mathbb E}\left[\sup_{(t,y),(t',y')\in\mathcal S_{j,x}\atop(t,y)\neq(t',y')}\frac{\Absolute*{X(t,y)-X(t',y')}^p}{\Parentheses*{\Absolute*{t-t'}^{\tilde \xi_1}+d(y,y')^{\tilde \xi_2}}^{\varrho p}}\right]\lesssim h(x)^\lambda
		\end{align}
		uniformly in $x\in{\mathbb X}$ and non-negative integers $j\leq T$.
		From now on, we work with this modification. Therefore, uniformly in $x\in{\mathbb X}$ and non-negative integers $j\leq T$,
		\begin{align}
			{\mathbb E}\left[ \sup_{y \in B_1(x)\atop s \in [j,j+1]} \left| X(s,y)\right|^p \right] & \lesssim  {\mathbb E}\left[\left|X(j,x) \right|^p \right] + {\mathbb E} \left[\sup_{y \in B_1(x)\atop s \in [j,j+1]} \left| X(s,y) - X(j,x) \right|^p \right]\nonumber\\
			&\lesssim h(x)^\lambda\label{ineq:tight_x0_bound}.
		\end{align}
		Let $\{x_i\}_{i \in \mathcal I}\subset {\mathbb X}$ and $\lambda_0 >0$ be as in condition \eqref{ineq:faster_than_ms}. By Markov's inequality we see for each $\lambda >0$, it holds uniformly in $A>0$ that
		\begin{align}
			{\mathbb P} \left(\sup_{s \le T} \|X(s)\|_{(\lambda)} > A \right)&\le   \sum_{0 \le j \le T}\sum_{i\in\mathcal I} {\mathbb P} \left( \sup_{t\in [j,j+1]\atop x \in B_1(x_i)}  \left|X(t,x) \right|^p h(x)^{-\lambda p} \ge  A^p \right)\\
			&\le  \sum_{0 \le j \le T}\sum_{i\in\mathcal I} {\mathbb P} \left( \sup_{t \in [j,j+1]\atop x \in B_1(x_i)}  \left|X(t,x) \right|^p  \ge  A^p \inf_{x \in B_1(x_i)}h(x)^{\lambda p}\right)\\
			&\overset{\eqref{ineq:tight_x0_bound}}{\lesssim} \sum_{i\in\mathcal I}\frac{1}{A^p}h(x_i)^{\lambda}  \sup_{x \in B_1(x_i)}h(x)^{-\lambda p} \\
			&\overset{\eqref{ineq:ref_regular}}{\lesssim} \frac{1}{A^p}\sum_{i\in\mathcal I} h(x_i)^{-\lambda p + \lambda}.
		\end{align}
		By \eqref{ineq:faster_than_ms}, we may choose $p$ to be large enough so that $-\lambda p+\lambda <- \lambda_0$, which makes the last sum finite. Therefore, we see by the continuity of the probability measure that
		\begin{align*}
			\mathbb P \Parentheses*{\sup_{t \in [0,T]}\Norm*{X(t)}_{(\lambda)} < \infty} = 1.
		\end{align*}
		Fix $T\geq1$, $\lambda>0$ and $x_0\in{\mathbb X}$, and work on a probability-one event on which
		\begin{align*}
			M:=\sup_{s\in[0,T]}\Norm*{X(s)}_{(\lambda/2)}<\infty.
		\end{align*}
		For $t,t'\in[0,T]$ and $R\geq1$,
		\begin{align*}
			\Norm*{X(t)-X(t')}_{(\lambda)}
			&\leq\sup_{x\in\overline{B_R(x_0)}}\Absolute*{X(t,x)-X(t',x)}
			+2M\sup_{x\in B_R(x_0)^c}h(x)^{-\lambda/2}.
		\end{align*}
		The first term converges to zero as $t' \to t$ by joint continuity and compactness of $\overline{B_R(x_0)}$. If ${\mathbb X}$ has finite diameter, the second term vanishes for all sufficiently large $R$. Otherwise, we see by Lemma \ref{lem:ref_grow} that the second term can be made arbitrarily small by choosing $R>0$ large enough. 
		Therefore, $t \mapsto X(t,\cdot)$ is continuous under $\Norm*{\cdot}_{(\lambda)}$ on $[0,T]$. Finally, we may take a countable intersection over $T\in\mathbb{N}$ and $\lambda=n^{-1}$ for $n\in\mathbb{N}$ to conclude the desired result.

Suppose that both $(B,\Sigma)$ and $(B',\Sigma')$ are Duhamel-integrable pairs and that $B'$ is a predictable modification of $B$.
			Then, for each $y\in{\mathbb X}$, $B(s,y,\omega)=B'(s,y,\omega)$ for $\Lambda\otimes\mathbb P$-almost every $(s,\omega)\in[0,T]\times\Omega$.
			Therefore, for each $(t,x)\in[0,T]\times{\mathbb X}$, we see by Tonelli's theorem that
			\begin{align*}
				&\mathbb E\left[\int_0^t\mathrm ds\int_{\mathbb X} G(s,y;t,x)\Absolute*{B(s,y)-B'(s,y)}m(\mathrm dy)\right]\\
				&\quad=\int_0^t\mathrm ds\int_{\mathbb X} G(s,y;t,x)\mathbb E\left[\Absolute*{B(s,y)-B'(s,y)}\right]m(\mathrm dy)=0,
			\end{align*}
			which implies  $\Psi_1(B')$ is a modification of $\Psi_1(B)$.

			Now suppose that $\Sigma'$ is a predictable modification of $\Sigma$, and let $\widetilde\Sigma(s,y):=\Sigma(s,y)-\Sigma'(s,y)$ for $(s,y)\in[0,T]\times{\mathbb X}$.
			For each $y\in{\mathbb X}$, Fubini's theorem gives
			\begin{align*}
				\Norm*{\widetilde\Sigma(r,y)}_{L^2_\Omega}=0,\qquad \text{for $\Lambda$-almost every $r\in[0,T]$}.
			\end{align*}
			Fix $(t,x)\in[0,T]\times{\mathbb X}$, and for $y,z\in{\mathbb X}$, define
			\begin{align}
				I_1(y,z;t,x)&:=\Parentheses*{\int_0^tG(r,y;t,x)G(r,z;t,x)\Norm*{\widetilde\Sigma(r,y)}_{L^2_\Omega}^2\mathrm dr}^{1/2},\\
				I_2(y,z;t,x)&:=\Parentheses*{\int_0^tG(r,y;t,x)G(r,z;t,x)\Norm*{\widetilde\Sigma(r,z)}_{L^2_\Omega}^2\mathrm dr}^{1/2}.
			\end{align}
			It follows that $I_1(y,z;t,x)=I_2(y,z;t,x)=0$ for every $y,z\in{\mathbb X}$.
			By Tonelli's theorem and the Cauchy--Schwarz inequality, we see
			\begin{align}
				&\int_0^t\Norm*{G(s,\cdot;t,x)\Norm*{\widetilde\Sigma(s,\cdot)}_{L^2_\Omega}}_{\mathcal H_K}^2\mathrm ds\\
				&=\int_0^t\iint_{{\mathbb X}^2}G(s,y;t,x)G(s,z;t,x)\Norm*{\widetilde\Sigma(s,y)}_{L^2_\Omega}\Norm*{\widetilde\Sigma(s,z)}_{L^2_\Omega}K(\mathrm dy,\mathrm dz)\mathrm ds\\
				&=\iint_{{\mathbb X}^2}\int_0^tG(s,y;t,x)G(s,z;t,x)\Norm*{\widetilde\Sigma(s,y)}_{L^2_\Omega}\Norm*{\widetilde\Sigma(s,z)}_{L^2_\Omega}\mathrm dsK(\mathrm dy,\mathrm dz)\\
				&\leq\iint_{{\mathbb X}^2}I_1(y,z;t,x)I_2(y,z;t,x)K(\mathrm dy,\mathrm dz)=0.
			\end{align}
			Therefore, by the linearity of the stochastic integral and Lemma \ref{cor:mtg+mink_cs},
			\begin{align*}
				\Norm*{\Psi_2(\Sigma)(t,x)-\Psi_2(\Sigma')(t,x)}_{L^2_\Omega}^2
				&=\Norm*{\iint_0^tG(s,y;t,x)\widetilde\Sigma(s,y)W(\mathrm ds,\mathrm dy)}_{L^2_\Omega}^2\\
				&\lesssim\int_0^t\Norm*{G(s,\cdot;t,x)\Norm*{\widetilde\Sigma(s,\cdot)}_{L^2_\Omega}}_{\mathcal H_K}^2\mathrm ds=0.
			\end{align*}
			Hence, $\Psi_2(\Sigma')$ is a modification of $\Psi_2(\Sigma)$.

Fix arbitrary $\lambda \in \mathbb{R}$ and $p \ge 1$, and observe that we may assume without loss of generality that $A = 0$. Clearly, $\Norm*{\cdot}_{\mathbb M^\sharp_{\lambda,p}}$ is a norm on $\mathbb M^\sharp_{\lambda,p}$, hence it is enough to show the space $(\mathbb M^\sharp_{\lambda,p}, \Norm*{\cdot}_{\mathbb M^\sharp_{\lambda,p}})$ is complete.

			\setcounter{step}{0}\refstepcounter{step}\emph{Step \thestep. }
			Suppose now $\{X^{(n)}\}_{n \in \mathbb N}$ is Cauchy in $(\mathbb M^\sharp_{\lambda,p}, \Norm*{\cdot}_{\mathbb M^\sharp_{\lambda,p}})$. Then there exists $\{X_n\}_{n \in \mathbb N}$ in $\mathbb M_{\lambda,p}$ so that 
			\begin{align}
				[X_n]_{\mathrm p} = X^{(n)} \qquad \text{ in }\mathbb M^\sharp_{\lambda,p},
			\end{align}
			and $\{X_n\}_{n \in \mathbb{N}}$ is Cauchy in $(\mathbb M_{\lambda,p},\Norm*{\cdot}_{\mathbb M_{\lambda,p}})$. We will first show the sequence $\{X_n\}_{n \in \mathbb N}$ has a predictable limit $X$ so that $\lim_{n \to \infty}\Norm*{X_n - X}_{\mathbb M_{\lambda, p}} = 0$.



			Let $\mathcal P_T:=\mathcal P|_{\Omega\times[0,T]}$, and equip $\widehat\Omega:=\Omega\times[0,T]$ with $\mathcal P_T$ and the probability measure $\widehat{\mathbb P}:=T^{-1}(\mathbb P\otimes\Lambda)|_{\mathcal P_T}$.
			For every $x\in{\mathbb X}$ and $n,m\in\mathbb{N}$, we have
			\begin{align*}
				\Norm*{X_n(\cdot,x)-X_m(\cdot,x)}_{L^p(\widehat{\mathbb P})}
				\leq h(x)^\lambda\Norm*{X_n-X_m}_{\mathbb M_{\lambda,p}}.
			\end{align*}
			Hence, for every fixed $x\in{\mathbb X}$, the sequence $\{X_n(\cdot,x)\}_{n\in\mathbb{N}}$ is Cauchy in $L^p(\widehat{\mathbb P})$ and therefore Cauchy in $\widehat{\mathbb P}$-probability.
			Regarding $x\in{\mathbb X}$ as a parameter, it follows from \cite[Lemma~5.6 and Corollary~5.33]{MR4226142} that there exists a $\mathcal P_T\otimes\mathscr B_{\mathbb X}$-measurable random field $X$ such that $X_n(\cdot,x)$ converges to $X(\cdot,x)$ in $\widehat{\mathbb P}$-probability for every $x\in{\mathbb X}$.
			In particular, $X$ is jointly predictable.

			\refstepcounter{step}\emph{Step \thestep. } We now prove that $X_n$ converges to $X$ in the $\Norm*{\cdot}_{\mathbb M_{\lambda,p}}$ norm.
			For $N\in\mathbb{N}$, set
			\begin{align*}
				r_N:=\sup_{n,m\geq N}\Norm*{X_n-X_m}_{\mathbb M_{\lambda,p}},
			\end{align*}
			so that $r_N\downarrow0$ as $N\to\infty$.
			Fix $x\in{\mathbb X}$ and $n\geq N$.
			By \cite[Lemma~5.2]{MR4226142}, there exists a subsequence $\{X_{m_k}(\cdot,x)\}_{k\in\mathbb{N}}$, with $m_k\geq N$, which converges to $X(\cdot,x)$ $\widehat{\mathbb P}$-almost surely.
			Therefore, Fubini's theorem and Fatou's lemma imply that, for $\Lambda$-almost every $t\in[0,T]$,
			\begin{align*}
				h(x)^{-p\lambda}\mathbb E\left[\Absolute*{X_n(t,x)-X(t,x)}^p\right]
				&\leq\liminf_{k\to\infty}h(x)^{-p\lambda}\mathbb E\left[\Absolute*{X_n(t,x)-X_{m_k}(t,x)}^p\right]\\
				&\leq r_N^p.
			\end{align*}
			Taking the $p$-th root, the essential supremum in $t$, and then the supremum in $x$, we obtain
			\begin{align*}
				\Norm*{X_n-X}_{\mathbb M_{\lambda,p}}\leq r_N,\qquad n\geq N.
			\end{align*}
			Since $r_N\to0$, it follows that $X\in\mathbb M_{\lambda,p}$ and $\lim_{n\to\infty}\Norm*{X_n-X}_{\mathbb M_{\lambda,p}}=0$.

			\refstepcounter{step}\emph{Step \thestep. } We see $[X]_{\mathrm p} \in \mathbb M_{\lambda,p}^\sharp$, and 
			\begin{align}
				\lim_{n \to \infty} \Norm*{X^{(n)}-[X]_{\mathrm p}}_{\mathbb M_{\lambda,p}^\sharp} &= \lim_{n \to \infty} \Norm*{[X_n]_{\mathrm p}-[X]_{\mathrm p}}_{\mathbb M_{\lambda,p}^\sharp} \\
				&=\lim_{n \to \infty}\Norm*{X_n - X}_{\mathbb M_{\lambda,p}}\\
				&=0,
			\end{align}
			which concludes the proof.

We first show that $(B_U, \Sigma_U)$ is a Duhamel-integrable pair.
		Note that the predictability of $B_U$ and $\Sigma_U$ is given by the fact that the coefficients $\sigma(t,x,u),\, b(t,x,u)$ are predictable functions on $\Omega\times\mathbb R_+\times{\mathbb X}\times\mathbb R$ by \eqref{eq:DC}--\eqref{eq:NC}, and $U(t,x)$ itself is a  predictable random field.
		Hence, it is enough to show for some $p \ge 2$ that
		\begin{align}\label{ineq:bcc D pair}
			\Norm*{\Norm*{G(\cdot,\cdot; t,x) B_U}_{L^1_{[0,T]}L_{\mathbb X}^1}}_{L^p_\Omega} + \Norm*{ \Norm*{G(\cdot,\cdot;t,x)\Sigma_U}_{L^2_{[0,T]}\mathcal H_K} }_{L^p_{\Omega}}<\infty.
		\end{align}
		Observe by Minkowski's inequality that it holds uniformly in $(t,x) \in [0,T]\times {\mathbb X}$ and $A \ge 1$ that
		\begin{align*}
			\Norm*{\Norm*{G(\cdot,\cdot; t,x) B_U}_{L^1_{[0,T]}L_{\mathbb X}^1}}_{L^p_\Omega}&\,\,=\Norm*{\int_0^t \mathrm ds \int_{\mathbb X}  G(s,y;t,x) |B_U(s,y)|m(\mathrm dy)}_{L^p_\Omega}\\
			&\,\,\le \int_0^t \mathrm ds  \int_{\mathbb X}  G(s,y;t,x) \Norm*{B_U(s,y)}_{L^p_\Omega}m(\mathrm dy)\\
			&\overset{\eqref{eq:LiG}}{\lesssim}\int_0^t \mathrm ds \int_{\mathbb X} G(s,y;t,x) \Parentheses*{1+\Norm*{U(s,y)}_{L^p_\Omega}} m(\mathrm dy)\\
			&\,\,\le \int_0^t\mathrm ds \int_{\mathbb X} e^{sA}G(s,y;t,x) h(y)^{\lambda} m(\mathrm dy) \Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda, p,A}}}\\
			&\overset{\text{Lemma~\ref{lem:hk longtime}, \eqref{ineq:hk_m long time}}}{\lesssim}h(x)^\lambda \Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}\int_0^t \mathrm ds \,e^{sA} \\
			&\,\,\le A^{-1} e^{At} h(x)^\lambda \Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}.
		\end{align*}


		Following the proof of Lemma \ref{cor:mtg+mink_cs}, we see it holds uniformly in $(t,x)\in [0,T]\times {\mathbb X}$ and $A \ge 0$ that 
		\begin{align*}
			\Norm*{\Norm*{G(\cdot,\cdot; t,x) \Sigma_U}_{L^2_{[0,T]}\mathcal H_K}}_{L^p_\Omega}^2 
			&\,\,\le \int_0^t \mathrm ds \Norm*{G(s,\cdot; t,x) \Norm*{\Sigma_U(s,\cdot)}_{L^{p}_\Omega} }_{\mathcal H_K}^2\\
			&\,\,=\int_0^t \mathrm ds \Norm*{G(s,\cdot; t,x) h(\cdot)^\lambda h(\cdot)^{-\lambda} \Norm*{\Sigma_U(s,\cdot)}_{L^{p}_\Omega} }_{\mathcal H_K}^2\\
			&\,\,\le \Norm*{\Sigma_U}_{\mathbb M_{\lambda, p,A}}^2\int_0^t\mathrm ds\, e^{2As}\Norm*{G(s,\cdot; t,x) h(\cdot)^\lambda}_{\mathcal H_K}^2  \\
			&\overset{\text{Lemma~\ref{lem:hk longtime}, \eqref{ineq:hk_k long time}}}{\lesssim} \Norm*{\Sigma_U}_{\mathbb M_{\lambda,p,A}}^2 h(x)^{2\lambda}\int_0^t\mathrm ds \, \Parentheses*{e^{2As} (t-s)^{-\widetilde\alpha}}.
		\end{align*}
		Note for every $\widetilde\alpha \in [0,1)$, it holds uniformly in $A,t >0$ that 
		\begin{align*}
			\int_0^t e^{2As}(t-s)^{-\widetilde\alpha} \mathrm ds  \lesssim A^{\widetilde\alpha - 1} e^{2At}.
		\end{align*}
		Hence it holds uniformly in $(t,x) \in [0,T]\times {\mathbb X}$ and $A \ge 1$ that 
		\begin{align*}
			\Norm*{\Norm*{G(\cdot,\cdot;t,x) \Sigma_U}_{L^2_{[0,T]}\mathcal H_K}}_{L^p_\Omega} \lesssim  A^\frac{\widetilde\alpha -1}{2}e^{A t}\Norm*{\Sigma_U}_{\mathbb M_{\lambda,p,A}} h(x)^\lambda \lesssim A^\frac{\widetilde\alpha - 1}{2} e^{At} h(x)^\lambda\Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}.
		\end{align*}
		Hence \eqref{ineq:bcc D pair} holds. More precisely, for each $p \ge 2$, the following inequality holds uniformly in $A \ge 1$ and $(t,x) \in [0,T]\times {\mathbb X}$ 
		\begin{align}\label{ineq:bcc D pair explicit}
			&\Norm*{\Norm*{G(\cdot,\cdot; t,x) B_U}_{L^1_{[0,T]}L_{\mathbb X}^1}}_{L^p_\Omega} + \Norm*{ \Norm*{G(\cdot,\cdot;t,x)\Sigma_U}_{L^2_{[0,T]}\mathcal H_K} }_{L^p_{\Omega}}\\
			\lesssim & A^{\frac{\widetilde\alpha - 1}{2}}h(x)^\lambda e^{A t} \Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda, p,A}}}.
		\end{align}


		We next show that $\Psi(g,B_U,\Sigma_U)$ admits a predictable modification in $\mathbb M_{\lambda,p}$.

		We first verify predictability. By \eqref{cond:ctem continuous}, $\Psi_0(g)$ is deterministic and jointly continuous.
		For $n\in\mathbb{N}$, let $\delta_n:=2^{-n}T$ and define $\Psi^{(n)}(0,x):=g(x)$. For $t\in(j\delta_n,(j+1)\delta_n]$, where $j=0,\ldots,2^n-1$, set
		\begin{align}\label{eq:predictable_approximation}
			\Psi^{(n)}(t,x)
			&:=(P_t^*g)(x)+\int_0^{j\delta_n}\mathrm ds\int_{\mathbb X} G(s,y;t,x)B_U(s,y)m(\mathrm dy)\\
			&\qquad+\iint_0^{j\delta_n}G(s,y;t,x)\Sigma_U(s,y)W(\mathrm ds,\mathrm dy).
		\end{align}

		Set $S:=(j\delta_n,(j+1)\delta_n]\times{\mathbb X}$. The drift integral in the definition of $\Psi^{(n)}(t,x)$ has an $\mathscr F_{j\delta_n}\otimes\mathscr B(S)$-measurable version. The stochastic integral vanishes when $j=0$, so suppose that $j\ge1$.

		By Lemma \ref{lem:H0}, the standard elementary predictable approximations of $G(\cdot,\cdot;t,x)\Sigma_U$ on $[0,j\delta_n]$, using  finite-dimensional projections, can be chosen jointly measurable in $(t,x)\in S$. 
		Hence, by \cite[Corollary~5.33]{MR4226142}, the third term on the right hand side of \eqref{eq:predictable_approximation} 
		has an $\mathscr F_{j\delta_n}\otimes\mathscr B(S)$-measurable version.
		Since $\mathscr F_{j\delta_n}\otimes\mathscr B((j\delta_n,(j+1)\delta_n])\subset\mathcal P_T$ on $(j\delta_n,(j+1)\delta_n]$, patching the measurable versions of the drift and stochastic integrals over these time intervals, together with the deterministic term $(P_t^*g)(x)$ and the value $g(x)$ at $t=0$, gives a $\mathcal P_T\otimes\mathscr B_{\mathbb X}$-measurable version of $\Psi^{(n)}$, where $\mathcal P_T:=\mathcal P|_{\Omega\times[0,T]}$. We use this predictable version of $\Psi^{(n)}$ below.

		By Minkowski's inequality and Lemma \ref{cor:mtg+mink_cs}, using \eqref{eq:LiG} and \eqref{ineq:hk_m long time}--\eqref{ineq:hk_k long time}, we have, uniformly in $n\in\mathbb{N}$,
		\begin{align*}
			\Norm*{\Psi^{(n)}}_{\mathbb M_{\lambda,p}}
			\lesssim \Norm*{g}_{(\lambda)}+1+\Norm*{U}_{\mathbb M_{\lambda,p}}<\infty.
		\end{align*}
		Together with the predictability established above, this proves that $\Psi^{(n)}\in\mathbb M_{\lambda,p}$.

		For $t\in(j\delta_n,(j+1)\delta_n]$, \eqref{eq:Psi} and \eqref{eq:predictable_approximation} give
		\begin{align*}
			\Psi(g,B_U,\Sigma_U)(t,x)-\Psi^{(n)}(t,x)
			&=\int_{j\delta_n}^t\mathrm ds\int_{\mathbb X} G(s,y;t,x)B_U(s,y)m(\mathrm dy)\\
			&\qquad\quad+\iint_{j\delta_n}^tG(s,y;t,x)\Sigma_U(s,y)W(\mathrm ds,\mathrm dy).
		\end{align*}
		By \eqref{eq:LiG}, Minkowski's inequality, Lemma \ref{cor:mtg+mink_cs}, and \eqref{ineq:hk_m long time}--\eqref{ineq:hk_k long time}, it follows uniformly in $n\in\mathbb{N}$, $A\geq1$, and $(t,x)\in(0,T]\times{\mathbb X}$ that
		\begin{align*}
			&e^{-At}h(x)^{-\lambda}\Norm*{\Psi^{(n)}(t,x)-\Psi(g,B_U,\Sigma_U)(t,x)}_{L^p_\Omega}\\
			&\lesssim\Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}
			\left[\int_{j\delta_n}^t e^{-A(t-s)}\mathrm ds
			+\left(\int_{j\delta_n}^t e^{-2A(t-s)}(t-s)^{-\widetilde\alpha}\mathrm ds\right)^{1/2}\right]\\
			&\lesssim\Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}\left(\delta_n+\delta_n^{(1-\widetilde\alpha)/2}\right).
		\end{align*}
		The last inequality uses $0<t-j\delta_n\le\delta_n$ and $\widetilde\alpha<1$. The estimate also holds at $t=0$, since both random fields equal $g(x)$. 
		Since $\sum_{n\in\mathbb{N}}(\delta_n+\delta_n^{(1-\widetilde\alpha)/2})<\infty$, we see $\Psi^{(n)}(t,x)$ converges almost surely to $\Psi(g,B_U,\Sigma_U)(t,x)$. Taking the pointwise limit of $\Psi^{(n)}$ wherever it exists and is finite, and setting the field equal to zero elsewhere, yields a $\mathcal P_T\otimes\mathscr B_{\mathbb X}$-measurable modification of $\Psi(g,B_U,\Sigma_U)$ whose value at $t=0$ is $g(x)$. We use this modification below without changing notation.

		It remains to bound $\Norm*{\Psi(g,B_U,\Sigma_U)}_{\mathbb M_{\lambda,p}}$. For $p\ge2$, the following estimate holds uniformly in $(t,x)\in[0,T]\times{\mathbb X}$ and $A\ge1$:
		\begin{align*}
			&\Norm*{\Psi(g,B_U,\Sigma_U)(t,x)}_{L^p_\Omega}\\
			&\quad\lesssim \Absolute*{P^*_t g(x)} +\Norm*{\Norm*{G(\cdot,\cdot; t,x) B_U}_{L^1_{[0,T]}L_{\mathbb X}^1}}_{L^p_\Omega}+ \Norm*{ \Norm*{G(\cdot,\cdot;t,x)\Sigma_U}_{L^2_{[0,T]}\mathcal H_K} }_{L^p_{\Omega}}\\
			&\quad\overset{\text{Lemma~\ref{lem:hk longtime}, \eqref{ineq:hk_m long time}},\eqref{ineq:bcc D pair explicit}}{\lesssim} h(x)^\lambda + \Parentheses*{A^\frac{\widetilde\alpha-1}{2}e^{At}} h(x)^\lambda  \Parentheses*{1+\Norm*{U}_{\mathbb M_{\lambda,p,A}}}.
		\end{align*}
		Taking $A=1$ in this estimate gives $\Norm*{\Psi(g,B_U,\Sigma_U)}_{\mathbb M_{\lambda,p}}<\infty$.

		Finally, to prove the difference estimate, we write
		\begin{align*}
			\Psi(g,B_U,\Sigma_U) - \Psi(g,B_V,\Sigma_V) &= \int_0^t\mathrm ds  \int_{\mathbb X}  G(s,y; t,x) \widetilde B_{U - V}(s,y) m(\mathrm dy)\\
			&\qquad + \iint_0^t G(s,y; t,x) \widetilde \Sigma_{U - V}(s,y) W(\mathrm ds,\mathrm dy),
		\end{align*}
		where 
		\begin{gather*}
			\widetilde B_{X}(s,y):= \widetilde b(s,y,X(s,y)):=b(s,y,X(s,y)+V(s,y)) - b(s,y,V(s,y)),\\ \widetilde \Sigma _{X}(s,y):= \widetilde\sigma(s,y,X(s,y)):=\sigma(s,y,X(s,y)+V(s,y)) - \sigma(s,y,V(s,y)).
		\end{gather*}
		We see $\widetilde b$ and $\widetilde \sigma$ satisfy \eqref{ineq:g_lip} and 
		\begin{align*}
			|\widetilde b(t,x,u)| + |\widetilde \sigma(t,x,u)| \lesssim |u|,\qquad \text{ uniformly in } (t,x,u) \in [0,T]\times {\mathbb X} \times  \mathbb{R}.
		\end{align*}
		Hence, by repeating the above argument, we see it holds uniformly in $(t,x) \in [0,T]\times {\mathbb X}$ and $A \ge 1$ that
		\begin{align*}
			\Norm*{\Psi(g,B_U,\Sigma_U)(t,x) - \Psi(g,B_V,\Sigma_V)(t,x)}_{L^p_\Omega} \lesssim \Parentheses*{A^\frac{\widetilde\alpha - 1}{2} e^{At} } h(x)^\lambda \Norm*{U - V}_{\mathbb M_{\lambda,p,A}},
		\end{align*}
		which implies the desired inequality.

(1) Let $t>0$, $\varepsilon \in (0,1]$ and $x \in {\mathbb X}$. We see by Lemma \ref{lem:H0}, Lemma \ref{lem:hk longtime} and {Jensen's} inequality that uniformly in $x \in {\mathbb X}$, $t >0 $ and $\varepsilon \in (0,1]$,
		\begin{align}
			\|r_t^\varepsilon(\cdot,x)\|_{\mathcal H_K}^2 &\le \left(e^{-t/\varepsilon} \sum_{n = 1}^\infty \frac{(t/\varepsilon)^n}{n!}\|G(n\varepsilon,\cdot,x)\|_{\mathcal H_K} \right)^2\\
			&\,\,\le e^{-t/\varepsilon} \sum_{n = 1}^\infty \frac{(t/\varepsilon)^n}{n!} \|G(n\varepsilon,\cdot,x)\|_{\mathcal H_K}^2\\
			&\overset{\eqref{ineq:hk_k long time}}{\lesssim} e^{-t/\varepsilon} \sum_{n = 1}^\infty \frac{(t/\varepsilon)^n}{n!} (n\varepsilon)^{-\alpha} e^{\kappa \varepsilon n}\\
			&\,\, =\exp \left(t\left(e^{\kappa \varepsilon} - 1 \right) /\varepsilon \right) e^{-te^{\kappa \varepsilon}/\varepsilon} \sum_{n = 1}^\infty \frac{\left(e^{\kappa \varepsilon}t/ \varepsilon\right)^n}{n!} (n\varepsilon)^{-\alpha},
		\end{align}
		for some $\alpha \in (0,1)$. Hence, by {Jensen's} inequality,
		\begin{align}
			e^{-te^{\kappa \varepsilon}/\varepsilon} \sum_{n = 1}^\infty \frac{\left(e^{\kappa \varepsilon}t/ \varepsilon\right)^n}{n!} (n\varepsilon)^{-\alpha} &\le \left (e^{-t e^{\kappa \varepsilon}/\varepsilon} \sum_{n = 1}^\infty \frac{(e^{\kappa \varepsilon}t/\varepsilon)^{n}}{n!} (n\varepsilon)^{-1} \right)^{\alpha}\\
			&{\le}\left(e^{-te^{\kappa \varepsilon}/\varepsilon}\sum_{n=1}^\infty \frac{\left(e^{\kappa \varepsilon}t/\varepsilon \right)^{n+1}}{(n+1)!} \frac{n+1}{n}t^{-1}\right)^\alpha \\
			& \le 2^\alpha t^{-\alpha}.
		\end{align}
		Finally, observe that there is $\kappa' \in \mathbb{R}$ so that for $t \ge 0$,
		\begin{align}
			\sup_{ \varepsilon \in (0,1]} \exp \left(t \left(e^{\kappa \varepsilon} - 1 \right) /\varepsilon\right) \le  e^{\kappa ' t}.
		\end{align}
		Collecting all terms, we see it holds uniformly in $x \in {\mathbb X}$, $t >0$ and $\varepsilon \in (0,1]$ that
		\begin{align}
			\|r_t^\varepsilon(\cdot,x)\|_{\mathcal H_K }^2 \lesssim e^{\kappa' t} t^{-\alpha}
		\end{align}
		for some $\kappa ' \in \mathbb{R}$. Moreover, by Lemma \ref{lem:hk longtime}, there exists $\kappa'' \in \mathbb{R}$ so that for $t>0$, $\varepsilon \in (0,1]$ and $x \in {\mathbb X}$, it holds uniformly in $x \in {\mathbb X}$, $t >0 $ and $\varepsilon \in (0,1]$ that
		\begin{align}
			\|r_t^\varepsilon(\cdot,x)\|_{L^1_{\mathbb X}}
			&\le e^{-t/\varepsilon}\sum_{n=1}^\infty \frac{(t/\varepsilon)^n}{n!}
			\|G_{n\varepsilon}(\cdot,x)\|_{L^1_{\mathbb X}}\\
			&\lesssim e^{-t/\varepsilon}\sum_{n=1}^\infty \frac{(t/\varepsilon)^n}{n!}e^{\kappa n\varepsilon}
			\le \exp\left(t\frac{e^{\kappa\varepsilon}-1}{\varepsilon}\right)
			\lesssim e^{\kappa''t},
		\end{align}
		Since $1\lesssim t^{-\alpha}e^t$ for $t>0$, enlarging the exponential constant if necessary proves both bounds in \eqref{ineq:R_bound} with a single $\kappa$ independent of $\varepsilon$.

		(2) The objective is to show
		\begin{align}\label{lim:sup_cov}
			\lim_{\varepsilon \downarrow 0} \sup_{x\in {\mathbb X}} \int_0^t \left\|{\Absolute*{\int_{\mathbb X} r_{t-s}^\varepsilon(y,x)G_\varepsilon(\cdot,y)m(\mathrm dy) - G(t-s,\cdot,x)}}\right\|^2_{\mathcal H_K}\,\mathrm ds {=} 0.
		\end{align}
		For $t>0$, by Lemma \ref{lem:H0} and {Jensen's} inequality, it holds uniformly in $x \in {\mathbb X}$ that
		\begin{align}
			&\int_0^t \left\|{\Absolute*{\int_{\mathbb X} r_{t-s}^\varepsilon({y,x}) G_\varepsilon({\cdot,y}) m(\mathrm dy) - G(t-s,\cdot,x)}}\right\|^2_{\mathcal H_K} \mathrm ds\\
			\overset{\text{Lemma~\ref{lem:hk longtime}, \eqref{ineq:hk_k long time}}}{\lesssim}& \int_0^t  \left\|e^{-(t-s)/\varepsilon}\sum_{n = 1}^\infty \frac{((t-s)/\varepsilon)^n}{n!} {\Absolute*{G((n+1)\varepsilon,\cdot,x) - G(t-s, \cdot,x)}}\right\|^2_{\mathcal H_K } \mathrm ds\\
			&\qquad + \int_0^t e^{-2(t-s)/\varepsilon} (t-s)^{-\alpha} \mathrm ds\\
			\le \,\,\,&\int_0^t e^{-(t-s)/\varepsilon} \sum_{n = 1}^\infty \frac{\left(\frac{t-s}{\varepsilon}\right)^n}{n!} \left\|{\Absolute*{G(\varepsilon(n+1),\cdot,x) - G(t-s,\cdot,x)}}\right\|^2_{\mathcal H_K } \mathrm ds +  \int_0^t e^{-2s/\varepsilon} s^{-\alpha} \mathrm ds\\
			=: \,\,&\int_0^t {\left(I_{1,T}(t-s,x,\varepsilon)+I_{2,T}(t-s,x,\varepsilon)\right)} \mathrm ds +\int_0^t e^{-2s/\varepsilon} s^{-\alpha} \mathrm ds,
		\end{align}
		where we used {Jensen's} inequality and Lemma \ref{lem:H0} in the second inequality and
		\begin{gather*}
			I_{1,T}(t-s,x,\varepsilon) :=e^{-(t-s)/\varepsilon}{\sum_{n\varepsilon > T+1}} \frac{\left(\frac{t-s}{\varepsilon}\right)^n}{n!} \left\|{\Absolute*{G(\varepsilon(n+1),\cdot,x) - G(t-s,\cdot,x)}}\right\|^2_{\mathcal H_K }{,}\\
			I_{2,T}(t-s,x,\varepsilon):= e^{-(t-s)/\varepsilon}\sum_{\substack{\\n \varepsilon \le T+1}}\frac{\left(\frac{t-s}{\varepsilon}\right)^n}{n!} \left\|{\Absolute*{G(\varepsilon(n+1),\cdot,x) - G(t-s,\cdot,x)}}\right\|^2_{\mathcal H_K }{.}
		\end{gather*}


		First, for an arbitrary but fixed $T>0$, it holds uniformly in $0 < s< t$  and $x \in {\mathbb X}$ that
		\begin{align}
			&e^{-(t-s)/\varepsilon}\sum_{n \varepsilon > T+1} \frac{\left( \frac{t-s}{\varepsilon}\right)^n}{n!} \left\|{\Absolute*{G\left(\varepsilon(n+1), \cdot, x \right)  - G(t-s, \cdot,x)}}\right\|_{\mathcal H_K }^2\\
			{\lesssim} &e^{-(t-s)/\varepsilon}\sum_{n \varepsilon > T+1} \frac{\left( \frac{t-s}{\varepsilon}\right)^n}{n!} \left(\left\|G\left(\varepsilon(n+1), \cdot, x \right)\right\|_{\mathcal H_K }^2 + \left\| G(t-s, \cdot,x)\right\|_{\mathcal H_K }^2\right)\\
			\lesssim& e^{-(t-s)/\varepsilon}\sum_{n\varepsilon>T+1} \frac{\left( \frac{t-s}{\varepsilon}\right)^n}{n!} \left((\varepsilon (n+1))^{-\alpha}e^{\kappa n\varepsilon} + (t-s)^{-\alpha}\right)\\
			\le & e^{-(t-s)/\varepsilon} \sum_{n \varepsilon >T+1} \frac{\left( \frac{t-s}{\varepsilon}e^{\kappa \varepsilon}\right)^n}{n!} T^{-\alpha} + e^{-(t-s)/\varepsilon} \sum_{n \varepsilon >T+1} \frac{\left( \frac{t-s}{\varepsilon}e^{\kappa \varepsilon}\right)^n}{n!}(t-s)^{-\alpha}\\
			= &{e^{(e^{\kappa \varepsilon}-1)(t-s)/\varepsilon}} \left(T^{-\alpha}+(t-s)^{-\alpha} \right)e^{- \frac{t-s}{\varepsilon}e^{\varepsilon \kappa }}\sum_{n\varepsilon>T+1}  \frac{\left( \frac{t-s}{\varepsilon}e^{\kappa \varepsilon}\right)^n}{n!}.
		\end{align}

		Let $\psi(u):= (1+u) \ln(u+1)- u$ for $u \ge 0$ and note that $\psi$ is an increasing function on $\mathbb{R}_+$. Hence, by {Bennett's inequality} for Poisson random variables, we see for sufficiently small $\varepsilon>0$ and $0<s<t\le T$,
